window.MESSER_EXAMS={"version":"1.8","sha256":"438b213ef975987ca88894c5e1fb6da80bfafa4e68fdc62dd00917478167e603","exams":{"A":[{"id":"A1","number":1,"page":10,"clip":[24,85.848,410,610],"text":"1\nPractice Exam A - Questions\nA1.\t Match the description with the most accurate attack type. \nNot all attack types will be used.\nAttack Types:\nOn-path\nRFID cloning\nKeylogger\nVishing\nRootkit\nDDoS\nInjection\nSupply chain\nAttacker accesses a database directly  \nfrom a web browser\nSelect an Attack Type\nAttacker intercepts all communication between \na client and a web server\nSelect an Attack Type\n  \nMultiple attackers \noverwhelm a web server\nSelect an Attack Type\nAnswer Page: 35\nAttacker obtains a list of all login credentials used  \nover the last 24 hours\nSelect an Attack Type\nAttacker obtains bank account number  \nand birth date by calling the victim\nSelect an Attack Type\n","choices":[],"correct":[],"answerPages":[44,45],"objectives":["2.2","2.3","2.4"]},{"id":"A2","number":2,"page":11,"clip":[24,29.063,410,610],"text":"2\nPractice Exam A - Questions\nA2.\t The security team at a manufacturing company is creating a set of \nsecurity standards for employees and visitors.  \n \nSelect the BEST security control for each location.  \nAll of the available security controls will be used once. \nAnswer Page: 37\nSecurity guard\nAuthentication token\nAccess badge\nLighting\nAccess control vestibule\nAvailable Security\n Controls:\nFencing\nBiometrics\nReception\nBuilding lobby\nData\nCenter\nDoor\nEntrance from\ninside building\nServer\nAdministration\nAuthentication to\nserver console\nin the data center\nLocation\nDescription\nSecurity Controls\nOutside\nBuilding\nParking and\nVisitor drop-off\n","choices":[],"correct":[],"answerPages":[46,47],"objectives":[]},{"id":"A3","number":3,"page":12,"clip":[24,29.063,410,275.971],"text":"A3.\t Select the most appropriate security category.  \nSome categories may be used more than once.\nAnswer Page: 39\nA guard checks the identification of all visitors\nAll returns must be approved by a Vice President\nA generator is used during a power outage\nBuilding doors can be unlocked with an access card\nSystem logs are transferred automatically to a SIEM\nManagerial\nOperational\nTechnical\nPhysical\n","choices":[],"correct":[],"answerPages":[48],"objectives":["1.1"]},{"id":"A4","number":4,"page":12,"clip":[24,277.971,410,610],"text":"3\nPractice Exam A - Questions\nA4.\t Match the appropriate authentication factor to each description.  \nEach authentication factor will be used once.\nAnswer Page: 40\nSomewhere you are\nSomething you have\nSomething you are\nSomething you know\nDuring the login process, your phone receives a \ntext message with a one-time passcode\nDescription\nAuthentication Factor\nYou enter your PIN to make \na deposit into an ATM\nYou can use your fingerprint to unlock \nthe door to the data center\nYour login will not work unless you are \nconnected to the VPN\n","choices":[],"correct":[],"answerPages":[49],"objectives":["4.6"]},{"id":"A5","number":5,"page":13,"clip":[24,29.063,410,610],"text":"4\nPractice Exam A - Questions\nA5.\t Configure the following stateful firewall rules: \n• Block HTTP sessions between the Web Server and the Database Server \n• Allow the Storage Server to transfer files to the Video Server over HTTPS \n• Allow the Management Server to use a secure terminal on the File Server\nInternet\nDMZ\nWeb Server\n10.1.1.2\nFile Server\n10.1.1.3\nStorage Server\n10.2.1.33\nManagement Server\n10.2.1.47\nVideo Server\n10.1.1.7\nDMZ\nSwitch\nInternal\nSwitch\nDatabase Server\n10.2.1.20\nInternal Network\nFirewall\nRule #\nSource IP\nDestination \nIP\nProtocol \n(TCP/UDP)\nPort #\nAllow/\nBlock\n1\n2\n3\nAnswer Page: 41\n","choices":[],"correct":[],"answerPages":[50,51],"objectives":[]},{"id":"A6","number":6,"page":14,"clip":[24,86.168,410,237.409],"text":"A6.\t A company has hired a third-party to gather information \nabout the company’s servers and data. This third-party \nwill not have direct access to the company's internal \nnetwork, but they can gather information from any other \nsource. Which of the following would BEST describe  \nthis approach?\n \n❍A. Vulnerability scanning\n \n❍B. Passive reconnaissance\n \n❍C. Supply chain analysis\n \n❍D. Regulatory audit\nQuick \nAnswer: 33\nThe Details: 43\n","choices":[{"letter":"A","text":"Vulnerability scanning"},{"letter":"B","text":"Passive reconnaissance"},{"letter":"C","text":"Supply chain analysis"},{"letter":"D","text":"Regulatory audit"}],"correct":["B"],"answerPages":[52],"objectives":["5.5"]},{"id":"A7","number":7,"page":14,"clip":[24,239.409,410,364.25],"text":"A7.\t A company's email server has received an email from a \nthird-party, but the origination server does not match the \nlist of authorized devices. Which of the following would \ndetermine the disposition of this message?\n \n❍A. SPF\n \n❍B. NAC\n \n❍C. DMARC\n \n❍D. DKIM\nQuick \nAnswer: 33\nThe Details: 44\n","choices":[{"letter":"A","text":"SPF"},{"letter":"B","text":"NAC"},{"letter":"C","text":"DMARC"},{"letter":"D","text":"DKIM"}],"correct":["C"],"answerPages":[53],"objectives":["4.5"]},{"id":"A8","number":8,"page":14,"clip":[24,366.25,410,464.691],"text":"A8.\t Which of these threat actors would be MOST likely to \nattack systems for direct financial gain?\n \n❍A. Organized crime\n \n❍B. Hacktivist\n \n❍C. Nation state\n \n❍D. Shadow IT\nQuick \nAnswer: 33\nThe Details: 45\n","choices":[{"letter":"A","text":"Organized crime"},{"letter":"B","text":"Hacktivist"},{"letter":"C","text":"Nation state"},{"letter":"D","text":"Shadow IT"}],"correct":["A"],"answerPages":[54],"objectives":["2.1"]},{"id":"A9","number":9,"page":14,"clip":[24,466.691,410,610],"text":"5\nPractice Exam A - Questions\nA9.\t A security administrator has examined a server recently \ncompromised by an attacker, and has determined the \nsystem was exploited due to a known operating system \nvulnerability. Which of the following would BEST \ndescribe this finding?\n \n❍A. Root cause analysis\n \n❍B. E-discovery\n \n❍C. Risk appetite\n \n❍D. Data subject\nQuick \nAnswer: 33\nThe Details: 46\n","choices":[{"letter":"A","text":"Root cause analysis"},{"letter":"B","text":"E-discovery"},{"letter":"C","text":"Risk appetite"},{"letter":"D","text":"Data subject"}],"correct":["A"],"answerPages":[55],"objectives":["4.8"]},{"id":"A10","number":10,"page":15,"clip":[24,29.063,410,145.203],"text":"A10.\tA city is building an ambulance service network for \nemergency medical dispatching. Which of the following \nshould have the highest priority?\n \n❍A. Integration costs\n \n❍B. Patch availability\n \n❍C. System availability\n \n❍D. Power usage\nQuick \nAnswer: 33\nThe Details: 47\n","choices":[{"letter":"A","text":"Integration costs"},{"letter":"B","text":"Patch availability"},{"letter":"C","text":"System availability"},{"letter":"D","text":"Power usage"}],"correct":["C"],"answerPages":[56],"objectives":["3.1"]},{"id":"A11","number":11,"page":15,"clip":[24,147.203,410,276.543],"text":"A11.\tA system administrator receives a text alert when access \nrights are changed on a database containing private \ncustomer information. Which of the following would \ndescribe this alert?\n \n❍A. Maintenance window\n \n❍B. Attestation and acknowledgment\n \n❍C. Automation\n \n❍D. External audit\nQuick \nAnswer: 33\nThe Details: 48\n","choices":[{"letter":"A","text":"Maintenance window"},{"letter":"B","text":"Attestation and acknowledgment"},{"letter":"C","text":"Automation"},{"letter":"D","text":"External audit"}],"correct":["C"],"answerPages":[57],"objectives":["5.4"]},{"id":"A12","number":12,"page":15,"clip":[24,278.543,410,610],"text":"6\nPractice Exam A - Questions\nA12.\tA security administrator is concerned about the potential \nfor data exfiltration using external storage drives. Which \nof the following would be the BEST way to prevent this \nmethod of data exfiltration?\n \n❍A. Create an operating system security policy  \nto block the use of removable media\n \n❍B. Monitor removable media usage in  \nhost-based firewall logs\n \n❍C. Only allow applications that do not use  \nremovable media\n \n❍D. Define a removable media block rule in the UTM\nQuick \nAnswer: 33\nThe Details: 49\n","choices":[{"letter":"A","text":"Create an operating system security policy to block the use of removable media"},{"letter":"B","text":"Monitor removable media usage in host-based firewall logs"},{"letter":"C","text":"Only allow applications that do not use removable media"},{"letter":"D","text":"Define a removable media block rule in the UTM"}],"correct":["A"],"answerPages":[58],"objectives":["2.2"]},{"id":"A13","number":13,"page":16,"clip":[24,29.063,410,145.203],"text":"A13.\tA company creates a standard set of government reports \neach calendar quarter. Which of the following would \ndescribe this type of data?\n \n❍A. Data in use\n \n❍B. Obfuscated\n \n❍C. Trade secrets\n \n❍D. Regulated\nQuick \nAnswer: 33\nThe Details: 50\n","choices":[{"letter":"A","text":"Data in use"},{"letter":"B","text":"Obfuscated"},{"letter":"C","text":"Trade secrets"},{"letter":"D","text":"Regulated"}],"correct":["D"],"answerPages":[59],"objectives":["3.3"]},{"id":"A14","number":14,"page":16,"clip":[24,147.203,410,610],"text":"7\nPractice Exam A - Questions\nA14.\tAn insurance company has created a set of policies to \nhandle data breaches. The security team has been given \nthis set of requirements based on these policies:\n• Access records from all devices must be  \nsaved and archived\n• Any data access outside of normal working hours  \nmust be immediately reported\n• Data access must only occur inside of the country\n• Access logs and audit reports must be created from a \nsingle database\nWhich of the following should be implemented by the \nsecurity team to meet these requirements? \n(Select THREE)\n \n❍A. Restrict login access by IP address and  \nGPS location\n \n❍B. Require government-issued identification  \nduring the onboarding process\n \n❍C. Add additional password complexity for accounts \nthat access data\n \n❍D. Conduct monthly permission auditing\n \n❍E. Consolidate all logs on a SIEM\n \n❍F. Archive the encryption keys of all disabled \naccounts\n \n❍G. Enable time-of-day restrictions on the \nauthentication server\nQuick \nAnswer: 33\nThe Details: 51\n","choices":[{"letter":"A","text":"Restrict login access by IP address and GPS location"},{"letter":"B","text":"Require government-issued identification during the onboarding process"},{"letter":"C","text":"Add additional password complexity for accounts that access data"},{"letter":"D","text":"Conduct monthly permission auditing"},{"letter":"E","text":"Consolidate all logs on a SIEM"},{"letter":"F","text":"Archive the encryption keys of all disabled accounts"},{"letter":"G","text":"Enable time-of-day restrictions on the authentication server"}],"correct":["A","E","G"],"answerPages":[60,61],"objectives":[]},{"id":"A15","number":15,"page":17,"clip":[24,29.063,410,216.843],"text":"A15.\tA security engineer is viewing this record from the \nfirewall logs:\nUTC 04/05/2023 03:09:15809   AV Gateway Alert \n136.127.92.171  80 -> 10.16.10.14  60818                            \nGateway Anti-Virus Alert: \nXPACK.A_7854 (Trojan) blocked.\nWhich of the following can be observed from this  \nlog information?\n \n❍A. The victim's IP address is 136.127.92.171\n \n❍B. A download was blocked from a web server\n \n❍C. A botnet DDoS attack was blocked\n \n❍D. The Trojan was blocked, but the file was not\nQuick \nAnswer: 33\nThe Details: 53\n","choices":[{"letter":"A","text":"The victim's IP address is 136.127.92.171"},{"letter":"B","text":"A download was blocked from a web server"},{"letter":"C","text":"A botnet DDoS attack was blocked"},{"letter":"D","text":"The Trojan was blocked, but the file was not"}],"correct":["B"],"answerPages":[62],"objectives":["4.9"]},{"id":"A16","number":16,"page":17,"clip":[24,218.843,410,412.983],"text":"A16.\tA user connects to a third-party website and receives this \nmessage: \n \nYour connection is not private.  \nNET::ERR_CERT_INVALID \n \nWhich of the following attacks would be the MOST \nlikely reason  \nfor this message?\n \n❍A. Brute force\n \n❍B. DoS\n \n❍C. On-path\n \n❍D. Deauthentication\nQuick \nAnswer: 33\nThe Details: 54\n","choices":[{"letter":"A","text":"Brute force"},{"letter":"B","text":"DoS"},{"letter":"C","text":"On-path"},{"letter":"D","text":"Deauthentication"}],"correct":["C"],"answerPages":[63],"objectives":["2.4"]},{"id":"A17","number":17,"page":17,"clip":[24,414.983,410,610],"text":"8\nPractice Exam A - Questions\nA17.\tWhich of the following would be the BEST way to \nprovide a website login using existing credentials from a \nthird-party site?\n \n❍A. Federation\n \n❍B. 802.1X\n \n❍C. EAP\n \n❍D. SSO\nQuick \nAnswer: 33\nThe Details: 55\n","choices":[{"letter":"A","text":"Federation"},{"letter":"B","text":"802.1X"},{"letter":"C","text":"EAP"},{"letter":"D","text":"SSO"}],"correct":["A"],"answerPages":[64],"objectives":["4.6"]},{"id":"A18","number":18,"page":18,"clip":[24,29.063,410,184.803],"text":"A18.\tA system administrator is working on a contract that will \nspecify a minimum required uptime for a set of Internet-\nfacing firewalls. The administrator needs to know how \noften the firewall hardware is expected to fail between \nrepairs. Which of the following would BEST describe \nthis information?\n \n❍A. MTBF\n \n❍B. RTO\n \n❍C. MTTR\n \n❍D. RPO\nQuick \nAnswer: 33\nThe Details: 56\n","choices":[{"letter":"A","text":"MTBF"},{"letter":"B","text":"RTO"},{"letter":"C","text":"MTTR"},{"letter":"D","text":"RPO"}],"correct":["A"],"answerPages":[65],"objectives":["5.2"]},{"id":"A19","number":19,"page":18,"clip":[24,186.803,410,342.543],"text":"A19.\tAn attacker calls into a company’s help desk \nand pretends to be the director of the company’s \nmanufacturing department. The attacker states that they \nhave forgotten their password and they need to have the \npassword reset quickly for an important meeting. What \nkind of attack would BEST describe this phone call?\n \n❍A. Social engineering\n \n❍B. Supply chain\n \n❍C. Watering hole\n \n❍D. On-path\nQuick \nAnswer: 33\nThe Details: 57\n","choices":[{"letter":"A","text":"Social engineering"},{"letter":"B","text":"Supply chain"},{"letter":"C","text":"Watering hole"},{"letter":"D","text":"On-path"}],"correct":["A"],"answerPages":[66],"objectives":["2.2"]},{"id":"A20","number":20,"page":18,"clip":[24,344.543,410,610],"text":"9\nPractice Exam A - Questions\nA20.\tTwo companies have been working together for a \nnumber of months, and they would now like to qualify \ntheir partnership with a broad formal agreement between \nboth organizations. Which of the following would \ndescribe this agreement? \n \n❍A. SLA\n \n❍B. SOW\n \n❍C. MOA\n \n❍D. NDA\nQuick \nAnswer: 33\nThe Details: 58\n","choices":[{"letter":"A","text":"SLA"},{"letter":"B","text":"SOW"},{"letter":"C","text":"MOA"},{"letter":"D","text":"NDA"}],"correct":["C"],"answerPages":[67],"objectives":["5.3"]},{"id":"A21","number":21,"page":19,"clip":[24,29.063,410,145.203],"text":"A21.\tWhich of the following would explain why a company \nwould automatically add a digital signature to each \noutgoing email message?\n \n❍A. Confidentiality\n \n❍B. Integrity\n \n❍C. Authentication\n \n❍D. Availability\nQuick \nAnswer: 33\nThe Details: 59\n","choices":[{"letter":"A","text":"Confidentiality"},{"letter":"B","text":"Integrity"},{"letter":"C","text":"Authentication"},{"letter":"D","text":"Availability"}],"correct":["B"],"answerPages":[68],"objectives":["1.2"]},{"id":"A22","number":22,"page":19,"clip":[24,147.203,410,304.571],"text":"A22.\tThe embedded OS in a company’s time clock appliance is \nconfigured to reset the file system and reboot when a file \nsystem error occurs. On one of the time clocks, this file \nsystem error occurs during the startup process and causes \nthe system to constantly reboot. Which of the following \nBEST describes this issue?\n \n❍A. Memory injection\n \n❍B. Resource consumption\n \n❍C. Race condition\n \n❍D. Malicious update\nQuick \nAnswer: 33\nThe Details: 60\n","choices":[{"letter":"A","text":"Memory injection"},{"letter":"B","text":"Resource consumption"},{"letter":"C","text":"Race condition"},{"letter":"D","text":"Malicious update"}],"correct":["C"],"answerPages":[69],"objectives":["2.3"]},{"id":"A23","number":23,"page":19,"clip":[24,306.571,410,610],"text":"10\nPractice Exam A - Questions\nA23.\tA recent audit has found that existing password policies \ndo not include any restrictions on password attempts, \nand users are not required to periodically change their \npasswords. Which of the following would correct these \npolicy issues? (Select TWO)\n \n❍A. Password complexity\n \n❍B. Password expiration\n \n❍C. Password reuse\n \n❍D. Account lockout\n \n❍E. Password managers\nQuick \nAnswer: 33\nThe Details: 61\n","choices":[{"letter":"A","text":"Password complexity"},{"letter":"B","text":"Password expiration"},{"letter":"C","text":"Password reuse"},{"letter":"D","text":"Account lockout"},{"letter":"E","text":"Password managers"}],"correct":["B","D"],"answerPages":[70],"objectives":["4.6"]},{"id":"A24","number":24,"page":20,"clip":[24,29.383,410,164.487],"text":"A24.\tWhat kind of security control is associated with  \na login banner?\n \n❍A. Preventive\n \n❍B. Deterrent \n \n❍C. Corrective\n \n❍D. Detective\n \n❍E. Compensating\n \n❍F. Directive\nQuick \nAnswer: 33\nThe Details: 62\n","choices":[{"letter":"A","text":"Preventive"},{"letter":"B","text":"Deterrent"},{"letter":"C","text":"Corrective"},{"letter":"D","text":"Detective"},{"letter":"E","text":"Compensating"},{"letter":"F","text":"Directive"}],"correct":["B"],"answerPages":[71],"objectives":["1.1"]},{"id":"A25","number":25,"page":20,"clip":[24,166.487,410,309.027],"text":"A25.\tAn internal audit has discovered four servers that have \nnot been updated in over a year, and it will take two \nweeks to test and deploy the latest patches. Which of  \nthe following would be the best way to quickly  \nrespond to this situation in the meantime?\n \n❍A. Purchase cybersecurity insurance\n \n❍B. Implement an exception for all data center services\n \n❍C. Move the servers to a protected segment\n \n❍D. Hire a third-party to perform an extensive audit\nQuick \nAnswer: 33\nThe Details: 63\n","choices":[{"letter":"A","text":"Purchase cybersecurity insurance"},{"letter":"B","text":"Implement an exception for all data center services"},{"letter":"C","text":"Move the servers to a protected segment"},{"letter":"D","text":"Hire a third-party to perform an extensive audit"}],"correct":["C"],"answerPages":[72],"objectives":["4.3"]},{"id":"A26","number":26,"page":20,"clip":[24,311.027,410,433.646],"text":"A26.\tA business manager is documenting a set of steps for \nprocessing orders if the primary Internet connection fails. \nWhich of these would BEST describe these steps?\n \n❍A. Platform diversity\n \n❍B. Continuity of operations\n \n❍C. Cold site recovery\n \n❍D. Tabletop exercise\nQuick \nAnswer: 33\nThe Details: 64\n","choices":[{"letter":"A","text":"Platform diversity"},{"letter":"B","text":"Continuity of operations"},{"letter":"C","text":"Cold site recovery"},{"letter":"D","text":"Tabletop exercise"}],"correct":["B"],"answerPages":[73],"objectives":["3.4"]},{"id":"A27","number":27,"page":20,"clip":[24,435.646,410,610],"text":"11\nPractice Exam A - Questions\nA27.\tA company would like to examine the credentials of each \nindividual entering the data center building. Which of \nthe following would BEST facilitate this requirement?\n \n❍A. Access control vestibule\n \n❍B. Video surveillance\n \n❍C. Pressure sensors\n \n❍D. Bollards\nQuick \nAnswer: 33\nThe Details: 65\n","choices":[{"letter":"A","text":"Access control vestibule"},{"letter":"B","text":"Video surveillance"},{"letter":"C","text":"Pressure sensors"},{"letter":"D","text":"Bollards"}],"correct":["A"],"answerPages":[74],"objectives":["1.2"]},{"id":"A28","number":28,"page":21,"clip":[24,29.063,410,158.403],"text":"A28.\tA company stores some employee information in \nencrypted form, but other public details are stored as \nplaintext. Which of the following would BEST describe \nthis encryption strategy?\n \n❍A. Full-disk\n \n❍B. Record\n \n❍C. Asymmetric\n \n❍D. Key escrow\nQuick \nAnswer: 33\nThe Details: 66\n","choices":[{"letter":"A","text":"Full-disk"},{"letter":"B","text":"Record"},{"letter":"C","text":"Asymmetric"},{"letter":"D","text":"Key escrow"}],"correct":["B"],"answerPages":[75],"objectives":["1.4"]},{"id":"A29","number":29,"page":21,"clip":[24,160.403,410,283.022],"text":"A29.\tA company would like to minimize database corruption \nif power is lost to a server. Which of the following would \nbe the BEST strategy to follow?\n \n❍A. Encryption\n \n❍B. Off-site backups\n \n❍C. Journaling\n \n❍D. Replication\nQuick \nAnswer: 33\nThe Details: 67\n","choices":[{"letter":"A","text":"Encryption"},{"letter":"B","text":"Off-site backups"},{"letter":"C","text":"Journaling"},{"letter":"D","text":"Replication"}],"correct":["C"],"answerPages":[76],"objectives":["3.4"]},{"id":"A30","number":30,"page":21,"clip":[24,285.022,410,610],"text":"12\nPractice Exam A - Questions\nA30.\tA company is creating a security policy for corporate \nmobile devices:\n• All mobile devices must be automatically locked after a \npredefined time period. \n• The location of each device needs to be traceable.\n• All of the user’s information should be completely \nseparate from company data.\nWhich of the following would be the BEST way to \nestablish these security policy rules?\n \n❍A. Segmentation\n \n❍B. Biometrics\n \n❍C. COPE\n \n❍D. MDM\nQuick \nAnswer: 33\nThe Details: 68\n","choices":[{"letter":"A","text":"Segmentation"},{"letter":"B","text":"Biometrics"},{"letter":"C","text":"COPE"},{"letter":"D","text":"MDM"}],"correct":["D"],"answerPages":[77],"objectives":["4.1"]},{"id":"A31","number":31,"page":22,"clip":[24,29.063,410,171.603],"text":"A31.\tA security engineer runs a monthly vulnerability scan. \nThe scan doesn’t list any vulnerabilities for Windows \nservers, but a significant vulnerability was announced last \nweek and none of the servers are patched yet. Which of \nthe following best describes this result?\n \n❍A. Exploit\n \n❍B. Compensating controls\n \n❍C. Zero-day attack\n \n❍D. False negative\nQuick \nAnswer: 33\nThe Details: 69\n","choices":[{"letter":"A","text":"Exploit"},{"letter":"B","text":"Compensating controls"},{"letter":"C","text":"Zero-day attack"},{"letter":"D","text":"False negative"}],"correct":["D"],"answerPages":[78],"objectives":["4.3"]},{"id":"A32","number":32,"page":22,"clip":[24,173.603,410,292.614],"text":"A32.\tAn IT help desk is using automation to improve the \nresponse time for security events. Which of the following \nuse cases would apply to this process?\n \n❍A. Escalation\n \n❍B. Guard rails\n \n❍C. Continuous integration\n \n❍D. Resource provisioning\nQuick \nAnswer: 33\nThe Details: 70\n","choices":[{"letter":"A","text":"Escalation"},{"letter":"B","text":"Guard rails"},{"letter":"C","text":"Continuous integration"},{"letter":"D","text":"Resource provisioning"}],"correct":["A"],"answerPages":[79],"objectives":["4.7"]},{"id":"A33","number":33,"page":22,"clip":[24,294.614,410,437.154],"text":"A33.\tA network administrator would like each user to \nauthenticate with their corporate username and \npassword when connecting to the company's wireless \nnetwork. Which of the following should the network \nadministrator configure on the wireless access points?\n \n❍A. WPA3\n \n❍B. 802.1X\n \n❍C. PSK\n \n❍D. MFA\nQuick \nAnswer: 33\nThe Details: 71\n","choices":[{"letter":"A","text":"WPA3"},{"letter":"B","text":"802.1X"},{"letter":"C","text":"PSK"},{"letter":"D","text":"MFA"}],"correct":["B"],"answerPages":[80],"objectives":["3.2"]},{"id":"A34","number":34,"page":22,"clip":[24,439.154,410,610],"text":"13\nPractice Exam A - Questions\nA34.\tA company's VPN service performs a posture assessment \nduring the login process. Which of the following \nmitigation techniques would this describe?\n \n❍A. Encryption\n \n❍B. Decommissioning\n \n❍C. Least privilege\n \n❍D. Configuration enforcement\nQuick \nAnswer: 33\nThe Details: 72\n","choices":[{"letter":"A","text":"Encryption"},{"letter":"B","text":"Decommissioning"},{"letter":"C","text":"Least privilege"},{"letter":"D","text":"Configuration enforcement"}],"correct":["D"],"answerPages":[81],"objectives":["2.5"]},{"id":"A35","number":35,"page":23,"clip":[24,29.063,410,178.082],"text":"A35.\tA user has assigned individual rights and permissions \nto a file on their network drive. The user adds three \nadditional individuals to have read-only access to the \nfile. Which of the following would describe this access \ncontrol model?\n \n❍A. Discretionary \n \n❍B. Mandatory\n \n❍C. Attribute-based\n \n❍D. Role-based\nQuick \nAnswer: 33\nThe Details: 73\n","choices":[{"letter":"A","text":"Discretionary"},{"letter":"B","text":"Mandatory"},{"letter":"C","text":"Attribute-based"},{"letter":"D","text":"Role-based"}],"correct":["A"],"answerPages":[82],"objectives":["4.6"]},{"id":"A36","number":36,"page":23,"clip":[24,180.082,410,296.222],"text":"A36.\tA remote user has received a text message with a link to \nlogin and confirm their upcoming work schedule. Which \nof the following would BEST describe this attack?\n \n❍A. Brute force\n \n❍B. Watering hole\n \n❍C. Typosquatting\n \n❍D. Smishing\nQuick \nAnswer: 33\nThe Details: 74\n","choices":[{"letter":"A","text":"Brute force"},{"letter":"B","text":"Watering hole"},{"letter":"C","text":"Typosquatting"},{"letter":"D","text":"Smishing"}],"correct":["D"],"answerPages":[83],"objectives":["2.2"]},{"id":"A37","number":37,"page":23,"clip":[24,298.222,410,420.841],"text":"A37.\tA company is formalizing the design and deployment \nprocess used by their application programmers. Which of \nthe following policies would apply?\n \n❍A. Business continuity\n \n❍B. Acceptable use policy\n \n❍C. Incident response\n \n❍D. Development lifecycle\nQuick \nAnswer: 33\nThe Details: 75\n","choices":[{"letter":"A","text":"Business continuity"},{"letter":"B","text":"Acceptable use policy"},{"letter":"C","text":"Incident response"},{"letter":"D","text":"Development lifecycle"}],"correct":["D"],"answerPages":[84],"objectives":["5.1"]},{"id":"A38","number":38,"page":23,"clip":[24,422.841,410,610],"text":"14\nPractice Exam A - Questions\nA38.\tA security administrator has copied a suspected malware \nexecutable from a user's computer and is running the \nprogram in a sandbox. Which of the following would \ndescribe this part of the incident response process?\n \n❍A. Eradication\n \n❍B. Preparation\n \n❍C. Recovery\n \n❍D. Containment\nQuick \nAnswer: 33\nThe Details: 76\n","choices":[{"letter":"A","text":"Eradication"},{"letter":"B","text":"Preparation"},{"letter":"C","text":"Recovery"},{"letter":"D","text":"Containment"}],"correct":["D"],"answerPages":[85],"objectives":["4.8"]},{"id":"A39","number":39,"page":24,"clip":[24,29.063,410,184.803],"text":"A39.\tA server administrator at a bank has noticed a decrease \nin the number of visitors to the bank's website. \nAdditional research shows that users are being directed \nto a different IP address than the bank's web server. \nWhich of the following would MOST likely describe \nthis attack?\n \n❍A. Deauthentication\n \n❍B. DDoS\n \n❍C. Buffer overflow\n \n❍D. DNS poisoning\nQuick \nAnswer: 33\nThe Details: 77\n","choices":[{"letter":"A","text":"Deauthentication"},{"letter":"B","text":"DDoS"},{"letter":"C","text":"Buffer overflow"},{"letter":"D","text":"DNS poisoning"}],"correct":["D"],"answerPages":[86],"objectives":["2.4"]},{"id":"A40","number":40,"page":24,"clip":[24,186.803,410,289.743],"text":"A40.\tWhich of the following considerations are MOST \ncommonly associated with a hybrid cloud model?\n \n❍A. Microservice outages\n \n❍B. IoT support\n \n❍C. Network protection mismatches\n \n❍D. Containerization backups\nQuick \nAnswer: 33\nThe Details: 78\n","choices":[{"letter":"A","text":"Microservice outages"},{"letter":"B","text":"IoT support"},{"letter":"C","text":"Network protection mismatches"},{"letter":"D","text":"Containerization backups"}],"correct":["C"],"answerPages":[87],"objectives":["3.1"]},{"id":"A41","number":41,"page":24,"clip":[24,291.743,410,610],"text":"15\nPractice Exam A - Questions\nA41.\tA company hires a large number of seasonal employees, \nand their system access should normally be disabled \nwhen the employee leaves the company. The security \nadministrator would like to verify that their systems \ncannot be accessed by any of the former employees. \nWhich of the following would be the BEST way to \nprovide this verification?\n \n❍A. Confirm that no unauthorized accounts have \nadministrator access\n \n❍B. Validate the account lockout policy\n \n❍C. Validate the offboarding processes and procedures\n \n❍D. Create a report that shows all authentications  \nfor a 24-hour period\nQuick \nAnswer: 33\nThe Details: 79\n","choices":[{"letter":"A","text":"Confirm that no unauthorized accounts have administrator access"},{"letter":"B","text":"Validate the account lockout policy"},{"letter":"C","text":"Validate the offboarding processes and procedures"},{"letter":"D","text":"Create a report that shows all authentications for a 24-hour period"}],"correct":["C"],"answerPages":[88],"objectives":["5.1"]},{"id":"A42","number":42,"page":25,"clip":[24,29.063,410,132.003],"text":"A42.\tWhich of the following is used to describe how cautious \nan organization might be to taking a specific risk?\n \n❍A. Risk appetite\n \n❍B. Risk register\n \n❍C. Risk transfer\n \n❍D. Risk reporting\nQuick \nAnswer: 33\nThe Details: 80\n","choices":[{"letter":"A","text":"Risk appetite"},{"letter":"B","text":"Risk register"},{"letter":"C","text":"Risk transfer"},{"letter":"D","text":"Risk reporting"}],"correct":["A"],"answerPages":[89],"objectives":["5.2"]},{"id":"A43","number":43,"page":25,"clip":[24,134.003,410,296.222],"text":"A43.\tA technician is applying a series of patches to fifty web \nservers during a scheduled maintenance window. After \npatching and rebooting the first server, the web service \nfails with a critical error. Which of the following should \nthe technician do NEXT?\n \n❍A. Contact the stakeholders regarding the outage\n \n❍B. Follow the steps listed in the backout plan\n \n❍C. Test the upgrade process in the lab\n \n❍D. Evaluate the impact analysis associated with  \nthe change\nQuick \nAnswer: 33\nThe Details: 81\n","choices":[{"letter":"A","text":"Contact the stakeholders regarding the outage"},{"letter":"B","text":"Follow the steps listed in the backout plan"},{"letter":"C","text":"Test the upgrade process in the lab"},{"letter":"D","text":"Evaluate the impact analysis associated with the change"}],"correct":["B"],"answerPages":[90],"objectives":["1.3"]},{"id":"A44","number":44,"page":25,"clip":[24,298.222,410,453.962],"text":"A44.\tAn attacker has discovered a way to disable a server by \nsending specially crafted packets from many remote \ndevices to the operating system. When the packet is \nreceived, the system crashes and must be rebooted to \nrestore normal operations. Which of the following would \nBEST describe this attack?\n \n❍A. Privilege escalation\n \n❍B. SQL injection\n \n❍C. Replay attack\n \n❍D. DDoS\nQuick \nAnswer: 33\nThe Details: 82\n","choices":[{"letter":"A","text":"Privilege escalation"},{"letter":"B","text":"SQL injection"},{"letter":"C","text":"Replay attack"},{"letter":"D","text":"DDoS"}],"correct":["D"],"answerPages":[91],"objectives":["2.4"]},{"id":"A45","number":45,"page":25,"clip":[24,455.962,410,610],"text":"16\nPractice Exam A - Questions\nA45.\tA data breach has occurred in a large insurance company. \nA security administrator is building new servers and \nsecurity systems to get all of the financial systems back \nonline. Which part of the incident response process \nwould BEST describe these actions?\n \n❍A. Lessons learned\n \n❍B. Containment\n \n❍C. Recovery\n \n❍D. Analysis\nQuick \nAnswer: 33\nThe Details: 83\n","choices":[{"letter":"A","text":"Lessons learned"},{"letter":"B","text":"Containment"},{"letter":"C","text":"Recovery"},{"letter":"D","text":"Analysis"}],"correct":["C"],"answerPages":[92],"objectives":["4.8"]},{"id":"A46","number":46,"page":26,"clip":[24,29.063,410,178.082],"text":"A46.\tA network team has installed new access points to \nsupport an application launch. In less than 24 hours, \nthe wireless network was attacked and private company \ninformation was accessed. Which of the following would \nbe the MOST likely reason for this breach?\n \n❍A. Race condition\n \n❍B. Jailbreaking\n \n❍C. Impersonation\n \n❍D. Misconfiguration\nQuick \nAnswer: 33\nThe Details: 84\n","choices":[{"letter":"A","text":"Race condition"},{"letter":"B","text":"Jailbreaking"},{"letter":"C","text":"Impersonation"},{"letter":"D","text":"Misconfiguration"}],"correct":["D"],"answerPages":[93],"objectives":["2.3"]},{"id":"A47","number":47,"page":26,"clip":[24,180.082,410,322.622],"text":"A47.\tAn organization has identified a significant vulnerability \nin an Internet-facing firewall. The firewall company has \nstated the firewall is no longer available for sale and \nthere are no plans to create a patch for this vulnerability. \nWhich of the following would BEST describe this issue?\n \n❍A. End-of-life\n \n❍B. Improper input handling\n \n❍C. Improper key management\n \n❍D. Incompatible OS\nQuick \nAnswer: 33\nThe Details: 85\n","choices":[{"letter":"A","text":"End-of-life"},{"letter":"B","text":"Improper input handling"},{"letter":"C","text":"Improper key management"},{"letter":"D","text":"Incompatible OS"}],"correct":["A"],"answerPages":[94],"objectives":["2.3"]},{"id":"A48","number":48,"page":26,"clip":[24,324.622,410,610],"text":"17\nPractice Exam A - Questions\nA48.\tA company has decided to perform a disaster recovery \nexercise during an annual meeting with the IT directors \nand senior directors. A simulated disaster will be \npresented, and the participants will discuss the logistics \nand processes required to resolve the disaster. Which of \nthe following would BEST describe this exercise?\n \n❍A. Capacity planning\n \n❍B. Business impact analysis\n \n❍C. Continuity of operations\n \n❍D. Tabletop exercise\nQuick \nAnswer: 33\nThe Details: 86\n","choices":[{"letter":"A","text":"Capacity planning"},{"letter":"B","text":"Business impact analysis"},{"letter":"C","text":"Continuity of operations"},{"letter":"D","text":"Tabletop exercise"}],"correct":["D"],"answerPages":[95],"objectives":["3.4"]},{"id":"A49","number":49,"page":27,"clip":[24,29.063,410,165.366],"text":"A49. \tA security administrator needs to block users from \nvisiting websites hosting malicious software. Which of \nthe following would be the BEST way to control this \naccess?\n \n❍A. Honeynet\n \n❍B. Data masking\n \n❍C. DNS filtering\n \n❍D. Data loss prevention\nQuick \nAnswer: 33\nThe Details: 87\n","choices":[{"letter":"A","text":"Honeynet"},{"letter":"B","text":"Data masking"},{"letter":"C","text":"DNS filtering"},{"letter":"D","text":"Data loss prevention"}],"correct":["C"],"answerPages":[96],"objectives":["4.5"]},{"id":"A50","number":50,"page":27,"clip":[24,167.366,410,309.906],"text":"A50.\tA system administrator has been called to a system with \na malware infection. As part of the incident response \nprocess, the administrator has imaged the operating \nsystem to a known-good version. Which of these \nincident response steps is the administrator following?\n \n❍A. Lessons learned\n \n❍B. Recovery\n \n❍C. Detection\n \n❍D. Containment\nQuick \nAnswer: 33\nThe Details: 88\n","choices":[{"letter":"A","text":"Lessons learned"},{"letter":"B","text":"Recovery"},{"letter":"C","text":"Detection"},{"letter":"D","text":"Containment"}],"correct":["B"],"answerPages":[97],"objectives":["4.8"]},{"id":"A51","number":51,"page":27,"clip":[24,311.906,410,610],"text":"18\nPractice Exam A - Questions\nA51. \tA company has placed a SCADA system on a segmented \nnetwork with limited access from the rest of the \ncorporate network. Which of the following would \ndescribe this process?\n \n❍A. Load balancing\n \n❍B. Least privilege\n \n❍C. Data retention\n \n❍D. Hardening\nQuick \nAnswer: 33\nThe Details: 89\n","choices":[{"letter":"A","text":"Load balancing"},{"letter":"B","text":"Least privilege"},{"letter":"C","text":"Data retention"},{"letter":"D","text":"Hardening"}],"correct":["D"],"answerPages":[98],"objectives":["4.1"]},{"id":"A52","number":52,"page":28,"clip":[24,31.298,410,243.077],"text":"A52. \tAn administrator is viewing the following security log: \n \nDec 30 08:40:03 web01 Failed password for root  \nfrom 10.101.88.230 port 26244 ssh2\nDec 30 08:40:05 web01 Failed password for root \nfrom 10.101.88.230 port 26244 ssh2\nDec 30 08:40:09 web01 445 more authentication  \nfailures; rhost=10.101.88.230 user=root\n \nWhich of the following would describe this attack?\n \n❍A. Spraying\n \n❍B. Downgrade\n \n❍C. Brute force\n \n❍D. DDoS\nQuick \nAnswer: 33\nThe Details: 90\n","choices":[{"letter":"A","text":"Spraying"},{"letter":"B","text":"Downgrade"},{"letter":"C","text":"Brute force"},{"letter":"D","text":"DDoS"}],"correct":["C"],"answerPages":[99],"objectives":["4.9"]},{"id":"A53","number":53,"page":28,"clip":[24,245.077,410,374.417],"text":"A53.\tDuring a morning login process, a user's laptop was \nmoved to a private VLAN and a series of updates were \nautomatically installed. Which of the following would \ndescribe this process?\n \n❍A. Account lockout\n \n❍B. Configuration enforcement\n \n❍C. Decommissioning\n \n❍D. Sideloading\nQuick \nAnswer: 33\nThe Details: 91\n","choices":[{"letter":"A","text":"Account lockout"},{"letter":"B","text":"Configuration enforcement"},{"letter":"C","text":"Decommissioning"},{"letter":"D","text":"Sideloading"}],"correct":["B"],"answerPages":[100],"objectives":["2.5"]},{"id":"A54","number":54,"page":28,"clip":[24,376.417,410,610],"text":"19\nPractice Exam A - Questions\nA54.\tWhich of the following describes two-factor \nauthentication?\n \n❍A. A printer uses a password and a PIN\n \n❍B. The door to a building requires a fingerprint scan\n \n❍C. An application requires a pseudo-random code\n \n❍D. A Windows Domain requires a password and \nsmart card\nQuick \nAnswer: 33\nThe Details: 92\n","choices":[{"letter":"A","text":"A printer uses a password and a PIN"},{"letter":"B","text":"The door to a building requires a fingerprint scan"},{"letter":"C","text":"An application requires a pseudo-random code"},{"letter":"D","text":"A Windows Domain requires a password and smart card"}],"correct":["D"],"answerPages":[101],"objectives":["4.6"]},{"id":"A55","number":55,"page":29,"clip":[24,29.063,410,278.182],"text":"A55. \tA company is deploying a new application to all \nemployees in the field. Some of the problems associated \nwith this roll out include:\n• The company does not have a way to manage the  \ndevices in the field\n• Team members have many different kinds of  \nmobile devices\n• The same device needs to be used for both corporate  \nand private use\nWhich of the following deployment models would \naddress these concerns?\n \n❍A. CYOD\n \n❍B. SSO\n \n❍C. COPE\n \n❍D. BYOD\nQuick \nAnswer: 33\nThe Details: 93\n","choices":[{"letter":"A","text":"CYOD"},{"letter":"B","text":"SSO"},{"letter":"C","text":"COPE"},{"letter":"D","text":"BYOD"}],"correct":["C"],"answerPages":[102],"objectives":["4.1"]},{"id":"A56","number":56,"page":29,"clip":[24,280.182,410,396.322],"text":"A56.\tAn organization is installing a UPS for their new data \ncenter. Which of the following would BEST describe \nthis control type?\n \n❍A. Compensating\n \n❍B. Directive\n \n❍C. Deterrent\n \n❍D. Detective\nQuick \nAnswer: 33\nThe Details: 94\n","choices":[{"letter":"A","text":"Compensating"},{"letter":"B","text":"Directive"},{"letter":"C","text":"Deterrent"},{"letter":"D","text":"Detective"}],"correct":["A"],"answerPages":[103],"objectives":["1.1"]},{"id":"A57","number":57,"page":29,"clip":[24,398.322,410,610],"text":"20\nPractice Exam A - Questions\nA57.\tA manufacturing company would like to track the \nprogress of parts used on an assembly line. Which of the \nfollowing technologies would be the BEST choice for \nthis task?\n \n❍A. Secure enclave\n \n❍B. Blockchain\n \n❍C. Hashing\n \n❍D. Asymmetric encryption\nQuick \nAnswer: 33\nThe Details: 95\n","choices":[{"letter":"A","text":"Secure enclave"},{"letter":"B","text":"Blockchain"},{"letter":"C","text":"Hashing"},{"letter":"D","text":"Asymmetric encryption"}],"correct":["B"],"answerPages":[104],"objectives":["1.4"]},{"id":"A58","number":58,"page":30,"clip":[24,29.063,410,164.882],"text":"A58. \tA company's website has been compromised and the \nwebsite content has been replaced with a political \nmessage. Which of the following threat actors would be \nthe MOST likely culprit?\n \n❍A. Insider\n \n❍B. Organized crime\n \n❍C. Shadow IT\n \n❍D. Hacktivist\nQuick \nAnswer: 33\nThe Details: 96\n","choices":[{"letter":"A","text":"Insider"},{"letter":"B","text":"Organized crime"},{"letter":"C","text":"Shadow IT"},{"letter":"D","text":"Hacktivist"}],"correct":["D"],"answerPages":[105],"objectives":["2.1"]},{"id":"A59","number":59,"page":30,"clip":[24,166.882,410,362.222],"text":"A59.\tA Linux administrator is downloading an updated \nversion of her Linux distribution. The download site \nshows a link to the ISO and a SHA256 hash value. \nWhich of these would describe the use of this  \nhash value?\n \n❍A. Verifies that the file was not corrupted during  \nthe file transfer\n \n❍B. Provides a key for decrypting the ISO  \nafter download\n \n❍C. Authenticates the site as an official ISO  \ndistribution site\n \n❍D. Confirms that the file does not contain  \nany malware\nQuick \nAnswer: 33\nThe Details: 97\n","choices":[{"letter":"A","text":"Verifies that the file was not corrupted during the file transfer"},{"letter":"B","text":"Provides a key for decrypting the ISO after download"},{"letter":"C","text":"Authenticates the site as an official ISO distribution site"},{"letter":"D","text":"Confirms that the file does not contain any malware"}],"correct":["A"],"answerPages":[106],"objectives":["3.3"]},{"id":"A60","number":60,"page":30,"clip":[24,364.222,410,610],"text":"21\nPractice Exam A - Questions\nA60.\tA company's security policy requires that login access \nshould only be available if a person is physically within \nthe same building as the server. Which of the following \nwould be the BEST way to provide this requirement?\n \n❍A. USB security key\n \n❍B. Biometric scanner\n \n❍C. PIN\n \n❍D. SMS\nQuick \nAnswer: 33\nThe Details: 98\n","choices":[{"letter":"A","text":"USB security key"},{"letter":"B","text":"Biometric scanner"},{"letter":"C","text":"PIN"},{"letter":"D","text":"SMS"}],"correct":["B"],"answerPages":[107],"objectives":["3.3"]},{"id":"A61","number":61,"page":31,"clip":[24,29.063,410,191.282],"text":"A61. \tA development team has installed a new application and \ndatabase to a cloud service. After running a vulnerability \nscanner on the application instance, a security \nadministrator finds the database is available for anyone \nto query without providing any authentication. Which of \nthese vulnerabilities is MOST associated with this issue?\n \n❍A. Legacy software\n \n❍B. Open permissions\n \n❍C. Race condition\n \n❍D. Malicious update\nQuick \nAnswer: 33\nThe Details: 99\n","choices":[{"letter":"A","text":"Legacy software"},{"letter":"B","text":"Open permissions"},{"letter":"C","text":"Race condition"},{"letter":"D","text":"Malicious update"}],"correct":["B"],"answerPages":[108],"objectives":["3.3"]},{"id":"A62","number":62,"page":31,"clip":[24,193.282,410,329.101],"text":"A62.\tEmployees of an organization have received an email \nwith a link offering a cash bonus for completing an \ninternal training course. Which of the following would \nBEST describe this email?\n \n❍A. Watering hole attack\n \n❍B. Cross-site scripting\n \n❍C. Zero-day\n \n❍D. Phishing campaign\nQuick \nAnswer: 33\nThe Details: 100\n","choices":[{"letter":"A","text":"Watering hole attack"},{"letter":"B","text":"Cross-site scripting"},{"letter":"C","text":"Zero-day"},{"letter":"D","text":"Phishing campaign"}],"correct":["D"],"answerPages":[109],"objectives":["5.6"]},{"id":"A63","number":63,"page":31,"clip":[24,331.101,410,453.72],"text":"A63.\tWhich of the following risk management strategies \nwould include the purchase and installation of an \nNGFW?\n \n❍A. Transfer\n \n❍B. Mitigate\n \n❍C. Accept\n \n❍D. Avoid\nQuick \nAnswer: 33\nThe Details: 101\n","choices":[{"letter":"A","text":"Transfer"},{"letter":"B","text":"Mitigate"},{"letter":"C","text":"Accept"},{"letter":"D","text":"Avoid"}],"correct":["B"],"answerPages":[110],"objectives":["3.2"]},{"id":"A64","number":64,"page":31,"clip":[24,455.72,410,610],"text":"22\nPractice Exam A - Questions\nA64. \tAn organization is implementing a security model where \nall application requests must be validated at a policy \nenforcement point. Which of the following would BEST \ndescribe this model?\n \n❍A. Public key infrastructure\n \n❍B. Zero trust\n \n❍C. Discretionary access control\n \n❍D. Federation\nQuick \nAnswer: 33\nThe Details: 102\n","choices":[{"letter":"A","text":"Public key infrastructure"},{"letter":"B","text":"Zero trust"},{"letter":"C","text":"Discretionary access control"},{"letter":"D","text":"Federation"}],"correct":["B"],"answerPages":[111],"objectives":["1.2"]},{"id":"A65","number":65,"page":32,"clip":[24,29.063,410,151.682],"text":"A65. \tA company is installing a new application in a \npublic cloud. Which of the following determines the \nassignment of data security in this cloud infrastructure?\n \n❍A. Playbook\n \n❍B. Audit committee\n \n❍C. Responsibility matrix\n \n❍D. Right-to-audit clause\nQuick \nAnswer: 33\nThe Details: 103\n","choices":[{"letter":"A","text":"Playbook"},{"letter":"B","text":"Audit committee"},{"letter":"C","text":"Responsibility matrix"},{"letter":"D","text":"Right-to-audit clause"}],"correct":["C"],"answerPages":[112],"objectives":["3.1"]},{"id":"A66","number":66,"page":32,"clip":[24,153.682,410,283.022],"text":"A66.\tWhen decommissioning a device, a company documents \nthe type and size of storage drive, the amount of RAM, \nand any installed adapter cards. Which of the following \ndescribes this process?\n \n❍A. Destruction\n \n❍B. Sanitization\n \n❍C. Certification\n \n❍D. Enumeration\nQuick \nAnswer: 33\nThe Details: 104\n","choices":[{"letter":"A","text":"Destruction"},{"letter":"B","text":"Sanitization"},{"letter":"C","text":"Certification"},{"letter":"D","text":"Enumeration"}],"correct":["D"],"answerPages":[113],"objectives":["4.2"]},{"id":"A67","number":67,"page":32,"clip":[24,285.022,410,420.841],"text":"A67.\tAn attacker has sent more information than expected \nin a single API call, and this has allowed the execution \nof arbitrary code. Which of the following would BEST \ndescribe this attack?\n \n❍A. Buffer overflow\n \n❍B. Replay attack\n \n❍C. Cross-site scripting\n \n❍D. DDoS\nQuick \nAnswer: 33\nThe Details: 105\n","choices":[{"letter":"A","text":"Buffer overflow"},{"letter":"B","text":"Replay attack"},{"letter":"C","text":"Cross-site scripting"},{"letter":"D","text":"DDoS"}],"correct":["A"],"answerPages":[114],"objectives":["2.3"]},{"id":"A68","number":68,"page":32,"clip":[24,422.841,410,610],"text":"23\nPractice Exam A - Questions\nA68. \tA company encourages users to encrypt all of \ntheir confidential materials on a central server. The \norganization would like to enable key escrow as a backup \noption. Which of these keys should the organization \nplace into escrow?\n \n❍A. Private\n \n❍B. CA\n \n❍C. Session\n \n❍D. Public\nQuick \nAnswer: 33\nThe Details: 106\n","choices":[{"letter":"A","text":"Private"},{"letter":"B","text":"CA"},{"letter":"C","text":"Session"},{"letter":"D","text":"Public"}],"correct":["A"],"answerPages":[115],"objectives":["1.4"]},{"id":"A69","number":69,"page":33,"clip":[24,29.063,410,151.682],"text":"A69.\tA company is in the process of configuring and enabling \nhost-based firewalls on all user devices. Which of the \nfollowing threats is the company addressing?\n \n❍A. Default credentials\n \n❍B. Vishing\n \n❍C. Instant messaging\n \n❍D. On-path\nQuick \nAnswer: 33\nThe Details: 107\n","choices":[{"letter":"A","text":"Default credentials"},{"letter":"B","text":"Vishing"},{"letter":"C","text":"Instant messaging"},{"letter":"D","text":"On-path"}],"correct":["C"],"answerPages":[116],"objectives":["2.2"]},{"id":"A70","number":70,"page":33,"clip":[24,153.682,410,335.822],"text":"A70.\tA manufacturing company would like to use an \nexisting router to separate a corporate network from \na manufacturing floor. Both networks use the same \nphysical switch, and the company does not want to install \nany additional hardware. Which of the following would \nbe the BEST choice for this segmentation?\n \n❍A. Connect the corporate network and the \nmanufacturing floor with a VPN\n \n❍B. Build an air gapped manufacturing floor network\n \n❍C. Use host-based firewalls on each device\n \n❍D. Create separate VLANs for the corporate network \nand the manufacturing floor\nQuick \nAnswer: 33\nThe Details: 108\n","choices":[{"letter":"A","text":"Connect the corporate network and the manufacturing floor with a VPN"},{"letter":"B","text":"Build an air gapped manufacturing floor network"},{"letter":"C","text":"Use host-based firewalls on each device"},{"letter":"D","text":"Create separate VLANs for the corporate network and the manufacturing floor"}],"correct":["D"],"answerPages":[117],"objectives":["2.5"]},{"id":"A71","number":71,"page":33,"clip":[24,337.822,410,610],"text":"24\nPractice Exam A - Questions\nA71. An organization needs to provide a remote access \nsolution for a newly deployed cloud-based application. \nThis application is designed to be used by mobile field \nservice technicians. Which of the following would be the \nbest option for this requirement?\n \n❍A. RTOS\n \n❍B. CRL\n \n❍C. Zero-trust\n \n❍D. SASE\nQuick \nAnswer: 33\nThe Details: 109\n","choices":[{"letter":"A","text":"RTOS"},{"letter":"B","text":"CRL"},{"letter":"C","text":"Zero-trust"},{"letter":"D","text":"SASE"}],"correct":["D"],"answerPages":[118],"objectives":["3.2"]},{"id":"A72","number":72,"page":34,"clip":[24,29.063,410,151.682],"text":"A72.\tA company is implementing a quarterly security \nawareness campaign. Which of the following would \nMOST likely be part of this campaign?\n \n❍A. Suspicious message reports from users\n \n❍B. An itemized statement of work\n \n❍C. An IaC configuration file\n \n❍D. An acceptable use policy document\nQuick \nAnswer: 33\nThe Details: 110\n","choices":[{"letter":"A","text":"Suspicious message reports from users"},{"letter":"B","text":"An itemized statement of work"},{"letter":"C","text":"An IaC configuration file"},{"letter":"D","text":"An acceptable use policy document"}],"correct":["A"],"answerPages":[119],"objectives":["5.6"]},{"id":"A73","number":73,"page":34,"clip":[24,153.682,410,329.101],"text":"A73.\tA recent report shows the return of a vulnerability \nthat was previously patched four months ago. After \nresearching this issue, the security team has found a \nrecent patch has reintroduced this vulnerability on the \nservers. Which of the following should the security \nadministrator implement to prevent this issue from \noccurring in the future?\n \n❍A. Containerization\n \n❍B. Data masking\n \n❍C. 802.1X\n \n❍D. Change management\nQuick \nAnswer: 33\nThe Details: 111\n","choices":[{"letter":"A","text":"Containerization"},{"letter":"B","text":"Data masking"},{"letter":"C","text":"802.1X"},{"letter":"D","text":"Change management"}],"correct":["D"],"answerPages":[120],"objectives":["1.3"]},{"id":"A74","number":74,"page":34,"clip":[24,331.101,410,466.92],"text":"A74. \tA security manager would like to ensure that unique \nhashes are used with an application login process. Which \nof the following would be the BEST way to add random \ndata when generating a set of stored password hashes?\n \n❍A. Salting\n \n❍B. Obfuscation\n \n❍C. Key stretching\n \n❍D. Digital signature\nQuick \nAnswer: 33\nThe Details: 112\n","choices":[{"letter":"A","text":"Salting"},{"letter":"B","text":"Obfuscation"},{"letter":"C","text":"Key stretching"},{"letter":"D","text":"Digital signature"}],"correct":["A"],"answerPages":[121],"objectives":["1.4"]},{"id":"A75","number":75,"page":34,"clip":[24,468.92,410,610],"text":"25\nPractice Exam A - Questions\nA75. \tWhich cryptographic method is used to add trust to a \ndigital certificate?\n \n❍A. Steganography\n \n❍B. Hash\n \n❍C. Symmetric encryption\n \n❍D. Digital signature\nQuick \nAnswer: 33\nThe Details: 113\n","choices":[{"letter":"A","text":"Steganography"},{"letter":"B","text":"Hash"},{"letter":"C","text":"Symmetric encryption"},{"letter":"D","text":"Digital signature"}],"correct":["D"],"answerPages":[122],"objectives":["1.4"]},{"id":"A76","number":76,"page":35,"clip":[24,29.063,410,191.282],"text":"A76. \tA company is using SCAP as part of their security \nmonitoring processes. Which of the following would \nBEST describe this implementation? \n \n❍A. Train the user community to better identify \nphishing attempts\n \n❍B. Present the results of an internal audit to the board\n \n❍C. Automate the validation and patching of  \nsecurity issues\n \n❍D. Identify and document authorized data  \ncenter visitors\nQuick \nAnswer: 33\nThe Details: 114\n","choices":[{"letter":"A","text":"Train the user community to better identify phishing attempts"},{"letter":"B","text":"Present the results of an internal audit to the board"},{"letter":"C","text":"Automate the validation and patching of security issues"},{"letter":"D","text":"Identify and document authorized data center visitors"}],"correct":["C"],"answerPages":[123],"objectives":["4.4"]},{"id":"A77","number":77,"page":35,"clip":[24,193.282,410,329.101],"text":"A77. \tAn organization maintains a large database of customer \ninformation for sales tracking and customer support. \nWhich person in the organization would be responsible \nfor managing the access rights to this data?\n \n❍A. Data processor\n \n❍B. Data owner\n \n❍C. Data subject\n \n❍D. Data custodian\nQuick \nAnswer: 33\nThe Details: 115\n","choices":[{"letter":"A","text":"Data processor"},{"letter":"B","text":"Data owner"},{"letter":"C","text":"Data subject"},{"letter":"D","text":"Data custodian"}],"correct":["D"],"answerPages":[124],"objectives":["5.1"]},{"id":"A78","number":78,"page":35,"clip":[24,331.101,410,610],"text":"26\nPractice Exam A - Questions\nA78. \tAn organization’s content management system currently \nlabels files and documents as “Public” and “Restricted.” \nOn a recent update, a new classification type of “Private” \nwas added. Which of the following would be the MOST \nlikely reason for this addition?\n \n❍A. Minimized attack surface\n \n❍B. Simplified categorization\n \n❍C. Expanded privacy compliance\n \n❍D. Decreased search time\nQuick \nAnswer: 33\nThe Details: 116\n","choices":[{"letter":"A","text":"Minimized attack surface"},{"letter":"B","text":"Simplified categorization"},{"letter":"C","text":"Expanded privacy compliance"},{"letter":"D","text":"Decreased search time"}],"correct":["C"],"answerPages":[125],"objectives":["3.3"]},{"id":"A79","number":79,"page":36,"clip":[24,29.383,410,165.202],"text":"A79. \tA corporate security team would like to consolidate and \nprotect the private keys across all of their web servers. \nWhich of these would be the BEST way to securely store \nthese keys?\n \n❍A. Integrate an HSM\n \n❍B. Implement full disk encryption on the web servers\n \n❍C. Use a TPM\n \n❍D. Upgrade the web servers to use a UEFI BIOS\nQuick \nAnswer: 33\nThe Details: 117\n","choices":[{"letter":"A","text":"Integrate an HSM"},{"letter":"B","text":"Implement full disk encryption on the web servers"},{"letter":"C","text":"Use a TPM"},{"letter":"D","text":"Upgrade the web servers to use a UEFI BIOS"}],"correct":["A"],"answerPages":[126],"objectives":["1.4"]},{"id":"A80","number":80,"page":36,"clip":[24,167.202,410,427.343],"text":"A80. \tA security technician is reviewing this security log from \nan IPS:\nWhich of the following can be determined from this log \ninformation? (Select TWO)\n \n❍A. The alert was generated from a malformed \nUser Agent header\n \n❍B. The alert was generated from an embedded script\n \n❍C. The attacker’s IP address is 222.43.112.74\n \n❍D. The attacker’s IP address is 64.235.145.35\n \n❍E. The alert was generated due to an invalid \nclient port number\nALERT 2023-06-01 13:07:29 [163bcf65118-179b547b]\nCross-Site Scripting in JSON Data\n222.43.112.74:3332 -> 64.235.145.35:80\nURL/index.html - Method POST - Query String \"-\"\nUser Agent: curl/7.21.3 (i386-redhat-linux-gnu) libcurl/7.21.3 \nNSS/3.13.1.0 zlib/1.2.5 libidn/1.19 libssh2/1.2.7\nDetail: token=\"<script>\" key=\"key7\" value=\"<script>alert(2)</script>\"\nQuick \nAnswer: 33\nThe Details: 118\n","choices":[{"letter":"A","text":"The alert was generated from a malformed User Agent header"},{"letter":"B","text":"The alert was generated from an embedded script"},{"letter":"C","text":"The attacker’s IP address is 222.43.112.74"},{"letter":"D","text":"The attacker’s IP address is 64.235.145.35"},{"letter":"E","text":"The alert was generated due to an invalid client port number"}],"correct":["B","C"],"answerPages":[127],"objectives":["4.9"]},{"id":"A81","number":81,"page":36,"clip":[24,429.343,410,610],"text":"27\nPractice Exam A - Questions\nA81. \tWhich of the following describes a monetary loss if one \nevent occurs?\n \n❍A. ALE\n \n❍B. SLE\n \n❍C. RTO\n \n❍D. ARO\nQuick \nAnswer: 33\nThe Details: 119\n","choices":[{"letter":"A","text":"ALE"},{"letter":"B","text":"SLE"},{"letter":"C","text":"RTO"},{"letter":"D","text":"ARO"}],"correct":["B"],"answerPages":[128],"objectives":["5.2"]},{"id":"A82","number":82,"page":37,"clip":[24,29.063,410,217.682],"text":"A82. \tA user with restricted access has typed this text in a \nsearch field of an internal web-based application: \n \nUSER77' OR '1'='1 \n \nAfter submitting this search request, all database records \nare displayed on the screen. Which of the following \nwould BEST describe this search?\n \n❍A. Cross-site scripting\n \n❍B. Buffer overflow\n \n❍C. SQL injection\n \n❍D. SSL stripping\nQuick \nAnswer: 33\nThe Details: 120\n","choices":[{"letter":"A","text":"Cross-site scripting"},{"letter":"B","text":"Buffer overflow"},{"letter":"C","text":"SQL injection"},{"letter":"D","text":"SSL stripping"}],"correct":["C"],"answerPages":[129],"objectives":["2.3"]},{"id":"A83","number":83,"page":37,"clip":[24,219.682,410,395.101],"text":"A83. \tA user has opened a helpdesk ticket complaining of poor \nsystem performance, excessive pop up messages, and \nthe cursor moving without anyone touching the mouse. \nThis issue began after they opened a spreadsheet from a \nvendor containing part numbers and pricing information. \nWhich of the following is MOST likely the cause of this \nuser's issues?\n \n❍A. On-path\n \n❍B. Worm\n \n❍C. Trojan horse\n \n❍D. Logic bomb\nQuick \nAnswer: 33\nThe Details: 121\n","choices":[{"letter":"A","text":"On-path"},{"letter":"B","text":"Worm"},{"letter":"C","text":"Trojan horse"},{"letter":"D","text":"Logic bomb"}],"correct":["C"],"answerPages":[130],"objectives":["1.2"]},{"id":"A84","number":84,"page":37,"clip":[24,397.101,410,610],"text":"28\nPractice Exam A - Questions\nA84. \tA web-based manufacturing company processes \nmonthly charges to credit card information saved in the \ncustomer's profile. All of the customer information is \nencrypted and protected with additional authentication \nfactors. Which of the following would be the justification \nfor these security controls?\n \n❍A. Chain of custody\n \n❍B. Password vaulting\n \n❍C. Compliance reporting\n \n❍D. Sandboxing\nQuick \nAnswer: 33\nThe Details: 122\n","choices":[{"letter":"A","text":"Chain of custody"},{"letter":"B","text":"Password vaulting"},{"letter":"C","text":"Compliance reporting"},{"letter":"D","text":"Sandboxing"}],"correct":["C"],"answerPages":[131],"objectives":["5.4"]},{"id":"A85","number":85,"page":38,"clip":[24,29.063,410,191.282],"text":"A85. \tA security manager has created a report showing \nintermittent network communication from certain \nworkstations on the internal network to one external \nIP address. These traffic patterns occur at random times \nduring the day. Which of the following would be the \nMOST likely reason for these traffic patterns?\n \n❍A. On-path attack\n \n❍B. Keylogger\n \n❍C. Replay attack\n \n❍D. Brute force\nQuick \nAnswer: 33\nThe Details: 123\n","choices":[{"letter":"A","text":"On-path attack"},{"letter":"B","text":"Keylogger"},{"letter":"C","text":"Replay attack"},{"letter":"D","text":"Brute force"}],"correct":["B"],"answerPages":[132],"objectives":["2.4"]},{"id":"A86","number":86,"page":38,"clip":[24,193.282,410,355.501],"text":"A86. \tThe security policies in a manufacturing company \nprohibit the transmission of customer information. \nHowever, a security administrator has received an alert \nthat credit card numbers were transmitted as an email \nattachment. Which of the following was the MOST \nlikely source of this alert message?\n \n❍A. IPS\n \n❍B. DLP\n \n❍C. RADIUS\n \n❍D. IPsec\nQuick \nAnswer: 33\nThe Details: 124\n","choices":[{"letter":"A","text":"IPS"},{"letter":"B","text":"DLP"},{"letter":"C","text":"RADIUS"},{"letter":"D","text":"IPsec"}],"correct":["B"],"answerPages":[133],"objectives":["4.4"]},{"id":"A87","number":87,"page":38,"clip":[24,357.501,410,610],"text":"29\nPractice Exam A - Questions\nA87. \tA security administrator has configured a virtual machine \nin a screened subnet with a guest login account and no \npassword. Which of the following would be the MOST \nlikely reason for this configuration?\n \n❍A. The server is a honeypot for attracting  \npotential attackers\n \n❍B. The server is a cloud storage service for  \nremote users\n \n❍C. The server will be used as a VPN concentrator\n \n❍D. The server is a development sandbox for third-\nparty programming projects\nQuick \nAnswer: 33\nThe Details: 125\n","choices":[{"letter":"A","text":"The server is a honeypot for attracting potential attackers"},{"letter":"B","text":"The server is a cloud storage service for remote users"},{"letter":"C","text":"The server will be used as a VPN concentrator"},{"letter":"D","text":"The server is a development sandbox for third-party programming projects"}],"correct":["A"],"answerPages":[134],"objectives":["1.2"]},{"id":"A88","number":88,"page":39,"clip":[24,29.063,410,171.603],"text":"A88. \tA security administrator is configuring a DNS server \nwith a SPF record. Which of the following would be the \nreason for this configuration?\n \n❍A. Transmit all outgoing email over an  \nencrypted tunnel\n \n❍B. List all servers authorized to send emails\n \n❍C. Digitally sign all outgoing email messages\n \n❍D. Obtain disposition instructions for emails  \nmarked as spam\nQuick \nAnswer: 33\nThe Details: 126\n","choices":[{"letter":"A","text":"Transmit all outgoing email over an encrypted tunnel"},{"letter":"B","text":"List all servers authorized to send emails"},{"letter":"C","text":"Digitally sign all outgoing email messages"},{"letter":"D","text":"Obtain disposition instructions for emails marked as spam"}],"correct":["B"],"answerPages":[135],"objectives":["4.5"]},{"id":"A89","number":89,"page":39,"clip":[24,173.603,410,309.422],"text":"A89. \tA company would like to securely deploy applications \nwithout the overhead of installing a virtual machine for \neach system. Which of the following would be the BEST \nway to deploy these applications?\n \n❍A. Containerization\n \n❍B. IoT\n \n❍C. Proxy\n \n❍D. RTOS\nQuick \nAnswer: 33\nThe Details: 127\n","choices":[{"letter":"A","text":"Containerization"},{"letter":"B","text":"IoT"},{"letter":"C","text":"Proxy"},{"letter":"D","text":"RTOS"}],"correct":["A"],"answerPages":[136],"objectives":["3.1"]},{"id":"A90","number":90,"page":39,"clip":[24,311.422,410,610],"text":"30\nPractice Exam A - Questions\nA90. \tA company has just purchased a new application server, \nand the security director wants to determine if the \nsystem is secure. The system is currently installed in a test \nenvironment and will not be available to users until the \nroll out to production next week. Which of the following \nwould be the BEST way to determine if any part of the \nsystem can be exploited?\n \n❍A. Tabletop exercise\n \n❍B. Vulnerability scanner\n \n❍C. DDoS\n \n❍D. Penetration test\nQuick \nAnswer: 33\nThe Details: 128\n","choices":[{"letter":"A","text":"Tabletop exercise"},{"letter":"B","text":"Vulnerability scanner"},{"letter":"C","text":"DDoS"},{"letter":"D","text":"Penetration test"}],"correct":["D"],"answerPages":[137,138],"objectives":["4.3"]}],"B":[{"id":"B1","number":1,"page":140,"clip":[24,84.143,410,269.825],"text":"Answer Page: 165\nCRL\nCA\nOCSP\nCSR\nB1.\t Match the certificate characteristic to the description:\nA list of invalidated certificates\nSend the public key to be signed\nDeploy and manage certificates\nThe browser checks for a revoked certificate\n","choices":[],"correct":[],"answerPages":[172],"objectives":["1.4"]},{"id":"B2","number":2,"page":140,"clip":[24,271.825,410,610],"text":"131\nPractice Exam B - Questions\nAnswer Page: 164\nB2.\t An organization is deploying a mobile app to its sales team in the field. \nThe application will be accessed from tablets for remote team members \nand a browser-based front-end on desktops for corporate office users.  \n \nThe application contains sensitive customer information, and two forms of \nauthentication are required to launch the application. \n \nSelect the best security features for each platform. A security feature will \nonly be used once. Not all security features will be used.\nSecurity\nFeatures\nDesktop with\nBrowser-based\nFront-end\nTablet for\nField Sales\nInfrared sensors\nOSINT\nAnti-malware\nHost-based firewall\nMDM integration\nFull device encryption\nBiometric authentication\n","choices":[],"correct":[],"answerPages":[173],"objectives":["4.6","4.1"]},{"id":"B3","number":3,"page":141,"clip":[24,29.063,410,154.703],"text":"B3.\t Place the incident response activities in the correct order:\nAnswer Page: 165\nEradication\nRecovery\nPreparation\nAnalysis\nContainment\nLessons learned\nDetection\n","choices":[],"correct":[],"answerPages":[174],"objectives":["4.8"]},{"id":"B4","number":4,"page":141,"clip":[24,156.703,410,610],"text":"132\nPractice Exam B - Questions\nAnswer Page: 166\nB4.\t Match the security technology to the implementation:\nHashing\nDigital \nsignature\nSPF\nKey escrow\nJournaling\nObfuscation\nStore a password on an authentication server\nVerify a sender’s identity\nAuthenticate the server sending an email\nStore keys with a third-party\nPrevent data corruption when a system fails\nModify a script to make it difficult to understand\n","choices":[],"correct":[],"answerPages":[175],"objectives":[]},{"id":"B5","number":5,"page":142,"clip":[24,29.063,410,610],"text":"133\nPractice Exam B - Questions\nB5.\t Select the data state that best fits the description.  \nEach data state will be used more than once.\nAll switches in a data center are connected with  \nan 802.1Q trunk\nSales information is uploaded daily from a remote site \nusing a satellite network\nA company stores customer purchase information in a \nMySQL database\nAn application decrypts credit card numbers and \nexpiration dates to validate for approval\nAn authentication program performs a hash of  \nall passwords\nAn IPS identifies a SQL injection attack and removes \nthe attack frames from the network\nAn automatic teller machine validates a user’s PIN \nbefore allowing a deposit\nEach time a spreadsheet is updated, all of the cells \ncontaining formulas are automatically updated\nAll weekly backup tapes are transported to an offsite \nstorage facility\nAll user spreadsheets are stored on a cloud-based file \nsharing service\nData in-transit\nData at-rest\nData in-use\nAnswer Page: 167\n","choices":[],"correct":[],"answerPages":[176],"objectives":["3.3"]},{"id":"B6","number":6,"page":144,"clip":[24,85.848,410,237.089],"text":"B6.\t A security administrator has performed an audit of the \norganization’s production web servers, and the results have \nidentified default configurations, web services running \nfrom a privileged account, and inconsistencies with SSL \ncertificates. Which of the following would be the BEST \nway to resolve these issues?\n \n❍A. Server hardening\n \n❍B. Multi-factor authentication\n \n❍C. Enable HTTPS\n \n❍D. Run operating system updates\nQuick \nAnswer: 161\nThe Details: 168\n","choices":[{"letter":"A","text":"Server hardening"},{"letter":"B","text":"Multi-factor authentication"},{"letter":"C","text":"Enable HTTPS"},{"letter":"D","text":"Run operating system updates"}],"correct":["A"],"answerPages":[177],"objectives":["2.5"]},{"id":"B7","number":7,"page":144,"clip":[24,239.089,410,377.13],"text":"B7.\t A shipping company stores information in small regional \nwarehouses around the country. The company maintains \nan IPS at each warehouse to watch for suspicious traffic \npatterns. Which of the following would BEST describe \nthe security control used at the warehouse?\n \n❍A. Deterrent\n \n❍B. Compensating\n \n❍C. Directive\n \n❍D. Detective\nQuick \nAnswer: 161\nThe Details: 169\n","choices":[{"letter":"A","text":"Deterrent"},{"letter":"B","text":"Compensating"},{"letter":"C","text":"Directive"},{"letter":"D","text":"Detective"}],"correct":["D"],"answerPages":[178],"objectives":["1.1"]},{"id":"B8","number":8,"page":144,"clip":[24,379.13,410,610],"text":"135\nPractice Exam B - Questions\nB8.\t The Vice President of Sales has asked the IT team to \ncreate daily backups of the sales data. The Vice President \nis an example of a:\n \n❍A. Data owner \n \n❍B. Data controller\n \n❍C. Data steward\n \n❍D. Data processor\nQuick \nAnswer: 161\nThe Details: 170\n","choices":[{"letter":"A","text":"Data owner"},{"letter":"B","text":"Data controller"},{"letter":"C","text":"Data steward"},{"letter":"D","text":"Data processor"}],"correct":["A"],"answerPages":[179],"objectives":["5.1"]},{"id":"B9","number":9,"page":145,"clip":[24,29.063,410,167.104],"text":"B9.\t A security engineer is preparing to conduct a penetration \ntest of a third-party website. Part of the preparation \ninvolves reading through social media posts for \ninformation about this site. Which of the following \ndescribes this practice?\n \n❍A. Partially known environment\n \n❍B. OSINT\n \n❍C. Exfiltration\n \n❍D. Active reconnaissance\nQuick \nAnswer: 161\nThe Details: 171\n","choices":[{"letter":"A","text":"Partially known environment"},{"letter":"B","text":"OSINT"},{"letter":"C","text":"Exfiltration"},{"letter":"D","text":"Active reconnaissance"}],"correct":["B"],"answerPages":[180],"objectives":["4.3"]},{"id":"B10","number":10,"page":145,"clip":[24,169.104,410,298.444],"text":"B10.\t A company would like to orchestrate the response when \na virus is detected on company devices. Which of the \nfollowing would be the BEST way to implement this \nfunction?\n \n❍A. Active reconnaissance\n \n❍B. Log aggregation\n \n❍C. Vulnerability scan\n \n❍D. Escalation scripting\nQuick \nAnswer: 161\nThe Details: 172\n","choices":[{"letter":"A","text":"Active reconnaissance"},{"letter":"B","text":"Log aggregation"},{"letter":"C","text":"Vulnerability scan"},{"letter":"D","text":"Escalation scripting"}],"correct":["D"],"answerPages":[181],"objectives":["4.7"]},{"id":"B11","number":11,"page":145,"clip":[24,300.444,410,429.784],"text":"B11.\tA user in the accounting department has received a text \nmessage from the CEO. The message requests payment \nby cryptocurrency for a recently purchased tablet. Which \nof the following would BEST describe this attack?\n \n❍A. Brand impersonation\n \n❍B. Watering hole attack\n \n❍C. Smishing\n \n❍D. Typosquatting\nQuick \nAnswer: 161\nThe Details: 173\n","choices":[{"letter":"A","text":"Brand impersonation"},{"letter":"B","text":"Watering hole attack"},{"letter":"C","text":"Smishing"},{"letter":"D","text":"Typosquatting"}],"correct":["C"],"answerPages":[182],"objectives":["2.1"]},{"id":"B12","number":12,"page":145,"clip":[24,431.784,410,610],"text":"136\nPractice Exam B - Questions\nB12.\t A company has been informed of a hypervisor \nvulnerability that could allow users on one virtual \nmachine to access resources on another virtual machine. \nWhich of the following would BEST describe this \nvulnerability?\n \n❍A. Containerization\n \n❍B. Jailbreaking\n \n❍C. SDN\n \n❍D. Escape\nQuick \nAnswer: 161\nThe Details: 174\n","choices":[{"letter":"A","text":"Containerization"},{"letter":"B","text":"Jailbreaking"},{"letter":"C","text":"SDN"},{"letter":"D","text":"Escape"}],"correct":["D"],"answerPages":[183],"objectives":["2.3"]},{"id":"B13","number":13,"page":146,"clip":[24,29.063,410,198.003],"text":"B13.\tWhile working from home, users are attending a project \nmeeting over a web conference. When typing in the \nmeeting link, the browser is unexpectedly directed to a \ndifferent website than the web conference. Users in the \noffice do not have any issues accessing the conference \nsite. Which of the following would be the MOST likely \nreason for this issue?\n \n❍A. Buffer overflow\n \n❍B. Wireless disassociation\n \n❍C. Amplified DDoS\n \n❍D. DNS poisoning\nQuick \nAnswer: 161\nThe Details: 175\n","choices":[{"letter":"A","text":"Buffer overflow"},{"letter":"B","text":"Wireless disassociation"},{"letter":"C","text":"Amplified DDoS"},{"letter":"D","text":"DNS poisoning"}],"correct":["D"],"answerPages":[184],"objectives":["2.4"]},{"id":"B14","number":14,"page":146,"clip":[24,200.003,410,329.343],"text":"B14.\tA company is launching a new internal application that \nwill not start until a username and password is entered \nand a smart card is plugged into the computer. Which of \nthe following BEST describes this process?\n \n❍A. Federation \n \n❍B. Accounting\n \n❍C. Authentication\n \n❍D. Authorization\nQuick \nAnswer: 161\nThe Details: 176\n","choices":[{"letter":"A","text":"Federation"},{"letter":"B","text":"Accounting"},{"letter":"C","text":"Authentication"},{"letter":"D","text":"Authorization"}],"correct":["C"],"answerPages":[185],"objectives":["1.2"]},{"id":"B15","number":15,"page":146,"clip":[24,331.343,410,610],"text":"137\nPractice Exam B - Questions\nB15.\tAn online retailer is planning a penetration test as part \nof their PCI DSS validation. A third-party organization \nwill be performing the test, and the online retailer has \nprovided the Internet-facing IP addresses for their public \nweb servers. No other details were provided.  \nWhat penetration testing methodology is the online \nretailer using?\n \n❍A. Known environment \n \n❍B. Passive reconnaissance\n \n❍C. Partially known environment\n \n❍D. Benchmarks\nQuick \nAnswer: 161\nThe Details: 177\n","choices":[{"letter":"A","text":"Known environment"},{"letter":"B","text":"Passive reconnaissance"},{"letter":"C","text":"Partially known environment"},{"letter":"D","text":"Benchmarks"}],"correct":["C"],"answerPages":[186],"objectives":["5.5"]},{"id":"B16","number":16,"page":147,"clip":[24,29.063,410,184.803],"text":"B16.\t A manufacturing company produces radar used by \ncommercial and military organizations. A recently \nproposed policy change would allow the use of mobile \ndevices inside the facility. Which of the following would \nbe the MOST significant threat vector issue associated \nwith this change in policy?\n \n❍A. Unauthorized software on rooted devices \n \n❍B. Remote access clients on the mobile devices\n \n❍C. Out of date mobile operating systems\n \n❍D. Loss of intellectual property\nQuick \nAnswer: 161\nThe Details: 178\n","choices":[{"letter":"A","text":"Unauthorized software on rooted devices"},{"letter":"B","text":"Remote access clients on the mobile devices"},{"letter":"C","text":"Out of date mobile operating systems"},{"letter":"D","text":"Loss of intellectual property"}],"correct":["D"],"answerPages":[187],"objectives":["2.2"]},{"id":"B17","number":17,"page":147,"clip":[24,186.803,410,302.943],"text":"B17.\tWhich of the following would be the BEST way for an \norganization to verify the digital signature provided by an \nexternal email server?\n \n❍A. Perform a vulnerability scan\n \n❍B. View the server's device certificate\n \n❍C. Authenticate to a RADIUS server\n \n❍D. Check the DKIM record\nQuick \nAnswer: 161\nThe Details: 179\n","choices":[{"letter":"A","text":"Perform a vulnerability scan"},{"letter":"B","text":"View the server's device certificate"},{"letter":"C","text":"Authenticate to a RADIUS server"},{"letter":"D","text":"Check the DKIM record"}],"correct":["D"],"answerPages":[188],"objectives":["4.5"]},{"id":"B18","number":18,"page":147,"clip":[24,304.943,410,447.483],"text":"B18.\tA company is using older operating systems for their \nweb servers and are concerned of their stability during \nperiods of high use. Which of the following should the \ncompany use to maximize the uptime and availability of \nthis service?\n \n❍A. Cold site\n \n❍B. UPS\n \n❍C. Redundant routers\n \n❍D. Load balancer\nQuick \nAnswer: 161\nThe Details: 180\n","choices":[{"letter":"A","text":"Cold site"},{"letter":"B","text":"UPS"},{"letter":"C","text":"Redundant routers"},{"letter":"D","text":"Load balancer"}],"correct":["D"],"answerPages":[189],"objectives":["3.4"]},{"id":"B19","number":19,"page":147,"clip":[24,449.483,410,610],"text":"138\nPractice Exam B - Questions\nB19.\tA user in the accounting department would like to email \na spreadsheet with sensitive information to a list of third-\nparty vendors. Which of the following would be the \nBEST way to protect the data in this email?\n \n❍A. Full disk encryption\n \n❍B. Key exchange algorithm\n \n❍C. Salted hash\n \n❍D. Asymmetric encryption\nQuick \nAnswer: 161\nThe Details: 181\n","choices":[{"letter":"A","text":"Full disk encryption"},{"letter":"B","text":"Key exchange algorithm"},{"letter":"C","text":"Salted hash"},{"letter":"D","text":"Asymmetric encryption"}],"correct":["D"],"answerPages":[190],"objectives":["1.4"]},{"id":"B20","number":20,"page":148,"clip":[24,29.063,410,184.803],"text":"B20.\tA system administrator would like to segment the \nnetwork to give the marketing, accounting, and \nmanufacturing departments their own private network. \nThe network communication between departments \nwould be restricted for additional security. Which of the \nfollowing should be configured on this network?\n \n❍A. VPN \n \n❍B. RBAC\n \n❍C. VLAN\n \n❍D. SDN\nQuick \nAnswer: 161\nThe Details: 182\n","choices":[{"letter":"A","text":"VPN"},{"letter":"B","text":"RBAC"},{"letter":"C","text":"VLAN"},{"letter":"D","text":"SDN"}],"correct":["C"],"answerPages":[191],"objectives":["2.5"]},{"id":"B21","number":21,"page":148,"clip":[24,186.803,410,329.343],"text":"B21.\tA technician at an MSP has been asked to manage \ndevices on third-party private network. The technician \nneeds command line access to internal routers, switches, \nand firewalls. Which of the following would provide the \nnecessary access?\n \n❍A. HSM \n \n❍B. Jump server\n \n❍C. NAC\n \n❍D. Air gap\nQuick \nAnswer: 161\nThe Details: 183\n","choices":[{"letter":"A","text":"HSM"},{"letter":"B","text":"Jump server"},{"letter":"C","text":"NAC"},{"letter":"D","text":"Air gap"}],"correct":["B"],"answerPages":[192],"objectives":["3.2"]},{"id":"B22","number":22,"page":148,"clip":[24,331.343,410,610],"text":"139\nPractice Exam B - Questions\nB22.\tA transportation company is installing new wireless \naccess points in their corporate office. The manufacturer \nestimates the access points will operate an average of \n100,000 hours before a hardware-related outage. Which \nof the following describes this estimate?\n \n❍A. MTTR\n \n❍B. RPO\n \n❍C. RTO\n \n❍D. MTBF\nQuick \nAnswer: 161\nThe Details: 184\n","choices":[{"letter":"A","text":"MTTR"},{"letter":"B","text":"RPO"},{"letter":"C","text":"RTO"},{"letter":"D","text":"MTBF"}],"correct":["D"],"answerPages":[193],"objectives":["5.2"]},{"id":"B23","number":23,"page":149,"clip":[24,29.063,410,184.803],"text":"B23.\tA security administrator is creating a policy to prevent \nthe disclosure of credit card numbers in a customer \nsupport application. Users of the application would \nonly be able to view the last four digits of a credit card \nnumber. Which of the following would provide this \nfunctionality?\n \n❍A. Hashing\n \n❍B. Tokenization\n \n❍C. Masking\n \n❍D. Salting\nQuick \nAnswer: 161\nThe Details: 185\n","choices":[{"letter":"A","text":"Hashing"},{"letter":"B","text":"Tokenization"},{"letter":"C","text":"Masking"},{"letter":"D","text":"Salting"}],"correct":["C"],"answerPages":[194],"objectives":["3.3"]},{"id":"B24","number":24,"page":149,"clip":[24,186.803,410,302.943],"text":"B24.\tA user is authenticating through the use of a PIN and a \nfingerprint. Which of the following would describe these \nauthentication factors?\n \n❍A. Something you know, something you are\n \n❍B. Something you are, somewhere you are\n \n❍C. Something you have, something you know\n \n❍D. Somewhere you are, something you are\nQuick \nAnswer: 161\nThe Details: 186\n","choices":[{"letter":"A","text":"Something you know, something you are"},{"letter":"B","text":"Something you are, somewhere you are"},{"letter":"C","text":"Something you have, something you know"},{"letter":"D","text":"Somewhere you are, something you are"}],"correct":["A"],"answerPages":[195],"objectives":["4.6"]},{"id":"B25","number":25,"page":149,"clip":[24,304.943,410,610],"text":"140\nPractice Exam B - Questions\nB25.\tA security administrator is configuring the \nauthentication process used by technicians when logging \ninto wireless access points and switches. Instead of using \nlocal accounts, the administrator would like to pass all \nlogin requests to a centralized database. Which of the \nfollowing would be the BEST way to implement this \nrequirement?\n \n❍A. COPE \n \n❍B. AAA\n \n❍C. IPsec\n \n❍D. SIEM\nQuick \nAnswer: 161\nThe Details: 187\n","choices":[{"letter":"A","text":"COPE"},{"letter":"B","text":"AAA"},{"letter":"C","text":"IPsec"},{"letter":"D","text":"SIEM"}],"correct":["B"],"answerPages":[196],"objectives":["4.1"]},{"id":"B26","number":26,"page":150,"clip":[24,29.063,410,171.603],"text":"B26.\tA recent audit has determined that many IT department \naccounts have been granted Administrator access. The \naudit recommends replacing these permissions with \nlimited access rights. Which of the following would \ndescribe this policy?\n \n❍A. Password vaulting\n \n❍B. Offboarding\n \n❍C. Least privilege\n \n❍D. Discretionary access control\nQuick \nAnswer: 161\nThe Details: 188\n","choices":[{"letter":"A","text":"Password vaulting"},{"letter":"B","text":"Offboarding"},{"letter":"C","text":"Least privilege"},{"letter":"D","text":"Discretionary access control"}],"correct":["C"],"answerPages":[197],"objectives":["4.6"]},{"id":"B27","number":27,"page":150,"clip":[24,173.603,410,289.743],"text":"B27.\tA recent security audit has discovered email addresses \nand passwords located in a packet capture. Which of the \nfollowing did the audit identify?\n \n❍A. Weak encryption\n \n❍B. Improper patch management\n \n❍C. Insecure protocols\n \n❍D. Open ports\nQuick \nAnswer: 161\nThe Details: 189\n","choices":[{"letter":"A","text":"Weak encryption"},{"letter":"B","text":"Improper patch management"},{"letter":"C","text":"Insecure protocols"},{"letter":"D","text":"Open ports"}],"correct":["C"],"answerPages":[198],"objectives":["4.5"]},{"id":"B28","number":28,"page":150,"clip":[24,291.743,410,434.283],"text":"B28.\tBefore deploying a new application, a company is \nperforming an internal audit to ensure all of their  \nservers are configured with the appropriate security \nfeatures. Which of the following would BEST describe \nthis process?\n \n❍A. Due care\n \n❍B. Active reconnaissance\n \n❍C. Data retention\n \n❍D. Statement of work\nQuick \nAnswer: 161\nThe Details: 190\n","choices":[{"letter":"A","text":"Due care"},{"letter":"B","text":"Active reconnaissance"},{"letter":"C","text":"Data retention"},{"letter":"D","text":"Statement of work"}],"correct":["A"],"answerPages":[199],"objectives":["5.4"]},{"id":"B29","number":29,"page":150,"clip":[24,436.283,410,610],"text":"141\nPractice Exam B - Questions\nB29.\tAn organization has previously purchased insurance to \ncover a ransomware attack, but the costs of maintaining \nthe policy have increased above the acceptable budget. \nThe company has now decided to cancel the insurance \npolicies and address potential ransomware issues \ninternally. Which of the following would best describe \nthis action?\n \n❍A. Mitigation\n \n❍B. Acceptance\n \n❍C. Transference\n \n❍D. Risk-avoidance\nQuick \nAnswer: 161\nThe Details: 191\n","choices":[{"letter":"A","text":"Mitigation"},{"letter":"B","text":"Acceptance"},{"letter":"C","text":"Transference"},{"letter":"D","text":"Risk-avoidance"}],"correct":["B"],"answerPages":[200],"objectives":["5.2"]},{"id":"B30","number":30,"page":151,"clip":[24,29.063,410,145.203],"text":"B30.\tWhich of these threat actors would be MOST likely to \ninstall a company's internal application on a public cloud \nprovider?\n \n❍A. Organized crime \n \n❍B. Nation state\n \n❍C. Shadow IT\n \n❍D. Hacktivist\nQuick \nAnswer: 161\nThe Details: 192\n","choices":[{"letter":"A","text":"Organized crime"},{"letter":"B","text":"Nation state"},{"letter":"C","text":"Shadow IT"},{"letter":"D","text":"Hacktivist"}],"correct":["C"],"answerPages":[201],"objectives":["2.1"]},{"id":"B31","number":31,"page":151,"clip":[24,147.203,410,316.143],"text":"B31.\tAn IPS report shows a series of exploit attempts were \nmade against externally facing web servers. The system \nadministrator of the web servers has identified a number \nof unusual log entries on each system. Which of the \nfollowing would be the NEXT step in the incident \nresponse process?\n \n❍A. Check the IPS logs for any other potential attacks \n \n❍B. Create a plan for removing malware from the  \nweb servers\n \n❍C. Disable any breached user accounts\n \n❍D. Disconnect the web servers from the network\nQuick \nAnswer: 161\nThe Details: 193\n","choices":[{"letter":"A","text":"Check the IPS logs for any other potential attacks"},{"letter":"B","text":"Create a plan for removing malware from the web servers"},{"letter":"C","text":"Disable any breached user accounts"},{"letter":"D","text":"Disconnect the web servers from the network"}],"correct":["D"],"answerPages":[202],"objectives":["4.8"]},{"id":"B32","number":32,"page":151,"clip":[24,318.143,410,610],"text":"142\nPractice Exam B - Questions\nB32.\tA security administrator is viewing the logs on a laptop \nin the shipping and receiving department and identifies \nthese events: \nWhich of the following would BEST describe the \ncircumstances surrounding these events?\n \n❍A. The antivirus application identified three  \nviruses and quarantined two viruses \n \n❍B. The host-based firewall blocked two traffic flows\n \n❍C. A host-based allow list has blocked two  \napplications from executing\n \n❍D. A network-based IPS has identified two  \nknown vulnerabilities\n8:55:30 AM | D:\\Downloads\\ChangeLog-5.0.4.scr | Quarantine Success\n9:22:54 AM | C:\\Program Files\\Photo Viewer\\ViewerBase.dll | Quarantine Failure\n9:44:05 AM | C:\\Sales\\Sample32.dat | Quarantine Success\nQuick \nAnswer: 161\nThe Details: 194\n","choices":[{"letter":"A","text":"The antivirus application identified three viruses and quarantined two viruses"},{"letter":"B","text":"The host-based firewall blocked two traffic flows"},{"letter":"C","text":"A host-based allow list has blocked two applications from executing"},{"letter":"D","text":"A network-based IPS has identified two known vulnerabilities"}],"correct":["A"],"answerPages":[203,204],"objectives":[]},{"id":"B33","number":33,"page":152,"clip":[24,29.063,410,198.003],"text":"B33.\tIn the past, an organization has relied on the curated \nApple App Store to avoid issues associated with malware \nand insecure applications. However, the IT department \nhas discovered an iPhone in the shipping department \nwith applications not available on the Apple App Store. \nHow did the shipping department user install these apps \non their mobile device?\n \n❍A. Side loading\n \n❍B. Malicious update\n \n❍C. VM escape\n \n❍D. Cross-site scripting\nQuick \nAnswer: 161\nThe Details: 196\n","choices":[{"letter":"A","text":"Side loading"},{"letter":"B","text":"Malicious update"},{"letter":"C","text":"VM escape"},{"letter":"D","text":"Cross-site scripting"}],"correct":["A"],"answerPages":[205],"objectives":["2.3"]},{"id":"B34","number":34,"page":152,"clip":[24,200.003,410,342.543],"text":"B34.\tA company has noticed an increase in support calls from \nattackers. These attackers are using social engineering \nto gain unauthorized access to customer data. Which of \nthe following would be the BEST way to prevent these \nattacks?\n \n❍A. User training\n \n❍B. Next-generation firewall\n \n❍C. Internal audit\n \n❍D. Penetration testing\nQuick \nAnswer: 161\nThe Details: 197\n","choices":[{"letter":"A","text":"User training"},{"letter":"B","text":"Next-generation firewall"},{"letter":"C","text":"Internal audit"},{"letter":"D","text":"Penetration testing"}],"correct":["A"],"answerPages":[206],"objectives":["5.6"]},{"id":"B35","number":35,"page":152,"clip":[24,344.543,410,473.883],"text":"B35.\tAs part of an internal audit, each department of a \ncompany has been asked to compile a list of all devices, \noperating systems, and applications in use. Which of the \nfollowing would BEST describe this audit?\n \n❍A. Attestation\n \n❍B. Self-assessment\n \n❍C. Regulatory compliance\n \n❍D. Vendor monitoring\nQuick \nAnswer: 161\nThe Details: 198\n","choices":[{"letter":"A","text":"Attestation"},{"letter":"B","text":"Self-assessment"},{"letter":"C","text":"Regulatory compliance"},{"letter":"D","text":"Vendor monitoring"}],"correct":["B"],"answerPages":[207],"objectives":["5.5"]},{"id":"B36","number":36,"page":152,"clip":[24,475.883,410,610],"text":"143\nPractice Exam B - Questions\nB36.\tA company is concerned about security issues at their \nremote sites. Which of the following would provide \nthe IT team with more information of  potential \nshortcomings?\n \n❍A. Gap analysis\n \n❍B. Policy administrator\n \n❍C. Change management\n \n❍D. Dependency list\nQuick \nAnswer: 161\nThe Details: 199\n","choices":[{"letter":"A","text":"Gap analysis"},{"letter":"B","text":"Policy administrator"},{"letter":"C","text":"Change management"},{"letter":"D","text":"Dependency list"}],"correct":["A"],"answerPages":[208],"objectives":["1.2"]},{"id":"B37","number":37,"page":153,"clip":[24,29.063,410,158.403],"text":"B37.\tAn attacker has identified a number of devices on a \ncorporate network with the username of “admin” and the \npassword of “admin.” Which of the following describes \nthis situation?\n \n❍A. Open service ports\n \n❍B. Default credentials\n \n❍C. Unsupported systems\n \n❍D. Phishing\nQuick \nAnswer: 161\nThe Details: 200\n","choices":[{"letter":"A","text":"Open service ports"},{"letter":"B","text":"Default credentials"},{"letter":"C","text":"Unsupported systems"},{"letter":"D","text":"Phishing"}],"correct":["B"],"answerPages":[209],"objectives":["2.2"]},{"id":"B38","number":38,"page":153,"clip":[24,160.403,410,289.743],"text":"B38.\tA security administrator attends an annual industry \nconvention with other security professionals from around \nthe world. Which of the following attacks would be \nMOST likely in this situation?\n \n❍A. Smishing\n \n❍B. Supply chain\n \n❍C. SQL injection\n \n❍D. Watering hole\nQuick \nAnswer: 161\nThe Details: 201\n","choices":[{"letter":"A","text":"Smishing"},{"letter":"B","text":"Supply chain"},{"letter":"C","text":"SQL injection"},{"letter":"D","text":"Watering hole"}],"correct":["D"],"answerPages":[210],"objectives":["2.2"]},{"id":"B39","number":39,"page":153,"clip":[24,291.743,410,610],"text":"144\nPractice Exam B - Questions\nB39.\tA transportation company headquarters is located in an \narea with frequent power surges and outages. The security \nadministrator is concerned about the potential for \ndowntime and hardware failures. Which of the following \nwould provide the most protection against these issues? \nSelect TWO.\n \n❍A. UPS\n \n❍B. Parallel processing\n \n❍C. Snapshots\n \n❍D. Multi-cloud system\n \n❍E. Load balancing\n \n❍F. Generator\nQuick \nAnswer: 161\nThe Details: 202\n","choices":[{"letter":"A","text":"UPS"},{"letter":"B","text":"Parallel processing"},{"letter":"C","text":"Snapshots"},{"letter":"D","text":"Multi-cloud system"},{"letter":"E","text":"Load balancing"},{"letter":"F","text":"Generator"}],"correct":["A","F"],"answerPages":[211],"objectives":["3.4"]},{"id":"B40","number":40,"page":154,"clip":[24,29.063,410,184.803],"text":"B40.\tAn organization has developed an in-house mobile \ndevice app for order processing. The developers would \nlike the app to identify revoked server certificates \nwithout sending any traffic over the corporate Internet \nconnection. Which of the following must be configured \nto allow this functionality?\n \n❍A. CSR generation\n \n❍B. OCSP stapling\n \n❍C. Key escrow\n \n❍D. Wildcard\nQuick \nAnswer: 161\nThe Details: 203\n","choices":[{"letter":"A","text":"CSR generation"},{"letter":"B","text":"OCSP stapling"},{"letter":"C","text":"Key escrow"},{"letter":"D","text":"Wildcard"}],"correct":["B"],"answerPages":[212],"objectives":["1.4"]},{"id":"B41","number":41,"page":154,"clip":[24,186.803,410,316.143],"text":"B41.\tA security administrator has been asked to build a \nnetwork link to secure all communication between two \nremote locations. Which of the following would be the \nbest choice for this task?\n \n❍A. SCAP\n \n❍B. Screened subnet\n \n❍C. IPsec\n \n❍D. Network access control\nQuick \nAnswer: 161\nThe Details: 204\n","choices":[{"letter":"A","text":"SCAP"},{"letter":"B","text":"Screened subnet"},{"letter":"C","text":"IPsec"},{"letter":"D","text":"Network access control"}],"correct":["C"],"answerPages":[213],"objectives":["3.2"]},{"id":"B42","number":42,"page":154,"clip":[24,318.143,410,610],"text":"145\nPractice Exam B - Questions\nB42.\tA Linux administrator has received a ticket complaining \nof response issues with a database server. After \nconnecting to the server, the administrator views  \nthis information: \nWhich of the following would BEST describe this \ninformation?\n \n❍A. Buffer overflow\n \n❍B. Resource consumption\n \n❍C. SQL injection\n \n❍D. Race condition\nFilesystem  Size  Used Avail Use% Mounted on\n/dev/xvda1  158G  158G     0 100% /\nQuick \nAnswer: 161\nThe Details: 205\n","choices":[{"letter":"A","text":"Buffer overflow"},{"letter":"B","text":"Resource consumption"},{"letter":"C","text":"SQL injection"},{"letter":"D","text":"Race condition"}],"correct":["B"],"answerPages":[214],"objectives":["2.4"]},{"id":"B43","number":43,"page":155,"clip":[24,29.063,410,145.203],"text":"B43.\tWhich of the following can be used for credit card \ntransactions from a mobile device without sending the \nactual credit card number across the network?\n \n❍A. Tokenization\n \n❍B. Hashing\n \n❍C. Steganography\n \n❍D. Masking\nQuick \nAnswer: 161\nThe Details: 206\n","choices":[{"letter":"A","text":"Tokenization"},{"letter":"B","text":"Hashing"},{"letter":"C","text":"Steganography"},{"letter":"D","text":"Masking"}],"correct":["A"],"answerPages":[215],"objectives":["3.3"]},{"id":"B44","number":44,"page":155,"clip":[24,147.203,410,276.543],"text":"B44.\tA security administrator receives a report each week \nshowing a Linux vulnerability associated with a \nWindows server. Which of the following would prevent \nthis information from appearing in the report?\n \n❍A. Alert tuning\n \n❍B. Application benchmarking\n \n❍C. SIEM aggregation\n \n❍D. Data archiving\nQuick \nAnswer: 161\nThe Details: 207\n","choices":[{"letter":"A","text":"Alert tuning"},{"letter":"B","text":"Application benchmarking"},{"letter":"C","text":"SIEM aggregation"},{"letter":"D","text":"Data archiving"}],"correct":["A"],"answerPages":[216],"objectives":["4.4"]},{"id":"B45","number":45,"page":155,"clip":[24,278.543,410,394.683],"text":"B45.\tWhich of the following would a company use to \ncalculate the loss of a business activity if a vulnerability is \nexploited?\n \n❍A. Risk tolerance\n \n❍B. Vulnerability classification\n \n❍C. Environmental variables\n \n❍D. Exposure factor\nQuick \nAnswer: 161\nThe Details: 208\n","choices":[{"letter":"A","text":"Risk tolerance"},{"letter":"B","text":"Vulnerability classification"},{"letter":"C","text":"Environmental variables"},{"letter":"D","text":"Exposure factor"}],"correct":["D"],"answerPages":[217],"objectives":["4.3"]},{"id":"B46","number":46,"page":155,"clip":[24,396.683,410,610],"text":"146\nPractice Exam B - Questions\nB46.\tAn administrator is designing a network to be compliant \nwith a security standard for storing credit card numbers. \nWhich of the following would be the BEST choice to \nprovide this compliance?\n \n❍A. Implement RAID for all storage systems\n \n❍B. Connect a UPS to all servers\n \n❍C. DNS should be available on redundant servers\n \n❍D. Perform regular audits and vulnerability scans\nQuick \nAnswer: 161\nThe Details: 209\n","choices":[{"letter":"A","text":"Implement RAID for all storage systems"},{"letter":"B","text":"Connect a UPS to all servers"},{"letter":"C","text":"DNS should be available on redundant servers"},{"letter":"D","text":"Perform regular audits and vulnerability scans"}],"correct":["D"],"answerPages":[218],"objectives":["5.4"]},{"id":"B47","number":47,"page":156,"clip":[24,29.063,410,158.403],"text":"B47.\tA company is accepting proposals for an upcoming \nproject, and one of the responses is from a business \nowned by a board member. Which of the following \nwould describe this situation?\n \n❍A. Due diligence\n \n❍B. Vendor monitoring\n \n❍C. Conflict of interest\n \n❍D. Right-to-audit\nQuick \nAnswer: 161\nThe Details: 210\n","choices":[{"letter":"A","text":"Due diligence"},{"letter":"B","text":"Vendor monitoring"},{"letter":"C","text":"Conflict of interest"},{"letter":"D","text":"Right-to-audit"}],"correct":["C"],"answerPages":[219],"objectives":["5.3"]},{"id":"B48","number":48,"page":156,"clip":[24,160.403,410,289.743],"text":"B48.\tA company has rolled out a new application that requires \nthe use of a hardware-based token generator. Which of \nthe following would be the BEST description of this \naccess feature?\n \n❍A. Something you know\n \n❍B. Somewhere you are\n \n❍C. Something you are\n \n❍D. Something you have\nQuick \nAnswer: 161\nThe Details: 211\n","choices":[{"letter":"A","text":"Something you know"},{"letter":"B","text":"Somewhere you are"},{"letter":"C","text":"Something you are"},{"letter":"D","text":"Something you have"}],"correct":["D"],"answerPages":[220],"objectives":["4.6"]},{"id":"B49","number":49,"page":156,"clip":[24,291.743,410,447.483],"text":"B49.\tA company has signed an SLA with an Internet service \nprovider. Which of the following would BEST describe \nthe requirements of this SLA?\n \n❍A. The customer will connect to remote sites over  \nan IPsec tunnel \n \n❍B. The service provider will provide 99.99% uptime\n \n❍C. The customer applications use HTTPS over \ntcp/443\n \n❍D. Customer application use will be busiest on the \n15th of each month\nQuick \nAnswer: 161\nThe Details: 212\n","choices":[{"letter":"A","text":"The customer will connect to remote sites over an IPsec tunnel"},{"letter":"B","text":"The service provider will provide 99.99% uptime"},{"letter":"C","text":"The customer applications use HTTPS over tcp/443"},{"letter":"D","text":"Customer application use will be busiest on the 15th of each month"}],"correct":["B"],"answerPages":[221],"objectives":["5.3"]},{"id":"B50","number":50,"page":156,"clip":[24,449.483,410,610],"text":"147\nPractice Exam B - Questions\nB50.\tAn attacker has created multiple social media accounts \nand is posting information in an attempt to get the \nattention of the media. Which of the following would \nBEST describe this attack?\n \n❍A. On-path\n \n❍B. Watering hole\n \n❍C. Misinformation campaign\n \n❍D. Phishing\nQuick \nAnswer: 161\nThe Details: 213\n","choices":[{"letter":"A","text":"On-path"},{"letter":"B","text":"Watering hole"},{"letter":"C","text":"Misinformation campaign"},{"letter":"D","text":"Phishing"}],"correct":["C"],"answerPages":[222],"objectives":["2.4"]},{"id":"B51","number":51,"page":157,"clip":[24,29.063,410,145.203],"text":"B51.\tWhich of the following would be the BEST way to \nprotect credit card account information when performing \nreal-time purchase authorizations?\n \n❍A. Masking\n \n❍B. DLP\n \n❍C. Tokenization\n \n❍D. NGFW \nQuick \nAnswer: 161\nThe Details: 214\n","choices":[{"letter":"A","text":"Masking"},{"letter":"B","text":"DLP"},{"letter":"C","text":"Tokenization"},{"letter":"D","text":"NGFW"}],"correct":["C"],"answerPages":[223],"objectives":["3.3"]},{"id":"B52","number":52,"page":157,"clip":[24,147.203,410,276.543],"text":"B52.\tA company must comply with legal requirements \nfor storing customer data in the same country as the \ncustomer's mailing address. Which of the following \nwould describe this requirement?\n \n❍A. Geographic dispersion\n \n❍B. Least privilege\n \n❍C. Data sovereignty\n \n❍D. Exfiltration \nQuick \nAnswer: 161\nThe Details: 215\n","choices":[{"letter":"A","text":"Geographic dispersion"},{"letter":"B","text":"Least privilege"},{"letter":"C","text":"Data sovereignty"},{"letter":"D","text":"Exfiltration"}],"correct":["C"],"answerPages":[224],"objectives":["3.3"]},{"id":"B53","number":53,"page":157,"clip":[24,278.543,410,394.683],"text":"B53.\tA company is installing access points in all of their \nremote sites. Which of the following would provide \nconfidentiality for all wireless data?\n \n❍A. 802.1X\n \n❍B. WPA3\n \n❍C. RADIUS\n \n❍D. MDM \nQuick \nAnswer: 161\nThe Details: 216\n","choices":[{"letter":"A","text":"802.1X"},{"letter":"B","text":"WPA3"},{"letter":"C","text":"RADIUS"},{"letter":"D","text":"MDM"}],"correct":["B"],"answerPages":[225],"objectives":["4.1"]},{"id":"B54","number":54,"page":157,"clip":[24,396.683,410,610],"text":"148\nPractice Exam B - Questions\nB54.\tA security administrator has found a keylogger installed \nin an update of the company's accounting software. \nWhich of the following would prevent the transmission \nof the collected logs?\n \n❍A. Prevent the installation of all software \n \n❍B. Block all unknown outbound network traffic  \nat the Internet firewall\n \n❍C. Install host-based anti-virus software\n \n❍D. Scan all incoming email attachments at  \nthe email gateway \nQuick \nAnswer: 161\nThe Details: 217\n","choices":[{"letter":"A","text":"Prevent the installation of all software"},{"letter":"B","text":"Block all unknown outbound network traffic at the Internet firewall"},{"letter":"C","text":"Install host-based anti-virus software"},{"letter":"D","text":"Scan all incoming email attachments at the email gateway"}],"correct":["B"],"answerPages":[226],"objectives":["2.4"]},{"id":"B55","number":55,"page":158,"clip":[24,29.063,410,359.285],"text":"B55.\tA user in the marketing department is unable to connect \nto the wireless network. After authenticating with a \nusername and password, the user receives this message: \nThe AP is configured with WPA3 encryption and  \n802.1X authentication. \n \nWhich of the following is the MOST likely reason for \nthis login issue?\n \n❍A. The user’s computer is in the incorrect VLAN \n \n❍B. The RADIUS server is not responding\n \n❍C. The user’s computer does not support  \nWPA3 encryption\n \n❍D. The user is in a location with an insufficient \nwireless signal \n \n❍E. The client computer does not have the proper \ncertificate installed\nQuick \nAnswer: 161\nThe Details: 218\n-- -- -- \nThe connection attempt could not be completed.  \nThe Credentials provided by the server could not be validated. \nRadius Server: radius.example.com \nRoot CA: Example.com Internal CA Root Certificate \n-- -- -- \n","choices":[{"letter":"A","text":"The user’s computer is in the incorrect VLAN"},{"letter":"B","text":"The RADIUS server is not responding"},{"letter":"C","text":"The user’s computer does not support WPA3 encryption"},{"letter":"D","text":"The user is in a location with an insufficient wireless signal"},{"letter":"E","text":"The client computer does not have the proper certificate installed"}],"correct":["E"],"answerPages":[227,228],"objectives":[]},{"id":"B56","number":56,"page":158,"clip":[24,361.285,410,610],"text":"149\nPractice Exam B - Questions\nB56.\tA security administrator has created a new policy \nprohibiting the use of MD5 hashes due to collision \nproblems. Which of the following describes the reason \nfor this new policy?\n \n❍A. Two different messages have different hashes \n \n❍B. The original message can be derived from the hash\n \n❍C. Two identical messages have the same hash\n \n❍D. Two different messages share the same hash \nQuick \nAnswer: 161\nThe Details: 220\n","choices":[{"letter":"A","text":"Two different messages have different hashes"},{"letter":"B","text":"The original message can be derived from the hash"},{"letter":"C","text":"Two identical messages have the same hash"},{"letter":"D","text":"Two different messages share the same hash"}],"correct":["D"],"answerPages":[229],"objectives":["2.4"]},{"id":"B57","number":57,"page":159,"clip":[24,29.063,410,187.685],"text":"B57.\tA security administrator has been tasked with hardening \nall internal web servers to control access from certain \nIP address ranges and ensure all transferred data \nremains confidential. Which of the following should the \nadministrator include in his project plan? (Select TWO)\n \n❍A. Change the administrator password\n \n❍B. Use HTTPS for all server communication\n \n❍C. Uninstall all unused software\n \n❍D. Enable a host-based firewall\n \n❍E. Install the latest operating system update \nQuick \nAnswer: 161\nThe Details: 221\n","choices":[{"letter":"A","text":"Change the administrator password"},{"letter":"B","text":"Use HTTPS for all server communication"},{"letter":"C","text":"Uninstall all unused software"},{"letter":"D","text":"Enable a host-based firewall"},{"letter":"E","text":"Install the latest operating system update"}],"correct":["B","D"],"answerPages":[230],"objectives":["2.5"]},{"id":"B58","number":58,"page":159,"clip":[24,189.685,410,319.025],"text":"B58.\tA security administrator has identified the installation of \nransomware on a database server and has quarantined the \nsystem. Which of the following should be followed to \nensure that the integrity of the evidence is maintained?\n \n❍A. E-discovery\n \n❍B. Non-repudiation\n \n❍C. Chain of custody\n \n❍D. Legal hold \nQuick \nAnswer: 161\nThe Details: 222\n","choices":[{"letter":"A","text":"E-discovery"},{"letter":"B","text":"Non-repudiation"},{"letter":"C","text":"Chain of custody"},{"letter":"D","text":"Legal hold"}],"correct":["C"],"answerPages":[231],"objectives":["4.8"]},{"id":"B59","number":59,"page":159,"clip":[24,321.025,410,437.165],"text":"B59.\tWhich of the following would be the BEST option \nfor application testing in an environment completely \nseparated from the production network?\n \n❍A. Virtualization \n \n❍B. VLANs\n \n❍C. Cloud computing\n \n❍D. Air gap \nQuick \nAnswer: 161\nThe Details: 223\n","choices":[{"letter":"A","text":"Virtualization"},{"letter":"B","text":"VLANs"},{"letter":"C","text":"Cloud computing"},{"letter":"D","text":"Air gap"}],"correct":["D"],"answerPages":[232],"objectives":["3.1"]},{"id":"B60","number":60,"page":159,"clip":[24,439.165,410,610],"text":"150\nPractice Exam B - Questions\nB60.\tA security engineer is planning the installation of a new \nIPS. The network must remain operational if the IPS is \nturned off or disabled. Which of the following would \ndescribe this configuration?\n \n❍A. Containerization\n \n❍B. Load balancing\n \n❍C. Fail open\n \n❍D. Tunneling \nQuick \nAnswer: 161\nThe Details: 224\n","choices":[{"letter":"A","text":"Containerization"},{"letter":"B","text":"Load balancing"},{"letter":"C","text":"Fail open"},{"letter":"D","text":"Tunneling"}],"correct":["C"],"answerPages":[233],"objectives":["3.2"]},{"id":"B61","number":61,"page":160,"clip":[24,29.063,410,145.203],"text":"B61.\tWhich of the following describes the process of hiding \ndata from others by embedding the data inside of a \ndifferent media type?\n \n❍A. Hashing \n \n❍B. Obfuscation\n \n❍C. Encryption\n \n❍D. Masking \nQuick \nAnswer: 161\nThe Details: 225\n","choices":[{"letter":"A","text":"Hashing"},{"letter":"B","text":"Obfuscation"},{"letter":"C","text":"Encryption"},{"letter":"D","text":"Masking"}],"correct":["B"],"answerPages":[234],"objectives":["3.3"]},{"id":"B62","number":62,"page":160,"clip":[24,147.203,410,316.143],"text":"B62.\tWhich of the following vulnerabilities would be the \nMOST significant security concern when protecting \nagainst a hacktivist?\n \n❍A. Data center access with only one  \nauthentication factor \n \n❍B. Spoofing of internal IP addresses when  \naccessing an intranet server\n \n❍C. Employee VPN access uses a weak  \nencryption cipher\n \n❍D. Lack of patch updates on an Internet-facing \ndatabase server \nQuick \nAnswer: 161\nThe Details: 226\n","choices":[{"letter":"A","text":"Data center access with only one authentication factor"},{"letter":"B","text":"Spoofing of internal IP addresses when accessing an intranet server"},{"letter":"C","text":"Employee VPN access uses a weak encryption cipher"},{"letter":"D","text":"Lack of patch updates on an Internet-facing database server"}],"correct":["D"],"answerPages":[235],"objectives":["2.1"]},{"id":"B63","number":63,"page":160,"clip":[24,318.143,410,447.483],"text":"B63.\tA company is installing a security appliance to protect \nthe organization's web-based applications from attacks \nsuch as SQL injections and unexpected input. Which of \nthe following would BEST describe this appliance?\n \n❍A. WAF\n \n❍B. VPN concentrator\n \n❍C. UTM\n \n❍D. SASE \nQuick \nAnswer: 161\nThe Details: 227\n","choices":[{"letter":"A","text":"WAF"},{"letter":"B","text":"VPN concentrator"},{"letter":"C","text":"UTM"},{"letter":"D","text":"SASE"}],"correct":["A"],"answerPages":[236],"objectives":["3.2"]},{"id":"B64","number":64,"page":160,"clip":[24,449.483,410,610],"text":"151\nPractice Exam B - Questions\nB64.\tWhich of the following would be the BEST way to \ndetermine if files have been modified after the forensics \ndata acquisition process has occurred?\n \n❍A. Use a tamper seal on all storage devices \n \n❍B. Create a hash of the data\n \n❍C. Image each storage device for future comparison\n \n❍D. Take screenshots of file directories with file sizes \nQuick \nAnswer: 161\nThe Details: 228\n","choices":[{"letter":"A","text":"Use a tamper seal on all storage devices"},{"letter":"B","text":"Create a hash of the data"},{"letter":"C","text":"Image each storage device for future comparison"},{"letter":"D","text":"Take screenshots of file directories with file sizes"}],"correct":["B"],"answerPages":[237],"objectives":["4.8"]},{"id":"B65","number":65,"page":161,"clip":[24,29.063,410,171.603],"text":"B65.\tA system administrator is implementing a password \npolicy that would require letters, numbers, and special \ncharacters to be included in every password. Which of \nthe following controls MUST be in place to enforce this \npassword policy?\n \n❍A. Length \n \n❍B. Expiration\n \n❍C. Reuse\n \n❍D. Complexity\nQuick \nAnswer: 161\nThe Details: 229\n","choices":[{"letter":"A","text":"Length"},{"letter":"B","text":"Expiration"},{"letter":"C","text":"Reuse"},{"letter":"D","text":"Complexity"}],"correct":["D"],"answerPages":[238],"objectives":["4.6"]},{"id":"B66","number":66,"page":161,"clip":[24,173.603,410,276.543],"text":"B66.\tWhich of the following would a company follow to \ndeploy a weekly operating system patch?\n \n❍A. Tabletop exercise\n \n❍B. Penetration testing\n \n❍C. Change management\n \n❍D. Internal audit\nQuick \nAnswer: 161\nThe Details: 230\n","choices":[{"letter":"A","text":"Tabletop exercise"},{"letter":"B","text":"Penetration testing"},{"letter":"C","text":"Change management"},{"letter":"D","text":"Internal audit"}],"correct":["C"],"answerPages":[239],"objectives":["1.3"]},{"id":"B67","number":67,"page":161,"clip":[24,278.543,410,381.483],"text":"B67.\tWhich of the following would be the MOST likely \nresult of plaintext application communication?\n \n❍A. Buffer overflow\n \n❍B. Replay attack\n \n❍C. Resource consumption\n \n❍D. Directory traversal\nQuick \nAnswer: 161\nThe Details: 231\n","choices":[{"letter":"A","text":"Buffer overflow"},{"letter":"B","text":"Replay attack"},{"letter":"C","text":"Resource consumption"},{"letter":"D","text":"Directory traversal"}],"correct":["B"],"answerPages":[240],"objectives":["2.4"]},{"id":"B68","number":68,"page":161,"clip":[24,383.483,410,610],"text":"152\nPractice Exam B - Questions\nB68.\tA system administrator believes that certain \nconfiguration files on a Linux server have been modified \nfrom their original state. The administrator has reverted \nthe configurations to their original state, but he would \nlike to be notified if they are changed again. Which of \nthe following would be the BEST way to provide this \nfunctionality?\n \n❍A. HIPS\n \n❍B. File integrity monitoring\n \n❍C. Application allow list\n \n❍D. WAF\nQuick \nAnswer: 161\nThe Details: 232\n","choices":[{"letter":"A","text":"HIPS"},{"letter":"B","text":"File integrity monitoring"},{"letter":"C","text":"Application allow list"},{"letter":"D","text":"WAF"}],"correct":["B"],"answerPages":[241],"objectives":["4.5"]},{"id":"B69","number":69,"page":162,"clip":[24,29.063,410,145.203],"text":"B69.\tA security administrator is updating the network \ninfrastructure to support 802.1X. Which of the following \nwould be the BEST choice for this configuration?\n \n❍A. LDAP \n \n❍B. SIEM\n \n❍C. SNMP traps\n \n❍D. SPF \nQuick \nAnswer: 161\nThe Details: 233\n","choices":[{"letter":"A","text":"LDAP"},{"letter":"B","text":"SIEM"},{"letter":"C","text":"SNMP traps"},{"letter":"D","text":"SPF"}],"correct":["A"],"answerPages":[242],"objectives":["4.6"]},{"id":"B70","number":70,"page":162,"clip":[24,147.203,410,276.543],"text":"B70.\tA company owns a time clock appliance, but the time \nclock doesn’t provide any access to the operating system \nand it doesn't provide a method to upgrade the firmware. \nWhich of the following describes this appliance?\n \n❍A. End-of-life\n \n❍B. ICS\n \n❍C. SDN\n \n❍D. Embedded system \nQuick \nAnswer: 161\nThe Details: 234\n","choices":[{"letter":"A","text":"End-of-life"},{"letter":"B","text":"ICS"},{"letter":"C","text":"SDN"},{"letter":"D","text":"Embedded system"}],"correct":["D"],"answerPages":[243],"objectives":["3.1"]},{"id":"B71","number":71,"page":162,"clip":[24,278.543,410,610],"text":"153\nPractice Exam B - Questions\nB71.\tA company has deployed laptops to all employees, and \neach laptop is enumerated during each login. Which of \nthe following is supported with this configuration?\n \n❍A. If the laptop hardware is modified, the security \nteam is alerted\n \n❍B. Any malware identified on the system is \nautomatically deleted\n \n❍C. Users are required to use at least two factors  \nof authentication\n \n❍D. The laptop is added to a private VLAN after the \nlogin process \nQuick \nAnswer: 161\nThe Details: 235\n","choices":[{"letter":"A","text":"If the laptop hardware is modified, the security team is alerted"},{"letter":"B","text":"Any malware identified on the system is automatically deleted"},{"letter":"C","text":"Users are required to use at least two factors of authentication"},{"letter":"D","text":"The laptop is added to a private VLAN after the login process"}],"correct":["A"],"answerPages":[244],"objectives":["4.2"]},{"id":"B72","number":72,"page":163,"clip":[24,29.063,410,187.685],"text":"B72.\tA security manager believes that an employee is using \ntheir laptop to circumvent the corporate Internet security \ncontrols through the use of a cellular hotspot. Which \nof the following could be used to validate this belief? \n(Select TWO)\n \n❍A. HIPS\n \n❍B. UTM logs\n \n❍C. Web application firewall events\n \n❍D. Host-based firewall logs\n \n❍E. Next-generation firewall logs \nQuick \nAnswer: 161\nThe Details: 236\n","choices":[{"letter":"A","text":"HIPS"},{"letter":"B","text":"UTM logs"},{"letter":"C","text":"Web application firewall events"},{"letter":"D","text":"Host-based firewall logs"},{"letter":"E","text":"Next-generation firewall logs"}],"correct":["A","D"],"answerPages":[245],"objectives":["2.5"]},{"id":"B73","number":73,"page":163,"clip":[24,189.685,410,319.025],"text":"B73.\tAn application developer is creating a mobile device \napp that will require a true random number generator \nreal-time memory encryption. Which of the following \ntechnologies would be the BEST choice for this app?\n \n❍A. HSM\n \n❍B. Secure enclave\n \n❍C. NGFW\n \n❍D. Self-signed certificates \nQuick \nAnswer: 161\nThe Details: 237\n","choices":[{"letter":"A","text":"HSM"},{"letter":"B","text":"Secure enclave"},{"letter":"C","text":"NGFW"},{"letter":"D","text":"Self-signed certificates"}],"correct":["B"],"answerPages":[246],"objectives":["1.4"]},{"id":"B74","number":74,"page":163,"clip":[24,321.025,410,423.965],"text":"B74.\tWhich of the following would be a common result of a \nsuccessful vulnerability scan?\n \n❍A. Usernames and password hashes from a server \n \n❍B. A list of missing software patches\n \n❍C. A copy of image files from a private file share\n \n❍D. The BIOS configuration of a server \nQuick \nAnswer: 161\nThe Details: 238\n","choices":[{"letter":"A","text":"Usernames and password hashes from a server"},{"letter":"B","text":"A list of missing software patches"},{"letter":"C","text":"A copy of image files from a private file share"},{"letter":"D","text":"The BIOS configuration of a server"}],"correct":["B"],"answerPages":[247],"objectives":["4.3"]},{"id":"B75","number":75,"page":163,"clip":[24,425.965,410,610],"text":"154\nPractice Exam B - Questions\nB75.\tWhen connected to the wireless network, users at a \nremote site receive an IP address which is not part of \nthe corporate address scheme. Communication over this \nnetwork is also slower than the wireless connections \nelsewhere in the building. Which of the following would \nbe the MOST likely reason for these issues?\n \n❍A. Rogue access point\n \n❍B. Domain hijack\n \n❍C. DDoS\n \n❍D. Encryption is enabled \nQuick \nAnswer: 161\nThe Details: 239\n","choices":[{"letter":"A","text":"Rogue access point"},{"letter":"B","text":"Domain hijack"},{"letter":"C","text":"DDoS"},{"letter":"D","text":"Encryption is enabled"}],"correct":["A"],"answerPages":[248],"objectives":["2.2"]},{"id":"B76","number":76,"page":164,"clip":[24,29.063,410,171.603],"text":"B76.\tA company has identified a compromised server, and \nthe security team would like to know if an attacker has \nused this device to move between systems. Which of \nthe following would be the BEST way to provide this \ninformation?\n \n❍A. DNS server logs\n \n❍B. Penetration test\n \n❍C. NetFlow logs\n \n❍D. Email metadata \nQuick \nAnswer: 161\nThe Details: 240\n","choices":[{"letter":"A","text":"DNS server logs"},{"letter":"B","text":"Penetration test"},{"letter":"C","text":"NetFlow logs"},{"letter":"D","text":"Email metadata"}],"correct":["C"],"answerPages":[249],"objectives":["4.4"]},{"id":"B77","number":77,"page":164,"clip":[24,173.603,410,316.143],"text":"B77.\tA system administrator has protected a set of \nsystem backups with an encryption key. The system \nadministrator used the same key when restoring files \nfrom this backup. Which of the following would BEST \ndescribe this encryption type?\n \n❍A. Asymmetric \n \n❍B. Key escrow\n \n❍C. Symmetric\n \n❍D. Out-of-band key exchange  \nQuick \nAnswer: 161\nThe Details: 241\n","choices":[{"letter":"A","text":"Asymmetric"},{"letter":"B","text":"Key escrow"},{"letter":"C","text":"Symmetric"},{"letter":"D","text":"Out-of-band key exchange"}],"correct":["C"],"answerPages":[250],"objectives":["1.4"]},{"id":"B78","number":78,"page":164,"clip":[24,318.143,410,610],"text":"155\nPractice Exam B - Questions\nB78.\tA new malware variant takes advantage of a vulnerability \nin a popular email client. Once installed, the malware \nforwards all email attachments containing credit card \ninformation to an external email address. Which of the \nfollowing would limit the scope of this attack?\n \n❍A. Enable MFA on the email client\n \n❍B. Scan outgoing traffic with DLP\n \n❍C. Require users to enable the VPN when  \nusing email\n \n❍D. Update the list of malicious URLs in the firewall \nQuick \nAnswer: 161\nThe Details: 242\n","choices":[{"letter":"A","text":"Enable MFA on the email client"},{"letter":"B","text":"Scan outgoing traffic with DLP"},{"letter":"C","text":"Require users to enable the VPN when using email"},{"letter":"D","text":"Update the list of malicious URLs in the firewall"}],"correct":["B"],"answerPages":[251],"objectives":["4.5"]},{"id":"B79","number":79,"page":165,"clip":[24,29.063,410,174.485],"text":"B79.\tAn organization has identified a security breach and has \nremoved the affected servers from the network. Which of \nthe following is the NEXT step in the incident response \nprocess?\n \n❍A. Eradication\n \n❍B. Preparation\n \n❍C. Recovery\n \n❍D. Detection\n \n❍E. Containment \nQuick \nAnswer: 161\nThe Details: 243\n","choices":[{"letter":"A","text":"Eradication"},{"letter":"B","text":"Preparation"},{"letter":"C","text":"Recovery"},{"letter":"D","text":"Detection"},{"letter":"E","text":"Containment"}],"correct":["A"],"answerPages":[252],"objectives":["4.8"]},{"id":"B80","number":80,"page":165,"clip":[24,176.485,410,305.825],"text":"B80.\tA security administrator has been tasked with storing \nand protecting customer payment and shipping \ninformation for a three-year period. Which of the \nfollowing would describe the source of this data?\n \n❍A. Controller\n \n❍B. Owner\n \n❍C. Data subject\n \n❍D. Processor \nQuick \nAnswer: 161\nThe Details: 244\n","choices":[{"letter":"A","text":"Controller"},{"letter":"B","text":"Owner"},{"letter":"C","text":"Data subject"},{"letter":"D","text":"Processor"}],"correct":["C"],"answerPages":[253],"objectives":["5.4"]},{"id":"B81","number":81,"page":165,"clip":[24,307.825,410,610],"text":"156\nPractice Exam B - Questions\nB81.\tWhich of the following would be the main reasons \nwhy a system administrator would use a TPM when \nconfiguring full disk encryption? (Select TWO)\n \n❍A. Allows the encryption of multiple volumes \n \n❍B. Uses burned-in cryptographic keys\n \n❍C. Stores certificates in a hardware security module\n \n❍D. Maintains a copy of the CRL\n \n❍E. Includes built-in protections against  \nbrute-force attacks\nQuick \nAnswer: 161\nThe Details: 245\n","choices":[{"letter":"A","text":"Allows the encryption of multiple volumes"},{"letter":"B","text":"Uses burned-in cryptographic keys"},{"letter":"C","text":"Stores certificates in a hardware security module"},{"letter":"D","text":"Maintains a copy of the CRL"},{"letter":"E","text":"Includes built-in protections against brute-force attacks"}],"correct":["B","E"],"answerPages":[254],"objectives":["3.2"]},{"id":"B82","number":82,"page":166,"clip":[24,29.063,410,184.803],"text":"B82.\tA security administrator is using an access control \nwhere each file or folder is assigned a security clearance \nlevel, such as “confidential” or “secret.” The security \nadministrator then assigns a maximum security level to \neach user. What type of access control is used in this \nnetwork?\n \n❍A. Mandatory \n \n❍B. Rule-based\n \n❍C. Discretionary\n \n❍D. Role-based \nQuick \nAnswer: 161\nThe Details: 246\n","choices":[{"letter":"A","text":"Mandatory"},{"letter":"B","text":"Rule-based"},{"letter":"C","text":"Discretionary"},{"letter":"D","text":"Role-based"}],"correct":["A"],"answerPages":[255],"objectives":["4.6"]},{"id":"B83","number":83,"page":166,"clip":[24,186.803,410,342.543],"text":"B83.\tCameron, a security administrator, is reviewing a report \nthat shows a number of devices on internal networks \nattempting to connect with servers in the data center \nnetwork. Which of the following security controls should \nCameron add to prevent internal systems from accessing \ndata center devices?\n \n❍A. VPN \n \n❍B. IPS\n \n❍C. SIEM\n \n❍D. ACL \nQuick \nAnswer: 161\nThe Details: 247\n","choices":[{"letter":"A","text":"VPN"},{"letter":"B","text":"IPS"},{"letter":"C","text":"SIEM"},{"letter":"D","text":"ACL"}],"correct":["D"],"answerPages":[256],"objectives":["2.5"]},{"id":"B84","number":84,"page":166,"clip":[24,344.543,410,610],"text":"157\nPractice Exam B - Questions\nB84.\tA financial services company is headquartered in an area \nwith a high occurrence of tropical storms and hurricanes. \nWhich of the following would be MOST important \nwhen restoring services disabled by a storm?\n \n❍A. Disaster recovery plan\n \n❍B. Stakeholder management\n \n❍C. Change management\n \n❍D. Retention policies\nQuick \nAnswer: 161\nThe Details: 248\n","choices":[{"letter":"A","text":"Disaster recovery plan"},{"letter":"B","text":"Stakeholder management"},{"letter":"C","text":"Change management"},{"letter":"D","text":"Retention policies"}],"correct":["A"],"answerPages":[257],"objectives":["4.2"]},{"id":"B85","number":85,"page":167,"clip":[24,29.063,410,214.085],"text":"B85.\tA user in the mail room has reported an overall \nslowdown of his shipping management software. An \nanti-virus scan did not identify any issues, but a more \nthorough malware scan identified a kernel driver which \nis not part of the original operating system installation. \nWhich of the following malware was installed on this \nsystem?\n \n❍A. Rootkit\n \n❍B. Logic bomb\n \n❍C. Bloatware\n \n❍D. Ransomware\n \n❍E. Keylogger\nQuick \nAnswer: 161\nThe Details: 249\n","choices":[{"letter":"A","text":"Rootkit"},{"letter":"B","text":"Logic bomb"},{"letter":"C","text":"Bloatware"},{"letter":"D","text":"Ransomware"},{"letter":"E","text":"Keylogger"}],"correct":["A"],"answerPages":[258],"objectives":["2.4"]},{"id":"B86","number":86,"page":167,"clip":[24,216.085,410,345.425],"text":"B86.\tA virus scanner has identified a macro virus in a word \nprocessing file attached to an email. Which of the \nfollowing information could be obtained from the \nmetadata of this file?\n \n❍A. IPS signature name and number\n \n❍B. Operating system version\n \n❍C. Date and time when the file was created\n \n❍D. Alert disposition\nQuick \nAnswer: 161\nThe Details: 250\n","choices":[{"letter":"A","text":"IPS signature name and number"},{"letter":"B","text":"Operating system version"},{"letter":"C","text":"Date and time when the file was created"},{"letter":"D","text":"Alert disposition"}],"correct":["C"],"answerPages":[259],"objectives":["4.9"]},{"id":"B87","number":87,"page":167,"clip":[24,347.425,410,610],"text":"158\nPractice Exam B - Questions\nB87.\tWhen a person enters a data center facility, they must \ncheck-in before they are allowed to move further into \nthe building. People who are leaving must be formally \nchecked-out before they are able to exit the building. \nWhich of the following would BEST facilitate this \nprocess?\n \n❍A. Access control vestibule \n \n❍B. Air gap\n \n❍C. Pressure sensors\n \n❍D. Bollards \nQuick \nAnswer: 161\nThe Details: 251\n","choices":[{"letter":"A","text":"Access control vestibule"},{"letter":"B","text":"Air gap"},{"letter":"C","text":"Pressure sensors"},{"letter":"D","text":"Bollards"}],"correct":["A"],"answerPages":[260],"objectives":["1.2"]},{"id":"B88","number":88,"page":168,"clip":[24,29.063,410,171.603],"text":"B88.\tA security administrator has discovered an employee \nexfiltrating confidential company information by \nembedding data within image files and emailing the \nimages to a third-party. Which of the following would \nbest describe this activity?\n \n❍A. Digital signatures\n \n❍B. Steganography\n \n❍C. Salting\n \n❍D. Data masking \nQuick \nAnswer: 161\nThe Details: 252\n","choices":[{"letter":"A","text":"Digital signatures"},{"letter":"B","text":"Steganography"},{"letter":"C","text":"Salting"},{"letter":"D","text":"Data masking"}],"correct":["B"],"answerPages":[261],"objectives":["1.4"]},{"id":"B89","number":89,"page":168,"clip":[24,173.603,410,316.143],"text":"B89.\tA third-party has been contracted to perform a \npenetration test on a company's public web servers. The \ntesting company has been provided with the external IP \naddresses of the servers. Which of the following would \ndescribe this scenario?\n \n❍A. Defensive\n \n❍B. Active reconnaissance\n \n❍C. Partially known environment\n \n❍D. Regulatory \nQuick \nAnswer: 161\nThe Details: 253\n","choices":[{"letter":"A","text":"Defensive"},{"letter":"B","text":"Active reconnaissance"},{"letter":"C","text":"Partially known environment"},{"letter":"D","text":"Regulatory"}],"correct":["C"],"answerPages":[262],"objectives":["5.5"]},{"id":"B90","number":90,"page":168,"clip":[24,318.143,410,610],"text":"159\nPractice Exam B - Questions\nB90.\tWhich of the following would be the best way to \ndescribe the estimated number of laptops that might be \nstolen in a fiscal year?\n \n❍A. ALE \n \n❍B. SLE\n \n❍C. ARO\n \n❍D. MTTR\nQuick \nAnswer: 161\nThe Details: 254\n","choices":[{"letter":"A","text":"ALE"},{"letter":"B","text":"SLE"},{"letter":"C","text":"ARO"},{"letter":"D","text":"MTTR"}],"correct":["C"],"answerPages":[263,264],"objectives":["5.2"]}],"C":[{"id":"C1","number":1,"page":266,"clip":[24,85.848,410,610],"text":"257\nPractice Exam C - Questions\nC1.\t Refer to the following firewall rules:\nCategorize the following traffic flows as ALLOWED or BLOCKED  \nthrough the firewall:\nRule #\nSource IP\nDestination \nIP\nProtocol \n(TCP/\nUDP)\nPort #\nAllow/\nBlock\n1\nAny\n10.1.10.88\nTCP\n22\nAllow\n2\nAny\n10.1.10.120\nTCP\n80\nAllow\n3\nAny\n10.1.10.120\nTCP\n443\nAllow\n4\nAny\n10.1.10.61\nTCP\n3389\nAllow\n5\nAny\nAny\nUDP\n53\nAllow\n6\nAny\nAny\nUDP\n123\nAllow\n7\nAny\nAny\nICMP\nBlock\nUse a secure terminal to connect to 10.1.10.88\nShare the desktop on server 10.1.10.120\nPerform a DNS query from 10.1.10.88 to 9.9.9.9\nView web pages on 10.1.10.120\nAuthenticate to an LDAP server at 10.1.10.61\n \nSynchronize the clock on a server at 10.1.10.17\nAnswer Page: 291\n","choices":[],"correct":[],"answerPages":[300,301],"objectives":[]},{"id":"C2","number":2,"page":267,"clip":[24,29.063,410,267.783],"text":"C2.\t Match the device to the description. Some device types will not be used.\nBlock SQL injection over an Internet connection\nIntercept all browser requests and cache the results\nForward packets between separate VLANs\nConfigure a group of redundant web servers\nEvaluate the input to a browser-based application\nAnswer Page: 293\nWAF\nProxy server\nLoad balancer\nSensor\nMDM\nRouter\nJump server\nIPS\n","choices":[],"correct":[],"answerPages":[302],"objectives":["3.2"]},{"id":"C3","number":3,"page":267,"clip":[24,269.783,410,610],"text":"258\nPractice Exam C - Questions\nA website stops responding to normal requests\nData is captured and retransmitted to a server\nThe malware is designed to remain hidden on a \ncomputer system\nA list of passwords are attempted with a  \nknown username\nAn email link redirects a user to a site that  \nrequests login credentials\nPermissions are circumvented by adding additional \ncode as application input\nAnswer Page: 294\nC3.\t Match the attack type to the characteristic:\nDDoS\nReplay\nRootkit\nBrute force\nPhishing\nInjection\n","choices":[],"correct":[],"answerPages":[303],"objectives":["2.4"]},{"id":"C4","number":4,"page":268,"clip":[24,29.207,410,301.143],"text":"Create a stronger key using multiple processes\nData is hidden within another media type\nDifferent inputs create the same hash\nSensitive data is hidden from view\nA different key is used for decryption than encryption\nInformation is added to make a unique hash\nAnswer Page: 295\nC4.\t Match the cryptography technology to the description:\nSalting\nSteganography\nMasking\nAsymmetric\nCollision\nKey stretching\n","choices":[],"correct":[],"answerPages":[304],"objectives":["1.4"]},{"id":"C5","number":5,"page":268,"clip":[24,303.143,410,610],"text":"Practice Exam C - Questions\nA field service engineer uses their corporate laptop at \ncoffee shops and hotels\nSoftware developers run a series of tests before \ndeploying an application\nAn administrator prevents employees from visiting \nknown-malicious web sites\nDirectly access cloud-based services from all  \ncorporate locations\nUsers connecting to the network should use their \ncorporate authentication credentials\nAnswer Page: 296\nC5.\t Add the most applicable security technologies to the following scenarios:\nVPN\nNGFW\n802.1X\nSD-WAN\nSandboxing\n","choices":[],"correct":[],"answerPages":[305],"objectives":["3.2"]},{"id":"C6","number":6,"page":270,"clip":[24,85.848,410,250.289],"text":"C6.\t A finance company is legally required to maintain seven \nyears of tax records for all of their customers. Which of \nthe following would be the BEST way to implement this \nrequirement?\n \n❍A. Automate a script to remove all tax information \nmore than seven years old\n \n❍B. Print and store all tax records in a seven-year cycle\n \n❍C. Allow users to download tax records from their \naccount login\n \n❍D. Create a separate daily backup archive for all \napplicable tax records\nQuick \nAnswer: 289\nThe Details: 297\n","choices":[{"letter":"A","text":"Automate a script to remove all tax information more than seven years old"},{"letter":"B","text":"Print and store all tax records in a seven-year cycle"},{"letter":"C","text":"Allow users to download tax records from their account login"},{"letter":"D","text":"Create a separate daily backup archive for all applicable tax records"}],"correct":["D"],"answerPages":[306],"objectives":["4.2"]},{"id":"C7","number":7,"page":270,"clip":[24,252.289,410,377.13],"text":"C7.\t A system administrator is designing a data center for an \ninsurance company’s new public cloud and would like to \nautomatically rotate encryption keys on a regular basis. \nWhich of the following would provide this functionality?\n \n❍A. TPM\n \n❍B. Key management system\n \n❍C. Secure enclave\n \n❍D. XDR\nQuick \nAnswer: 289\nThe Details: 298\n","choices":[{"letter":"A","text":"TPM"},{"letter":"B","text":"Key management system"},{"letter":"C","text":"Secure enclave"},{"letter":"D","text":"XDR"}],"correct":["B"],"answerPages":[307],"objectives":["1.4"]},{"id":"C8","number":8,"page":270,"clip":[24,379.13,410,610],"text":"261\nPractice Exam C - Questions\nC8.\t A newly installed IPS is flagging a legitimate corporate \napplication as malicious network traffic. Which of the \nfollowing would be the BEST way to resolve this issue?\n \n❍A. Disable the IPS signature\n \n❍B. Block the application\n \n❍C. Log all IPS events\n \n❍D. Tune the IPS alerts\nQuick \nAnswer: 289\nThe Details: 299\n","choices":[{"letter":"A","text":"Disable the IPS signature"},{"letter":"B","text":"Block the application"},{"letter":"C","text":"Log all IPS events"},{"letter":"D","text":"Tune the IPS alerts"}],"correct":["D"],"answerPages":[308],"objectives":["4.4"]},{"id":"C9","number":9,"page":271,"clip":[24,29.063,410,158.403],"text":"C9.\t A security administrator has identified an internally \ndeveloped application which allows modification of SQL \nqueries through the web-based front-end. Which of the \nfollowing changes would resolve this vulnerability?\n \n❍A. Store all credentials as salted hashes\n \n❍B. Verify the application's digital signature\n \n❍C. Validate all application input\n \n❍D. Obfuscate the application's source code\nQuick \nAnswer: 289\nThe Details: 300\n","choices":[{"letter":"A","text":"Store all credentials as salted hashes"},{"letter":"B","text":"Verify the application's digital signature"},{"letter":"C","text":"Validate all application input"},{"letter":"D","text":"Obfuscate the application's source code"}],"correct":["C"],"answerPages":[309],"objectives":["4.1"]},{"id":"C10","number":10,"page":271,"clip":[24,160.403,410,289.743],"text":"C10.\tA system administrator is implementing a fingerprint \nscanner to provide access to the data center. Which of \nthe following authentication technologies would be \nassociated with this access?\n \n❍A. Digital signature\n \n❍B. Hard authentication token\n \n❍C. Security key\n \n❍D. Something you are \nQuick \nAnswer: 289\nThe Details: 301\n","choices":[{"letter":"A","text":"Digital signature"},{"letter":"B","text":"Hard authentication token"},{"letter":"C","text":"Security key"},{"letter":"D","text":"Something you are"}],"correct":["D"],"answerPages":[310],"objectives":["4.6"]},{"id":"C11","number":11,"page":271,"clip":[24,291.743,410,610],"text":"262\nPractice Exam C - Questions\nC11.\tThe IT department of a transportation company \nmaintains an on-site inventory of chassis-based network \nswitch interface cards. If a failure occurs, the on-site \ntechnician can replace the interface card and have the \nsystem running again in sixty minutes. Which of the \nfollowing BEST describes this recovery metric?\n \n❍A. MTBF \n \n❍B. MTTR\n \n❍C. RPO\n \n❍D. RTO\nQuick \nAnswer: 289\nThe Details: 302\n","choices":[{"letter":"A","text":"MTBF"},{"letter":"B","text":"MTTR"},{"letter":"C","text":"RPO"},{"letter":"D","text":"RTO"}],"correct":["B"],"answerPages":[311],"objectives":["5.2"]},{"id":"C12","number":12,"page":272,"clip":[24,29.063,410,211.203],"text":"C12.\tA company maintains a server farm in a large data center. \nThese servers are used internally and are not accessible \nfrom outside of the data center. The security team has \ndiscovered a group of servers was breached before the \nlatest security patches were applied. Breach attempts \nwere not logged on any other servers. Which of these \nthreat actors would be MOST likely involved in this \nbreach?\n \n❍A. Organized crime\n \n❍B. Insider\n \n❍C. Nation state\n \n❍D. Unskilled attacker\nQuick \nAnswer: 289\nThe Details: 303\n","choices":[{"letter":"A","text":"Organized crime"},{"letter":"B","text":"Insider"},{"letter":"C","text":"Nation state"},{"letter":"D","text":"Unskilled attacker"}],"correct":["B"],"answerPages":[312],"objectives":["2.1"]},{"id":"C13","number":13,"page":272,"clip":[24,213.203,410,368.943],"text":"C13.\tAn organization has received a vulnerability scan report \nof their Internet-facing web servers. The report shows the \nservers have multiple Sun Java Runtime Environment \n(JRE) vulnerabilities, but the server administrator has \nverified that JRE is not installed. Which of the following \nwould be the BEST way to handle this report?\n \n❍A. Install the latest version of JRE on the server \n \n❍B. Quarantine the server and scan for malware\n \n❍C. Harden the operating system of the web server\n \n❍D. Ignore the JRE vulnerability alert\nQuick \nAnswer: 289\nThe Details: 304\n","choices":[{"letter":"A","text":"Install the latest version of JRE on the server"},{"letter":"B","text":"Quarantine the server and scan for malware"},{"letter":"C","text":"Harden the operating system of the web server"},{"letter":"D","text":"Ignore the JRE vulnerability alert"}],"correct":["D"],"answerPages":[313],"objectives":["4.3"]},{"id":"C14","number":14,"page":272,"clip":[24,370.943,410,610],"text":"263\nPractice Exam C - Questions\nC14.\tA user downloaded and installed a utility for \ncompressing and decompressing files. Immediately \nafter installing the utility, the user’s overall workstation \nperformance degraded and it now takes twice as much \ntime to perform any tasks on the computer. Which of \nthe following is the BEST description of this malware \ninfection?\n \n❍A. Ransomware\n \n❍B. Bloatware\n \n❍C. Logic bomb\n \n❍D. Trojan\nQuick \nAnswer: 289\nThe Details: 305\n","choices":[{"letter":"A","text":"Ransomware"},{"letter":"B","text":"Bloatware"},{"letter":"C","text":"Logic bomb"},{"letter":"D","text":"Trojan"}],"correct":["D"],"answerPages":[314],"objectives":["2.4"]},{"id":"C15","number":15,"page":273,"clip":[24,29.063,410,145.203],"text":"C15.\tWhich of the following is the process for replacing \nsensitive data with a non-sensitive and functional \nplaceholder?\n \n❍A. Steganography\n \n❍B. Tokenization\n \n❍C. Retention\n \n❍D. Masking\nQuick \nAnswer: 289\nThe Details: 306\n","choices":[{"letter":"A","text":"Steganography"},{"letter":"B","text":"Tokenization"},{"letter":"C","text":"Retention"},{"letter":"D","text":"Masking"}],"correct":["B"],"answerPages":[315],"objectives":["3.3"]},{"id":"C16","number":16,"page":273,"clip":[24,147.203,410,342.543],"text":"C16.\tA security administrator has installed a new firewall \nto protect a web server VLAN. The application owner \nrequires all web server sessions communicate over an \nencrypted channel. Which of these rules should the \nsecurity administrator include in the firewall rulebase?\n \n❍A. Source: ANY, Destination: ANY,  \nProtocol: TCP, Port: 23, Deny \n \n❍B. Source: ANY, Destination: ANY,  \nProtocol: TCP, Port: 22, Allow\n \n❍C. Source: ANY, Destination: ANY,  \nProtocol: TCP, Port: 80, Allow\n \n❍D. Source: ANY, Destination: ANY,  \nProtocol: TCP, Port: 443, Allow\nQuick \nAnswer: 289\nThe Details: 307\n","choices":[{"letter":"A","text":"Source: ANY, Destination: ANY, Protocol: TCP, Port: 23, Deny"},{"letter":"B","text":"Source: ANY, Destination: ANY, Protocol: TCP, Port: 22, Allow"},{"letter":"C","text":"Source: ANY, Destination: ANY, Protocol: TCP, Port: 80, Allow"},{"letter":"D","text":"Source: ANY, Destination: ANY, Protocol: TCP, Port: 443, Allow"}],"correct":["D"],"answerPages":[316],"objectives":["4.5"]},{"id":"C17","number":17,"page":273,"clip":[24,344.543,410,447.483],"text":"C17.\tWhich of these would be used to provide  \nmulti-factor authentication?\n \n❍A. USB-connected storage drive with FDE \n \n❍B. Employee policy manual\n \n❍C. Just-in-time permissions\n \n❍D. Smart card with picture ID\nQuick \nAnswer: 289\nThe Details: 308\n","choices":[{"letter":"A","text":"USB-connected storage drive with FDE"},{"letter":"B","text":"Employee policy manual"},{"letter":"C","text":"Just-in-time permissions"},{"letter":"D","text":"Smart card with picture ID"}],"correct":["D"],"answerPages":[317],"objectives":["4.6"]},{"id":"C18","number":18,"page":273,"clip":[24,449.483,410,610],"text":"264\nPractice Exam C - Questions\nC18.\tA company's network team has been asked to build an \nIPsec tunnel to a new business partner. Which of the \nfollowing security risks would be the MOST important \nto consider?\n \n❍A. Supply chain attack\n \n❍B. Unsupported systems\n \n❍C. Business email compromise\n \n❍D. Typosquatting\nQuick \nAnswer: 289\nThe Details: 309\n","choices":[{"letter":"A","text":"Supply chain attack"},{"letter":"B","text":"Unsupported systems"},{"letter":"C","text":"Business email compromise"},{"letter":"D","text":"Typosquatting"}],"correct":["A"],"answerPages":[318],"objectives":["2.2"]},{"id":"C19","number":19,"page":274,"clip":[24,29.063,410,171.603],"text":"C19.\tA company's human resources team maintains a list of \nall employees participating in the corporate savings plan. \nA third-party financial company uses this information to \nmanage stock investments for the employees. Which of \nthe following would describe this financial company?\n \n❍A. Processor\n \n❍B. Owner\n \n❍C. Controller\n \n❍D. Custodian\nQuick \nAnswer: 289\nThe Details: 310\n","choices":[{"letter":"A","text":"Processor"},{"letter":"B","text":"Owner"},{"letter":"C","text":"Controller"},{"letter":"D","text":"Custodian"}],"correct":["A"],"answerPages":[319],"objectives":["5.1"]},{"id":"C20","number":20,"page":274,"clip":[24,173.603,410,329.343],"text":"C20.\tA technology company is manufacturing a military-\ngrade radar tracking system that can instantly identify \nany nearby unmanned aerial vehicles (UAVs). The UAV \ndetector must be able to instantly identify and react to \na vehicle without delay. Which of the following would \nBEST describe this tracking system?\n \n❍A. RTOS \n \n❍B. IoT\n \n❍C. ICS\n \n❍D. SDN\nQuick \nAnswer: 289\nThe Details: 311\n","choices":[{"letter":"A","text":"RTOS"},{"letter":"B","text":"IoT"},{"letter":"C","text":"ICS"},{"letter":"D","text":"SDN"}],"correct":["A"],"answerPages":[320],"objectives":["3.1"]},{"id":"C21","number":21,"page":274,"clip":[24,331.343,410,460.683],"text":"C21.\tAn administrator is writing a script to convert an email \nmessage to a help desk ticket and assign the ticket to the \ncorrect department. Which of the following should be \nadministrator use to complete this script?\n \n❍A. Role-based access controls \n \n❍B. Federation\n \n❍C. Due diligence\n \n❍D. Orchestration\nQuick \nAnswer: 289\nThe Details: 312\n","choices":[{"letter":"A","text":"Role-based access controls"},{"letter":"B","text":"Federation"},{"letter":"C","text":"Due diligence"},{"letter":"D","text":"Orchestration"}],"correct":["D"],"answerPages":[321],"objectives":["4.7"]},{"id":"C22","number":22,"page":274,"clip":[24,462.683,410,610],"text":"265\nPractice Exam C - Questions\nC22.\tA security administrator would like a report showing \nhow many attackers are attempting to use a known \nvulnerability to gain access to a corporate web server. \nWhich of the following should be used to gather this \ninformation?\n \n❍A. Application log\n \n❍B. Metadata\n \n❍C. IPS log\n \n❍D. Windows log\nQuick \nAnswer: 289\nThe Details: 313\n","choices":[{"letter":"A","text":"Application log"},{"letter":"B","text":"Metadata"},{"letter":"C","text":"IPS log"},{"letter":"D","text":"Windows log"}],"correct":["C"],"answerPages":[322],"objectives":["4.9"]},{"id":"C23","number":23,"page":275,"clip":[24,29.063,410,171.603],"text":"C23.\tDuring a ransomware outbreak, an organization was \nforced to rebuild database servers from known good \nbackup systems. In which of the following incident \nresponse phases were these database servers brought  \nback online?\n \n❍A. Recovery \n \n❍B. Lessons learned\n \n❍C. Containment\n \n❍D. Detection\nQuick \nAnswer: 289\nThe Details: 314\n","choices":[{"letter":"A","text":"Recovery"},{"letter":"B","text":"Lessons learned"},{"letter":"C","text":"Containment"},{"letter":"D","text":"Detection"}],"correct":["A"],"answerPages":[323],"objectives":["4.8"]},{"id":"C24","number":24,"page":275,"clip":[24,173.603,410,289.743],"text":"C24.\tA security administrator is installing a web server with \na newly built operating system. Which of the following \nwould be the best way to harden this OS?\n \n❍A. Create a backup schedule\n \n❍B. Install a device certificate\n \n❍C. Remove unnecessary software\n \n❍D. Disable power management features\nQuick \nAnswer: 289\nThe Details: 315\n","choices":[{"letter":"A","text":"Create a backup schedule"},{"letter":"B","text":"Install a device certificate"},{"letter":"C","text":"Remove unnecessary software"},{"letter":"D","text":"Disable power management features"}],"correct":["C"],"answerPages":[324],"objectives":["2.5"]},{"id":"C25","number":25,"page":275,"clip":[24,291.743,410,610],"text":"266\nPractice Exam C - Questions\nC25.\tA network IPS has created this log entry:\nFrame 4: 937 bytes on wire (7496 bits),  \n937 bytes captured\nEthernet II, Src: HewlettP_82:d8:31,  \nDst: Cisco_a1:b0:d1\nInternet Protocol Version 4, Src: 172.16.22.7,  \nDst: 10.8.122.244\nTransmission Control Protocol, Src Port: 3863,  \nDst Port: 1433\nApplication Data: SELECT * FROM users WHERE \nusername='x' or 'x'='x' AND  \npassword='x' or 'x'='x' \n \nWhich of the following would describe this log entry?\n \n❍A. Phishing\n \n❍B. Brute force\n \n❍C. SQL injection\n \n❍D. Cross-site scripting\nQuick \nAnswer: 289\nThe Details: 316\n","choices":[{"letter":"A","text":"Phishing"},{"letter":"B","text":"Brute force"},{"letter":"C","text":"SQL injection"},{"letter":"D","text":"Cross-site scripting"}],"correct":["C"],"answerPages":[325],"objectives":["2.3"]},{"id":"C26","number":26,"page":276,"clip":[24,29.063,410,158.403],"text":"C26.\tAn incident response team would like to validate their \ndisaster recovery plans without making any changes to \nthe infrastructure. Which of the following would be the \nbest course of action?\n \n❍A. Tabletop exercise\n \n❍B. Hot site fail-over\n \n❍C. Simulation\n \n❍D. Penetration test\nQuick \nAnswer: 289\nThe Details: 317\n","choices":[{"letter":"A","text":"Tabletop exercise"},{"letter":"B","text":"Hot site fail-over"},{"letter":"C","text":"Simulation"},{"letter":"D","text":"Penetration test"}],"correct":["A"],"answerPages":[326],"objectives":["3.4"]},{"id":"C27","number":27,"page":276,"clip":[24,160.403,410,329.343],"text":"C27.\tA system administrator has installed a new firewall \nbetween the corporate user network and the data center \nnetwork. When the firewall is turned on with the default \nsettings, users complain that the application in the data \ncenter is no longer working. Which of the following \nwould be the BEST way to correct this application issue?\n \n❍A. Create a single firewall rule with an explicit deny \n \n❍B. Build a separate VLAN for the application\n \n❍C. Create firewall rules that match the application \ntraffic flow\n \n❍D. Enable firewall threat blocking\nQuick \nAnswer: 289\nThe Details: 318\n","choices":[{"letter":"A","text":"Create a single firewall rule with an explicit deny"},{"letter":"B","text":"Build a separate VLAN for the application"},{"letter":"C","text":"Create firewall rules that match the application traffic flow"},{"letter":"D","text":"Enable firewall threat blocking"}],"correct":["C"],"answerPages":[327],"objectives":["4.5"]},{"id":"C28","number":28,"page":276,"clip":[24,331.343,410,434.283],"text":"C28.\tWhich of these would be used to provide HA for a  \nweb-based database application?\n \n❍A. SIEM \n \n❍B. UPS\n \n❍C. DLP\n \n❍D. VPN concentrator\nQuick \nAnswer: 289\nThe Details: 319\n","choices":[{"letter":"A","text":"SIEM"},{"letter":"B","text":"UPS"},{"letter":"C","text":"DLP"},{"letter":"D","text":"VPN concentrator"}],"correct":["B"],"answerPages":[328],"objectives":["3.4"]},{"id":"C29","number":29,"page":276,"clip":[24,436.283,410,610],"text":"267\nPractice Exam C - Questions\nC29.\tEach year, a certain number of laptops are lost or stolen \nand must be replaced by the company. Which of the \nfollowing would describe the total cost the company \nspends each year on laptop replacements?\n \n❍A. SLE \n \n❍B. SLA\n \n❍C. ALE\n \n❍D. ARO\nQuick \nAnswer: 289\nThe Details: 320\n","choices":[{"letter":"A","text":"SLE"},{"letter":"B","text":"SLA"},{"letter":"C","text":"ALE"},{"letter":"D","text":"ARO"}],"correct":["C"],"answerPages":[329],"objectives":["5.2"]},{"id":"C30","number":30,"page":277,"clip":[24,29.063,410,229.504],"text":"C30.\tA network administrator is viewing a log file  \nfrom a web server: \n \nhttps://www.example.com/?s=/Index/think/\napp/invokefunction&function=call_user_\nfunc_array&vars[0]=md5&vars[1][0]= \n__HelloThinkPHP \n \nWhich of the following would be the BEST way to \nprevent this attack?\n \n❍A. Static code analyzer\n \n❍B. Input validation\n \n❍C. Allow list\n \n❍D. Secure cookies\nQuick \nAnswer: 289\nThe Details: 321\n","choices":[{"letter":"A","text":"Static code analyzer"},{"letter":"B","text":"Input validation"},{"letter":"C","text":"Allow list"},{"letter":"D","text":"Secure cookies"}],"correct":["B"],"answerPages":[330],"objectives":["4.1"]},{"id":"C31","number":31,"page":277,"clip":[24,231.504,410,343.145],"text":"C31.\tSam would like to send an email to Jack and have Jack \nverify that Sam was the sender of the email. Which of \nthese should Sam use to provide this verification?\n \n❍A. Digitally sign with Sam’s private key \n \n❍B. Digitally sign with Sam’s public key\n \n❍C. Digitally sign with Jack’s private key\n \n❍D. Digitally sign with Jack’s public key\nQuick \nAnswer: 289\nThe Details: 322\n","choices":[{"letter":"A","text":"Digitally sign with Sam’s private key"},{"letter":"B","text":"Digitally sign with Sam’s public key"},{"letter":"C","text":"Digitally sign with Jack’s private key"},{"letter":"D","text":"Digitally sign with Jack’s public key"}],"correct":["A"],"answerPages":[331],"objectives":["1.4"]},{"id":"C32","number":32,"page":277,"clip":[24,345.145,410,610],"text":"268\nPractice Exam C - Questions\nC32.\tThe contract of a long-term temporary employee is \nending. Which of these would be the MOST important \npart of the off-boarding process?\n \n❍A. Perform an on-demand audit of the user’s \nprivileges \n \n❍B. Archive the decryption keys associated with  \nthe user account\n \n❍C. Document the user’s outstanding tasks\n \n❍D. Obtain a signed copy of the Acceptable  \nUse Policies\nQuick \nAnswer: 289\nThe Details: 323\n","choices":[{"letter":"A","text":"Perform an on-demand audit of the user’s privileges"},{"letter":"B","text":"Archive the decryption keys associated with the user account"},{"letter":"C","text":"Document the user’s outstanding tasks"},{"letter":"D","text":"Obtain a signed copy of the Acceptable Use Policies"}],"correct":["B"],"answerPages":[332],"objectives":["5.1"]},{"id":"C33","number":33,"page":278,"clip":[24,29.063,410,171.603],"text":"C33.\tA cybersecurity analyst has been asked to respond to \na denial of service attack against a web server, and the \nanalyst has collected the log files and data from the \nserver. Which of the following would allow a future \nanalyst to verify the data as original and unaltered?\n \n❍A. E-discovery\n \n❍B. Root cause analysis\n \n❍C. Legal hold\n \n❍D. Data hashing\nQuick \nAnswer: 289\nThe Details: 324\n","choices":[{"letter":"A","text":"E-discovery"},{"letter":"B","text":"Root cause analysis"},{"letter":"C","text":"Legal hold"},{"letter":"D","text":"Data hashing"}],"correct":["D"],"answerPages":[333],"objectives":["4.8"]},{"id":"C34","number":34,"page":278,"clip":[24,173.603,410,316.143],"text":"C34.\tA security administrator is reviewing authentication logs. \nThe logs show a large number of accounts with at least \nthree failed authentication attempts during the previous \nweek. Which of the following would BEST explain this \nreport data?\n \n❍A. Downgrade attack\n \n❍B. Phishing\n \n❍C. Injection\n \n❍D. Spraying\nQuick \nAnswer: 289\nThe Details: 325\n","choices":[{"letter":"A","text":"Downgrade attack"},{"letter":"B","text":"Phishing"},{"letter":"C","text":"Injection"},{"letter":"D","text":"Spraying"}],"correct":["D"],"answerPages":[334],"objectives":["2.4"]},{"id":"C35","number":35,"page":278,"clip":[24,318.143,410,447.483],"text":"C35.\tA security administrator has been asked to block all \nbrowsing to casino gaming websites. Which of the \nfollowing would be the BEST way to implement this \nrequirement?\n \n❍A. Tune the IPS signatures\n \n❍B. Block port tcp/443 on the firewall\n \n❍C. Configure 802.1X for web browsing\n \n❍D. Add a content filter rule\nQuick \nAnswer: 289\nThe Details: 326\n","choices":[{"letter":"A","text":"Tune the IPS signatures"},{"letter":"B","text":"Block port tcp/443 on the firewall"},{"letter":"C","text":"Configure 802.1X for web browsing"},{"letter":"D","text":"Add a content filter rule"}],"correct":["D"],"answerPages":[335],"objectives":["4.5"]},{"id":"C36","number":36,"page":278,"clip":[24,449.483,410,610],"text":"269\nPractice Exam C - Questions\nC36.\tA company is experiencing downtime and outages when \napplication patches and updates are deployed during \nthe week. Which of the following would help to resolve \nthese issues?\n \n❍A. Onboarding considerations\n \n❍B. Incident response policies\n \n❍C. Change management procedures\n \n❍D. Decentralized governance\nQuick \nAnswer: 289\nThe Details: 327\n","choices":[{"letter":"A","text":"Onboarding considerations"},{"letter":"B","text":"Incident response policies"},{"letter":"C","text":"Change management procedures"},{"letter":"D","text":"Decentralized governance"}],"correct":["C"],"answerPages":[336],"objectives":["1.3"]},{"id":"C37","number":37,"page":279,"clip":[24,29.063,410,158.403],"text":"C37.\tA company is implementing a series of steps to follow \nwhen responding to a security event. Which of the \nfollowing would provide this set of processes and \nprocedures?\n \n❍A. MDM\n \n❍B. DLP\n \n❍C. Playbook\n \n❍D. Zero trust\nQuick \nAnswer: 289\nThe Details: 328\n","choices":[{"letter":"A","text":"MDM"},{"letter":"B","text":"DLP"},{"letter":"C","text":"Playbook"},{"letter":"D","text":"Zero trust"}],"correct":["C"],"answerPages":[337],"objectives":["5.1"]},{"id":"C38","number":38,"page":279,"clip":[24,160.403,410,289.743],"text":"C38.\tA transportation company maintains a scheduling \napplication and a database in a virtualized cloud-based \nenvironment. Which of the following would be the \nBEST way to backup these services?\n \n❍A. Journaling\n \n❍B. Snapshot\n \n❍C. RTOS\n \n❍D. Containerizationh\nQuick \nAnswer: 289\nThe Details: 329\n","choices":[{"letter":"A","text":"Journaling"},{"letter":"B","text":"Snapshot"},{"letter":"C","text":"RTOS"},{"letter":"D","text":"Containerization"}],"correct":["B"],"answerPages":[338],"objectives":["3.4"]},{"id":"C39","number":39,"page":279,"clip":[24,291.743,410,407.883],"text":"C39.\tIn an environment using discretionary access controls, \nwhich of these would control the rights and permissions \nassociated with a file or directory?\n \n❍A. Administrator \n \n❍B. Owner\n \n❍C. Group\n \n❍D. Systemh\nQuick \nAnswer: 289\nThe Details: 330\n","choices":[{"letter":"A","text":"Administrator"},{"letter":"B","text":"Owner"},{"letter":"C","text":"Group"},{"letter":"D","text":"System"}],"correct":["B"],"answerPages":[339],"objectives":["4.6"]},{"id":"C40","number":40,"page":279,"clip":[24,409.883,410,610],"text":"270\nPractice Exam C - Questions\nC40.\tA security administrator has installed a network-based \nDLP solution to determine if file transfers contain PII. \nWhich of the following describes the data during the file \ntransfer?\n \n❍A. In-use \n \n❍B. In-transit\n \n❍C. Highly available\n \n❍D. At-resth\nQuick \nAnswer: 289\nThe Details: 331\n","choices":[{"letter":"A","text":"In-use"},{"letter":"B","text":"In-transit"},{"letter":"C","text":"Highly available"},{"letter":"D","text":"At-rest"}],"correct":["B"],"answerPages":[340],"objectives":["3.3"]},{"id":"C41","number":41,"page":280,"clip":[24,29.063,410,184.803],"text":"C41.\tA medical imaging company would like to connect all \nremote locations together with high speed network \nlinks. The network connections must maintain high \nthroughput rates and must always be available during \nworking hours. In which of the following should these \nrequirements be enforced with the network provider?\n \n❍A. Service level agreement \n \n❍B. Memorandum of understanding\n \n❍C. Non-disclosure agreement\n \n❍D. Acceptable use policy\nQuick \nAnswer: 289\nThe Details: 332\n","choices":[{"letter":"A","text":"Service level agreement"},{"letter":"B","text":"Memorandum of understanding"},{"letter":"C","text":"Non-disclosure agreement"},{"letter":"D","text":"Acceptable use policy"}],"correct":["A"],"answerPages":[341],"objectives":["5.3"]},{"id":"C42","number":42,"page":280,"clip":[24,186.803,410,316.143],"text":"C42.\tA company is implementing a security awareness \nprogram for their user community. Which of the \nfollowing should be included for additional user \nguidance and training?\n \n❍A. Daily firewall exception reporting\n \n❍B. Information on proper password management\n \n❍C. Periodic vulnerability scanning of external services\n \n❍D. Adjustments to annualized loss expectancy\nQuick \nAnswer: 289\nThe Details: 333\n","choices":[{"letter":"A","text":"Daily firewall exception reporting"},{"letter":"B","text":"Information on proper password management"},{"letter":"C","text":"Periodic vulnerability scanning of external services"},{"letter":"D","text":"Adjustments to annualized loss expectancy"}],"correct":["B"],"answerPages":[342],"objectives":["5.6"]},{"id":"C43","number":43,"page":280,"clip":[24,318.143,410,610],"text":"271\nPractice Exam C - Questions\nC43.\tA security administrator is preparing a phishing email as \npart of a periodic employee security awareness campaign. \nThe email is spoofed to appear as an unknown third-\nparty and asks employees to immediately click a link \nor their state licensing will be revoked. Which of the \nfollowing should be the expected response from the \nusers?\n \n❍A. Delete the message\n \n❍B. Click the link and make a note of the URL\n \n❍C. Forward the message to others in the department\n \n❍D. Report the suspicious link to the help desk\nQuick \nAnswer: 289\nThe Details: 334\n","choices":[{"letter":"A","text":"Delete the message"},{"letter":"B","text":"Click the link and make a note of the URL"},{"letter":"C","text":"Forward the message to others in the department"},{"letter":"D","text":"Report the suspicious link to the help desk"}],"correct":["D"],"answerPages":[343],"objectives":["5.6"]},{"id":"C44","number":44,"page":281,"clip":[24,29.063,410,171.603],"text":"C44.\tA security administrator would like to minimize \nthe number of certificate status checks made by web \nsite clients to the certificate authority. Which of \nthe following would be the BEST option for this \nrequirement?\n \n❍A. OCSP stapling \n \n❍B. Self-signed certificates\n \n❍C. CRL\n \n❍D. Wildcards\nQuick \nAnswer: 289\nThe Details: 335\n","choices":[{"letter":"A","text":"OCSP stapling"},{"letter":"B","text":"Self-signed certificates"},{"letter":"C","text":"CRL"},{"letter":"D","text":"Wildcards"}],"correct":["A"],"answerPages":[344],"objectives":["1.4"]},{"id":"C45","number":45,"page":281,"clip":[24,173.603,410,329.343],"text":"C45.\tA company is concerned their EDR solution will not \nbe able to stop more advanced ransomware variants. \nTechnicians have created a backup and restore utility to \nget most systems up and running less than an hour after \nan attack. What type of security control is associated \nwith this restore process?\n \n❍A. Directive\n \n❍B. Compensating\n \n❍C. Preventive\n \n❍D. Detective\nQuick \nAnswer: 289\nThe Details: 336\n","choices":[{"letter":"A","text":"Directive"},{"letter":"B","text":"Compensating"},{"letter":"C","text":"Preventive"},{"letter":"D","text":"Detective"}],"correct":["B"],"answerPages":[345],"objectives":["1.1"]},{"id":"C46","number":46,"page":281,"clip":[24,331.343,410,610],"text":"272\nPractice Exam C - Questions\nC46.\tTo upgrade an internal application, the development \nteam provides the operations team with instructions for \nbacking up, patching the application, and reverting the \npatch if needed. The operations team schedules a date \nfor the upgrade, informs the business divisions, and tests \nthe upgrade process after completion. Which of the \nfollowing describes this process?\n \n❍A. Code signing\n \n❍B. Continuity planning\n \n❍C. Usage auditing\n \n❍D. Change management\nQuick \nAnswer: 289\nThe Details: 337\n","choices":[{"letter":"A","text":"Code signing"},{"letter":"B","text":"Continuity planning"},{"letter":"C","text":"Usage auditing"},{"letter":"D","text":"Change management"}],"correct":["D"],"answerPages":[346],"objectives":["1.3"]},{"id":"C47","number":47,"page":282,"clip":[24,29.063,410,171.603],"text":"C47.\tA company is implementing a public file-storage and \ncloud-based sharing service, and would like users to \nauthenticate with an existing account on a trusted \nthird-party web site. Which of the following should the \ncompany implement?\n \n❍A. SSO\n \n❍B. Federation\n \n❍C. Least privilege \n \n❍D. Discretionary access controls\nQuick \nAnswer: 289\nThe Details: 338\n","choices":[{"letter":"A","text":"SSO"},{"letter":"B","text":"Federation"},{"letter":"C","text":"Least privilege"},{"letter":"D","text":"Discretionary access controls"}],"correct":["B"],"answerPages":[347],"objectives":["4.6"]},{"id":"C48","number":48,"page":282,"clip":[24,173.603,410,368.943],"text":"C48.\tA system administrator is viewing this output from \nMicrosoft’s System File Checker: \nWhich of the following malware types is the MOST \nlikely cause of this output?\n \n❍A. Ransomware \n \n❍B. Logic bomb\n \n❍C. Rootkit\n \n❍D. Keylogger\n15:43:01 - Repairing corrupted file C:\\Windows\\System32\\kernel32.dll\n15:43:03 - Repairing corrupted file C:\\Windows\\System32\\netapi32.dll\n15:43:07 - Repairing corrupted file C:\\Windows\\System32\\user32.dll\n15:43:43 - Repair complete\nQuick \nAnswer: 289\nThe Details: 339\n","choices":[{"letter":"A","text":"Ransomware"},{"letter":"B","text":"Logic bomb"},{"letter":"C","text":"Rootkit"},{"letter":"D","text":"Keylogger"}],"correct":["C"],"answerPages":[348],"objectives":["2.4"]},{"id":"C49","number":49,"page":282,"clip":[24,370.943,410,610],"text":"273\nPractice Exam C - Questions\nC49.\tWhat type of vulnerability would be associated with this \nlog information?\n \n❍A. Buffer overflow \n \n❍B. Directory traversal\n \n❍C. DoS\n \n❍D. Cross-site scripting\n    GET http://example.com/show.asp?view=../../Windows/ \n         system.ini HTTP/1.1\n    GET http://example.com/show.asp?view=../../Windows/ \n         system.ini HTTP/1.1\nQuick \nAnswer: 289\nThe Details: 340\n","choices":[{"letter":"A","text":"Buffer overflow"},{"letter":"B","text":"Directory traversal"},{"letter":"C","text":"DoS"},{"letter":"D","text":"Cross-site scripting"}],"correct":["B"],"answerPages":[349],"objectives":["2.4"]},{"id":"C50","number":50,"page":283,"clip":[24,29.063,410,158.403],"text":"C50.\tA developer has created an application to store password \ninformation in a database. Which of the following BEST \ndescribes a way of protecting these credentials by adding \nrandom data to the password?\n \n❍A. Hashing\n \n❍B. Data masking\n \n❍C. Salting\n \n❍D. Asymmetric encryption\nQuick \nAnswer: 289\nThe Details: 341\n","choices":[{"letter":"A","text":"Hashing"},{"letter":"B","text":"Data masking"},{"letter":"C","text":"Salting"},{"letter":"D","text":"Asymmetric encryption"}],"correct":["C"],"answerPages":[350],"objectives":["3.3"]},{"id":"C51","number":51,"page":283,"clip":[24,160.403,410,263.343],"text":"C51.\tWhich of the following processes provides ongoing \nbuilding and testing of newly written code?\n \n❍A. Continuous integration\n \n❍B. Continuity of operations\n \n❍C. Version control\n \n❍D. Race condition\nQuick \nAnswer: 289\nThe Details: 342\n","choices":[{"letter":"A","text":"Continuous integration"},{"letter":"B","text":"Continuity of operations"},{"letter":"C","text":"Version control"},{"letter":"D","text":"Race condition"}],"correct":["A"],"answerPages":[351],"objectives":["4.7"]},{"id":"C52","number":52,"page":283,"clip":[24,265.343,410,407.883],"text":"C52.\tWhich of the following BEST describes a  \nresponsibility matrix?\n \n❍A. A visual summary of cloud provider accountability\n \n❍B. Identification of tasks at each step of  \na project plan\n \n❍C. A list of cybersecurity requirements based  \non the identified risks\n \n❍D. Ongoing group discussions regarding \ncybersecurity\nQuick \nAnswer: 289\nThe Details: 343\n","choices":[{"letter":"A","text":"A visual summary of cloud provider accountability"},{"letter":"B","text":"Identification of tasks at each step of a project plan"},{"letter":"C","text":"A list of cybersecurity requirements based on the identified risks"},{"letter":"D","text":"Ongoing group discussions regarding cybersecurity"}],"correct":["A"],"answerPages":[352],"objectives":["3.1"]},{"id":"C53","number":53,"page":283,"clip":[24,409.883,410,610],"text":"274\nPractice Exam C - Questions\nC53.\tA security administrator is implementing an \nauthentication system for the company. Which of the \nfollowing would be the best choice for validating login \ncredentials for all usernames and passwords in the \nauthentication system?\n \n❍A. CA\n \n❍B. SIEM\n \n❍C. LDAP\n \n❍D. WAF\nQuick \nAnswer: 289\nThe Details: 344\n","choices":[{"letter":"A","text":"CA"},{"letter":"B","text":"SIEM"},{"letter":"C","text":"LDAP"},{"letter":"D","text":"WAF"}],"correct":["C"],"answerPages":[353],"objectives":["4.6"]},{"id":"C54","number":54,"page":284,"clip":[24,29.063,410,280.085],"text":"C54.\tA technician is reviewing this information from an IPS log: \nWhich of the following can be associated with this log \ninformation? (Select TWO)\n \n❍A. The attacker sent a non-authenticated  \nBGP packet to trigger the IPS \n \n❍B. The source of the attack is 192.168.11.1\n \n❍C. The event was logged but no packets were dropped\n \n❍D. The source of the attack is 10.1.111.7\n \n❍E. The attacker sent an unusual HTTP packet to \ntrigger the IPS\nMAIN_IPS: 22June2023 09:02:50 reject 10.1.111.7\nAlert: HTTP Suspicious Webdav OPTIONS Method Request; Host: Server\nSeverity: medium; Performance Impact:3;\nCategory: info-leak; Packet capture; disable\nProto:tcp; dst:192.168.11.1; src:10.1.111.7\nQuick \nAnswer: 289\nThe Details: 345\n","choices":[{"letter":"A","text":"The attacker sent a non-authenticated BGP packet to trigger the IPS"},{"letter":"B","text":"The source of the attack is 192.168.11.1"},{"letter":"C","text":"The event was logged but no packets were dropped"},{"letter":"D","text":"The source of the attack is 10.1.111.7"},{"letter":"E","text":"The attacker sent an unusual HTTP packet to trigger the IPS"}],"correct":["D","E"],"answerPages":[354],"objectives":["4.9"]},{"id":"C55","number":55,"page":284,"clip":[24,282.085,410,610],"text":"275\nPractice Exam C - Questions\nC55.\tA company has contracted with a third-party to provide \npenetration testing services. The service includes a port \nscan of each externally-facing device. This is an  \nexample of:\n \n❍A. Initial exploitation \n \n❍B. Privilege escalation\n \n❍C. Known environment\n \n❍D. Active reconnaissance\nQuick \nAnswer: 289\nThe Details: 346\n","choices":[{"letter":"A","text":"Initial exploitation"},{"letter":"B","text":"Privilege escalation"},{"letter":"C","text":"Known environment"},{"letter":"D","text":"Active reconnaissance"}],"correct":["D"],"answerPages":[355],"objectives":["5.5"]},{"id":"C56","number":56,"page":285,"clip":[24,29.063,410,303.603],"text":"C56.\tAn access point in a corporate headquarters office has \nthe following configuration: \nWhich of the following would apply to this \nconfiguration?\n \n❍A. Invalid frequency band \n \n❍B. Weak encryption\n \n❍C. Incorrect IP address and subnet mask\n \n❍D. Invalid software version\nIP address: 10.1.10.1\nSubnet mask: 255.255.255.0\nDHCPv4 Server: Enabled\nSSID: Wireless\nWireless Mode: 802.11n\nSecurity Mode: WEP-PSK\nFrequency band: 2.4 GHz\nSoftware revision: 2.1\nMAC Address: 60:3D:26:71:FF:AA\nIPv4 Firewall: Enabled\nQuick \nAnswer: 289\nThe Details: 347\n","choices":[{"letter":"A","text":"Invalid frequency band"},{"letter":"B","text":"Weak encryption"},{"letter":"C","text":"Incorrect IP address and subnet mask"},{"letter":"D","text":"Invalid software version"}],"correct":["B"],"answerPages":[356],"objectives":["2.2"]},{"id":"C57","number":57,"page":285,"clip":[24,305.603,410,421.743],"text":"C57.\tAn attacker has gained access to an application through \nthe use of packet captures. Which of the following would \nbe MOST likely used by the attacker?\n \n❍A. Overflow\n \n❍B. Forgery\n \n❍C. Replay\n \n❍D. Injection\nQuick \nAnswer: 289\nThe Details: 348\n","choices":[{"letter":"A","text":"Overflow"},{"letter":"B","text":"Forgery"},{"letter":"C","text":"Replay"},{"letter":"D","text":"Injection"}],"correct":["C"],"answerPages":[357],"objectives":["2.4"]},{"id":"C58","number":58,"page":285,"clip":[24,423.743,410,610],"text":"276\nPractice Exam C - Questions\nC58.\tA company is receiving complaints of slowness and \ndisconnections to their Internet-facing web server. A \nnetwork administrator monitors the Internet link and \nfinds excessive bandwidth utilization from thousands of \ndifferent IP addresses. Which of the following would be \nthe MOST likely reason for these performance issues?\n \n❍A. DDoS\n \n❍B. DNS spoofing\n \n❍C. RFID cloning\n \n❍D. Wireless jamming\nQuick \nAnswer: 289\nThe Details: 349\n","choices":[{"letter":"A","text":"DDoS"},{"letter":"B","text":"DNS spoofing"},{"letter":"C","text":"RFID cloning"},{"letter":"D","text":"Wireless jamming"}],"correct":["A"],"answerPages":[358],"objectives":["2.4"]},{"id":"C59","number":59,"page":286,"clip":[24,29.063,410,171.603],"text":"C59.\tA company has created an itemized list of tasks to be \ncompleted by a third-party service provider. After the \nservices are complete, this document will be used to \nvalidate the completion of the services. Which of the \nfollowing would describe this agreement type?\n \n❍A. SLA \n \n❍B. SOW\n \n❍C. NDA\n \n❍D. BPA\nQuick \nAnswer: 289\nThe Details: 350\n","choices":[{"letter":"A","text":"SLA"},{"letter":"B","text":"SOW"},{"letter":"C","text":"NDA"},{"letter":"D","text":"BPA"}],"correct":["B"],"answerPages":[359],"objectives":["5.3"]},{"id":"C60","number":60,"page":286,"clip":[24,173.603,410,319.025],"text":"C60.\tA company is deploying a series of internal applications \nto different cloud providers. Which of the following \nconnection types should be deployed for this \nconfiguration?\n \n❍A. Air-gapped\n \n❍B. 802.1X\n \n❍C. Site-to-site IPsec VPN\n \n❍D. Jump server\n \n❍E. SD-WAN\nQuick \nAnswer: 289\nThe Details: 351\n","choices":[{"letter":"A","text":"Air-gapped"},{"letter":"B","text":"802.1X"},{"letter":"C","text":"Site-to-site IPsec VPN"},{"letter":"D","text":"Jump server"},{"letter":"E","text":"SD-WAN"}],"correct":["E"],"answerPages":[360],"objectives":["3.2"]},{"id":"C61","number":61,"page":286,"clip":[24,321.025,410,437.165],"text":"C61.\tA company is updating components within the control \nplane of their zero-trust implementation. Which of the \nfollowing would be part of this update?\n \n❍A. Policy engine\n \n❍B. Subjects\n \n❍C. Policy enforcement point\n \n❍D. Zone configurations\nQuick \nAnswer: 289\nThe Details: 352\n","choices":[{"letter":"A","text":"Policy engine"},{"letter":"B","text":"Subjects"},{"letter":"C","text":"Policy enforcement point"},{"letter":"D","text":"Zone configurations"}],"correct":["A"],"answerPages":[361],"objectives":["1.2"]},{"id":"C62","number":62,"page":286,"clip":[24,439.165,410,610],"text":"277\nPractice Exam C - Questions\nC62.\tWhich of the following malware types would cause a \nworkstation to participate in a DDoS?\n \n❍A. Bot \n \n❍B. Logic bomb\n \n❍C. Ransomware\n \n❍D. Keylogger\nQuick \nAnswer: 289\nThe Details: 353\n","choices":[{"letter":"A","text":"Bot"},{"letter":"B","text":"Logic bomb"},{"letter":"C","text":"Ransomware"},{"letter":"D","text":"Keylogger"}],"correct":["A"],"answerPages":[362],"objectives":["2.4"]},{"id":"C63","number":63,"page":287,"clip":[24,29.063,410,132.003],"text":"C63.\tWhich of these are used to force the preservation of data \nfor later use in court?\n \n❍A. Chain of custody \n \n❍B. Data loss prevention\n \n❍C. Legal hold\n \n❍D. E-discovery\nQuick \nAnswer: 289\nThe Details: 354\n","choices":[{"letter":"A","text":"Chain of custody"},{"letter":"B","text":"Data loss prevention"},{"letter":"C","text":"Legal hold"},{"letter":"D","text":"E-discovery"}],"correct":["C"],"answerPages":[363],"objectives":["4.8"]},{"id":"C64","number":64,"page":287,"clip":[24,134.003,410,263.343],"text":"C64.\tA company would like to automatically monitor and \nreport on any movement occurring in an open field at the \ndata center. Which of the following would be the BEST \nchoice for this task?\n \n❍A. Bollard\n \n❍B. Microwave sensor\n \n❍C. Access control vestibule\n \n❍D. Fencing\nQuick \nAnswer: 289\nThe Details: 355\n","choices":[{"letter":"A","text":"Bollard"},{"letter":"B","text":"Microwave sensor"},{"letter":"C","text":"Access control vestibule"},{"letter":"D","text":"Fencing"}],"correct":["B"],"answerPages":[364],"objectives":["1.2"]},{"id":"C65","number":65,"page":287,"clip":[24,265.343,410,394.683],"text":"C65.\tA company is releasing a new product, and part of the \nrelease includes  the installation of load balancers to \nthe public web site. Which of the following would best \ndescribe this process?\n \n❍A. Platform diversity\n \n❍B. Capacity planning\n \n❍C. Multi-cloud systems\n \n❍D. Permission restrictions\nQuick \nAnswer: 289\nThe Details: 356\n","choices":[{"letter":"A","text":"Platform diversity"},{"letter":"B","text":"Capacity planning"},{"letter":"C","text":"Multi-cloud systems"},{"letter":"D","text":"Permission restrictions"}],"correct":["B"],"answerPages":[365],"objectives":["3.4"]},{"id":"C66","number":66,"page":287,"clip":[24,396.683,410,610],"text":"278\nPractice Exam C - Questions\nC66.\tA system administrator would like to prove an email \nmessage was sent by a specific person. Which of the \nfollowing describes the verification of this message \nsource?\n \n❍A. Non-repudiation\n \n❍B. Key escrow\n \n❍C. Asymmetric encryption\n \n❍D. Steganography\nQuick \nAnswer: 289\nThe Details: 357\n","choices":[{"letter":"A","text":"Non-repudiation"},{"letter":"B","text":"Key escrow"},{"letter":"C","text":"Asymmetric encryption"},{"letter":"D","text":"Steganography"}],"correct":["A"],"answerPages":[366],"objectives":["1.2"]},{"id":"C67","number":67,"page":288,"clip":[24,29.063,410,145.203],"text":"C67.\tA security administrator has created a policy to alert if a \nuser modifies the hosts file on their system. Which of the \nfollowing behaviors does this policy address?\n \n❍A. Unexpected\n \n❍B. Self-assessment\n \n❍C. Unintentional\n \n❍D. Risky\nQuick \nAnswer: 289\nThe Details: 358\n","choices":[{"letter":"A","text":"Unexpected"},{"letter":"B","text":"Self-assessment"},{"letter":"C","text":"Unintentional"},{"letter":"D","text":"Risky"}],"correct":["D"],"answerPages":[367],"objectives":["5.6"]},{"id":"C68","number":68,"page":288,"clip":[24,147.203,410,302.943],"text":"C68.\tA company has identified a web server data breach \nresulting in the theft of financial records from 150 \nmillion customers. A security update to the company’s \nweb server software was available for two months prior \nto the breach. Which of the following would have \nprevented this breach from occurring?\n \n❍A. Patch management\n \n❍B. Full disk encryption\n \n❍C. Disabling unnecessary services\n \n❍D. Application allow lists\nQuick \nAnswer: 289\nThe Details: 359\n","choices":[{"letter":"A","text":"Patch management"},{"letter":"B","text":"Full disk encryption"},{"letter":"C","text":"Disabling unnecessary services"},{"letter":"D","text":"Application allow lists"}],"correct":["A"],"answerPages":[368],"objectives":["2.5"]},{"id":"C69","number":69,"page":288,"clip":[24,304.943,410,610],"text":"279\nPractice Exam C - Questions\nC69.\tDuring the onboarding process, the IT department \nrequires a list of software applications associated with the \nnew employee's job functions. Which of the following \nwould describe the use of this information?\n \n❍A. Access control configuration\n \n❍B. Encryption settings\n \n❍C. Physical security requirements\n \n❍D. Change management\nQuick \nAnswer: 289\nThe Details: 360\n","choices":[{"letter":"A","text":"Access control configuration"},{"letter":"B","text":"Encryption settings"},{"letter":"C","text":"Physical security requirements"},{"letter":"D","text":"Change management"}],"correct":["A"],"answerPages":[369],"objectives":["5.1"]},{"id":"C70","number":70,"page":289,"clip":[24,29.063,410,284.903],"text":"C70.\tA system administrator has identified an unexpected \nusername on a database server, and the user has been \ntransferring database files to an external server over the \ncompany’s Internet connection. The administrator then \nperformed these tasks:\n• Physically disconnected the Ethernet cable on the \ndatabase server\n• Disabled the unknown account\n• Configured a firewall rule to prevent file transfers from \nthe server\nWhich of the following would BEST describe this part \nof the incident response process?\n \n❍A. Eradication \n \n❍B. Containment\n \n❍C. Lessons learned\n \n❍D. Preparation\nQuick \nAnswer: 289\nThe Details: 361\n","choices":[{"letter":"A","text":"Eradication"},{"letter":"B","text":"Containment"},{"letter":"C","text":"Lessons learned"},{"letter":"D","text":"Preparation"}],"correct":["B"],"answerPages":[370],"objectives":["4.8"]},{"id":"C71","number":71,"page":289,"clip":[24,286.903,410,389.843],"text":"C71.\tWhich of the following would be the MOST effective \nuse of asymmetric encryption?\n \n❍A. Real-time video encryption\n \n❍B. Securely store passwords\n \n❍C. Protect data on mobile devices\n \n❍D. Create a shared session key\nQuick \nAnswer: 289\nThe Details: 362\n","choices":[{"letter":"A","text":"Real-time video encryption"},{"letter":"B","text":"Securely store passwords"},{"letter":"C","text":"Protect data on mobile devices"},{"letter":"D","text":"Create a shared session key"}],"correct":["D"],"answerPages":[371],"objectives":["1.4"]},{"id":"C72","number":72,"page":289,"clip":[24,391.843,410,610],"text":"280\nPractice Exam C - Questions\nC72.\tEach salesperson in a company receives a laptop with \napplications and data to support their sales efforts. The \nIT manager would like to prevent third-parties from \ngaining access to this information if the laptop is stolen. \nWhich of the following would be the BEST way to \nprotect this data?\n \n❍A. Remote wipe\n \n❍B. Full disk encryption\n \n❍C. Biometrics\n \n❍D. VPN\nQuick \nAnswer: 289\nThe Details: 363\n","choices":[{"letter":"A","text":"Remote wipe"},{"letter":"B","text":"Full disk encryption"},{"letter":"C","text":"Biometrics"},{"letter":"D","text":"VPN"}],"correct":["B"],"answerPages":[372],"objectives":["1.4"]},{"id":"C73","number":73,"page":290,"clip":[24,29.063,410,145.203],"text":"C73.\tA security administrator has compiled a list of all \ninformation stored and managed by an organization. \nWhich of the following would best describe this list?\n \n❍A. Sanitization\n \n❍B. Metadata\n \n❍C. Known environment\n \n❍D. Data inventory\nQuick \nAnswer: 289\nThe Details: 364\n","choices":[{"letter":"A","text":"Sanitization"},{"letter":"B","text":"Metadata"},{"letter":"C","text":"Known environment"},{"letter":"D","text":"Data inventory"}],"correct":["D"],"answerPages":[373],"objectives":["5.4"]},{"id":"C74","number":74,"page":290,"clip":[24,147.203,410,263.343],"text":"C74.\tA security administrator would like to monitor all \noutbound Internet connections for malicious software. \nWhich of the following would provide this functionality?\n \n❍A. Jump server\n \n❍B. IPsec tunnel\n \n❍C. Forward proxy\n \n❍D. Load balancer\nQuick \nAnswer: 289\nThe Details: 365\n","choices":[{"letter":"A","text":"Jump server"},{"letter":"B","text":"IPsec tunnel"},{"letter":"C","text":"Forward proxy"},{"letter":"D","text":"Load balancer"}],"correct":["C"],"answerPages":[374],"objectives":["3.2"]},{"id":"C75","number":75,"page":290,"clip":[24,265.343,410,368.283],"text":"C75.\tWhat type of security control would be associated with \ncorporate security policies?\n \n❍A. Technical\n \n❍B. Operational\n \n❍C. Managerial\n \n❍D. Physical\nQuick \nAnswer: 289\nThe Details: 366\n","choices":[{"letter":"A","text":"Technical"},{"letter":"B","text":"Operational"},{"letter":"C","text":"Managerial"},{"letter":"D","text":"Physical"}],"correct":["C"],"answerPages":[375],"objectives":["1.1"]},{"id":"C76","number":76,"page":290,"clip":[24,370.283,410,610],"text":"281\nPractice Exam C - Questions\nC76.\tWhich of the following would be the MOST significant \nsecurity concern when protecting against organized \ncrime?\n \n❍A. Prevent users from posting passwords near  \ntheir workstations \n \n❍B. Require identification cards for all employees  \nand guests\n \n❍C. Maintain reliable backup data\n \n❍D. Use access control vestibules at all data  \ncenter locations\nQuick \nAnswer: 289\nThe Details: 367\n","choices":[{"letter":"A","text":"Prevent users from posting passwords near their workstations"},{"letter":"B","text":"Require identification cards for all employees and guests"},{"letter":"C","text":"Maintain reliable backup data"},{"letter":"D","text":"Use access control vestibules at all data center locations"}],"correct":["C"],"answerPages":[376],"objectives":["2.1"]},{"id":"C77","number":77,"page":291,"clip":[24,29.063,410,198.003],"text":"C77.\tAn application team has been provided with a hardened \nversion of Linux to use with a new application \ninstallation, and this includes installing a web service \nand the application code on the server. Which of the \nfollowing would BEST protect the application  \nfrom attacks?\n \n❍A. Build a backup server for the application \n \n❍B. Run the application in a cloud-based environment\n \n❍C. Implement a secure configuration of the  \nweb service\n \n❍D. Send application logs to the SIEM via syslog\nQuick \nAnswer: 289\nThe Details: 368\n","choices":[{"letter":"A","text":"Build a backup server for the application"},{"letter":"B","text":"Run the application in a cloud-based environment"},{"letter":"C","text":"Implement a secure configuration of the web service"},{"letter":"D","text":"Send application logs to the SIEM via syslog"}],"correct":["C"],"answerPages":[377],"objectives":["2.5"]},{"id":"C78","number":78,"page":291,"clip":[24,200.003,410,355.743],"text":"C78.\tA system administrator has configured MAC filtering \non their corporate access point, but access logs show \nunauthorized users accessing the network. Which of the \nfollowing should the administrator configure to prevent \nfuture unauthorized use?\n \n❍A. Enable WPA3 encryption \n \n❍B. Remove unauthorized MAC addresses from  \nthe filter\n \n❍C. Modify the SSID name\n \n❍D. Modify the channel frequencies\nQuick \nAnswer: 289\nThe Details: 369\n","choices":[{"letter":"A","text":"Enable WPA3 encryption"},{"letter":"B","text":"Remove unauthorized MAC addresses from the filter"},{"letter":"C","text":"Modify the SSID name"},{"letter":"D","text":"Modify the channel frequencies"}],"correct":["A"],"answerPages":[378],"objectives":["4.1"]},{"id":"C79","number":79,"page":291,"clip":[24,357.743,410,610],"text":"282\nPractice Exam C - Questions\nC79.\tA system administrator has been tasked with performing \nan application upgrade, but the upgrade has been delayed \ndue to a different scheduled installation of an outdated \ndevice driver. Which of the following issues would best \ndescribe this change management delay?\n \n❍A. Deny list\n \n❍B. Legacy application\n \n❍C. Dependency\n \n❍D. Restricted activity\nQuick \nAnswer: 289\nThe Details: 370\n","choices":[{"letter":"A","text":"Deny list"},{"letter":"B","text":"Legacy application"},{"letter":"C","text":"Dependency"},{"letter":"D","text":"Restricted activity"}],"correct":["C"],"answerPages":[379],"objectives":["1.3"]},{"id":"C80","number":80,"page":292,"clip":[24,29.063,410,171.603],"text":"C80.\tDuring an initial network connection, a supplicant \ncommunicates to an authenticator, which then sends an \nauthentication request to an Active Directory database. \nWhich of the following would BEST describe this \nauthentication technology?\n \n❍A. Federation \n \n❍B. UTM\n \n❍C. 802.1X\n \n❍D. PKI\nQuick \nAnswer: 289\nThe Details: 371\n","choices":[{"letter":"A","text":"Federation"},{"letter":"B","text":"UTM"},{"letter":"C","text":"802.1X"},{"letter":"D","text":"PKI"}],"correct":["C"],"answerPages":[380],"objectives":["3.2"]},{"id":"C81","number":81,"page":292,"clip":[24,173.603,410,289.743],"text":"C81.\tA security researcher has been notified of a potential \nhardware vulnerability. Which of the following should \nthe researcher evaluate as a potential security issue?\n \n❍A. Firmware versions\n \n❍B. Firewall configuration\n \n❍C. SQL requests\n \n❍D. XSS attachments\nQuick \nAnswer: 289\nThe Details: 372\n","choices":[{"letter":"A","text":"Firmware versions"},{"letter":"B","text":"Firewall configuration"},{"letter":"C","text":"SQL requests"},{"letter":"D","text":"XSS attachments"}],"correct":["A"],"answerPages":[381],"objectives":["2.3"]},{"id":"C82","number":82,"page":292,"clip":[24,291.743,410,610],"text":"283\nPractice Exam C - Questions\nC82.\tVisitors to a corporate data center must enter through \nthe main doors of the building. Which of the following \nsecurity controls would be the BEST choice to \nsuccessfully guide people to the front door? \n(Select TWO)\n \n❍A. Infrared sensors\n \n❍B. Bollards\n \n❍C. Biometrics\n \n❍D. Fencing\n \n❍E. Access badges\n \n❍F. Video surveillance\nQuick \nAnswer: 289\nThe Details: 373\n","choices":[{"letter":"A","text":"Infrared sensors"},{"letter":"B","text":"Bollards"},{"letter":"C","text":"Biometrics"},{"letter":"D","text":"Fencing"},{"letter":"E","text":"Access badges"},{"letter":"F","text":"Video surveillance"}],"correct":["B","D"],"answerPages":[382],"objectives":["1.2"]},{"id":"C83","number":83,"page":293,"clip":[24,29.063,410,171.603],"text":"C83.\tA company's employees are required to authenticate \neach time a file share, printer, or SAN imaging system \nis accessed. Which of the following should be used \nto minimize the number of employee authentication \nrequests?\n \n❍A. SSO\n \n❍B. OSINT\n \n❍C. MFA\n \n❍D. SCAP\nQuick \nAnswer: 289\nThe Details: 374\n","choices":[{"letter":"A","text":"SSO"},{"letter":"B","text":"OSINT"},{"letter":"C","text":"MFA"},{"letter":"D","text":"SCAP"}],"correct":["A"],"answerPages":[383],"objectives":["4.6"]},{"id":"C84","number":84,"page":293,"clip":[24,173.603,410,329.343],"text":"C84.\tA company has recently moved from one accounting \nsystem to another, and the new system includes \nintegration with many other divisions of the \norganization. Which of the following would ensure \nthat the correct access has been provided to the proper \nemployees in each division?\n \n❍A. Geolocation \n \n❍B. Onboarding process\n \n❍C. Account de-provisioning\n \n❍D. Internal self-assessment\nQuick \nAnswer: 289\nThe Details: 375\n","choices":[{"letter":"A","text":"Geolocation"},{"letter":"B","text":"Onboarding process"},{"letter":"C","text":"Account de-provisioning"},{"letter":"D","text":"Internal self-assessment"}],"correct":["D"],"answerPages":[384],"objectives":["5.5"]},{"id":"C85","number":85,"page":293,"clip":[24,331.343,410,610],"text":"284\nPractice Exam C - Questions\nC85.\tAn attacker has circumvented a web-based application \nto send commands directly to a database. Which of the \nfollowing would describe this attack type?\n \n❍A. Downgrade\n \n❍B. SQL injection\n \n❍C. Cross-site scripting\n \n❍D. On-path\nQuick \nAnswer: 289\nThe Details: 376\n","choices":[{"letter":"A","text":"Downgrade"},{"letter":"B","text":"SQL injection"},{"letter":"C","text":"Cross-site scripting"},{"letter":"D","text":"On-path"}],"correct":["B"],"answerPages":[385],"objectives":["2.3"]},{"id":"C86","number":86,"page":294,"clip":[24,29.063,410,158.403],"text":"C86.\tA group of business partners is using blockchain \ntechnology to monitor and track raw materials and parts \nas they are transferred between companies. Where would \na partner find these tracking details?\n \n❍A. Ledger\n \n❍B. HSM\n \n❍C. SIEM\n \n❍D. HIPS\nQuick \nAnswer: 289\nThe Details: 377\n","choices":[{"letter":"A","text":"Ledger"},{"letter":"B","text":"HSM"},{"letter":"C","text":"SIEM"},{"letter":"D","text":"HIPS"}],"correct":["A"],"answerPages":[386],"objectives":[]},{"id":"C87","number":87,"page":294,"clip":[24,160.403,410,342.543],"text":"C87.\tA network technician at a bank has noticed a significant \ndecrease in traffic to the bank's public website. After \nadditional investigation, the technician finds that users \nare being directed to a web site which looks similar to the \nbank's site but is not under the bank's control. Flushing \nthe local DNS cache and changing the DNS entry does \nnot have any effect. Which of the following has most \nlikely occurred?\n \n❍A. DDoS\n \n❍B. Disassociation attack\n \n❍C. Buffer overflow\n \n❍D. Domain hijacking\nQuick \nAnswer: 289\nThe Details: 378\n","choices":[{"letter":"A","text":"DDoS"},{"letter":"B","text":"Disassociation attack"},{"letter":"C","text":"Buffer overflow"},{"letter":"D","text":"Domain hijacking"}],"correct":["D"],"answerPages":[387],"objectives":["2.4"]},{"id":"C88","number":88,"page":294,"clip":[24,344.543,410,610],"text":"285\nPractice Exam C - Questions\nC88.\tA company runs two separate applications in their \ndata center. The security administrator has been tasked \nwith preventing all communication between these \napplications. Which of the following would be the BEST \nway to implement this security requirement?\n \n❍A. Firewall\n \n❍B. SDN\n \n❍C. Air gap\n \n❍D. VLANs\nQuick \nAnswer: 289\nThe Details: 379\n","choices":[{"letter":"A","text":"Firewall"},{"letter":"B","text":"SDN"},{"letter":"C","text":"Air gap"},{"letter":"D","text":"VLANs"}],"correct":["C"],"answerPages":[388],"objectives":["3.1"]},{"id":"C89","number":89,"page":295,"clip":[24,29.063,410,198.003],"text":"C89.\tA receptionist at a manufacturing company recently \nreceived an email from the CEO asking for a copy of \nthe internal corporate employee directory. It was later \ndetermined that the email address was not sent from the \nCEO and the domain associated with the email address \nwas not a corporate domain name. What type of training \ncould help identify this type of attack in the future?\n \n❍A. Recognizing social engineering \n \n❍B. Proper password management\n \n❍C. Securing remote work environments\n \n❍D. Understanding insider threats\nQuick \nAnswer: 289\nThe Details: 380\n","choices":[{"letter":"A","text":"Recognizing social engineering"},{"letter":"B","text":"Proper password management"},{"letter":"C","text":"Securing remote work environments"},{"letter":"D","text":"Understanding insider threats"}],"correct":["A"],"answerPages":[389],"objectives":["5.6"]},{"id":"C90","number":90,"page":295,"clip":[24,200.003,410,610],"text":"286\nPractice Exam C - Questions\nC90.\tWhich of the following deployment models would a \ncompany follow if they require individuals to use their \npersonal phones for work purposes? \n \n❍A. CYOD\n \n❍B. MDM\n \n❍C. BYOD\n \n❍D. COPE\nQuick \nAnswer: 289\nThe Details: 381\n","choices":[{"letter":"A","text":"CYOD"},{"letter":"B","text":"MDM"},{"letter":"C","text":"BYOD"},{"letter":"D","text":"COPE"}],"correct":["C"],"answerPages":[390,391],"objectives":["4.1"]}]}};